INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('f5122217-ed2c-5a74-ab38-2e5ece496419', 'deba481d-c512-5960-ab2e-6709d673e27f', 'c08fb833-5d5e-5a85-a1b1-23f9e1f78bd7', 4, 11, 'እንዲሁም ሴቶች ጭምቶች፥ የማያሙ፥ ልከኞች፥ በነገር ሁሉ የታመኑ ሊሆኑ ይገባቸዋል።'),
  ('8e7a1cf2-ac06-52d0-a211-b0444c3db8ee', 'deba481d-c512-5960-ab2e-6709d673e27f', 'c08fb833-5d5e-5a85-a1b1-23f9e1f78bd7', 5, 12, 'ዲያቆናት ልጆቻቸውንና የራሳቸውን ቤቶች በመልካም እየገዙ እያንዳንዳቸው የአንዲት ሴት ባሎች ይሁኑ።'),
  ('de7bf7b1-abaf-551f-a7ce-1fbb36d841d2', 'deba481d-c512-5960-ab2e-6709d673e27f', 'c08fb833-5d5e-5a85-a1b1-23f9e1f78bd7', 6, 13, 'በዲቁና ሥራ በመልካም ያገለገሉ ለራሳቸው ትልቅ ማዕርግና በክርስቶስ ኢየሱስ ባለው እምነት ብዙ ድፍረት ያገኛሉ።'),
  ('b8dd3824-8d88-5b57-a482-ddea9ef8b584', 'deba481d-c512-5960-ab2e-6709d673e27f', '36117df4-e2e6-527a-a789-51874c11b4d5', 1, 14, 'ፈጥኜ ወደ አንተ እንድመጣ ተስፋ አድርጌ ይህን እጽፍልሃለሁ።'),
  ('82279454-01d7-58fc-a749-f01ccafbefe2', 'deba481d-c512-5960-ab2e-6709d673e27f', '36117df4-e2e6-527a-a789-51874c11b4d5', 2, 15, 'ብዘገይ ግን፥ በእግዚአብሔር ማደሪያ ቤት መኖር እንዴት እንደሚገባ ታውቅ ዘንድ እጽፍልሃለሁ፤ ቤቱም የእውነት ዓምድና መሠረት፥ የሕያው እግዚአብሔር ቤተ ክርስቲያን ነው።'),
  ('0ebb685c-1a84-5e12-ad4d-d8261229b5f2', 'deba481d-c512-5960-ab2e-6709d673e27f', '36117df4-e2e6-527a-a789-51874c11b4d5', 3, 16, 'እግዚአብሔርንም የመምሰል ምሥጢር ያለ ጥርጥር ታላቅ ነው፤'),
  ('28ba20a4-7443-5c9a-a07f-f144b2746b02', 'f3ff6695-f570-5809-a3ef-5dc178dc6624', '6bd7a416-3393-556e-ac67-3752d7866452', 1, 1, 'መንፈስ ግን በግልጥ “በኋለኞች ዘመናት አንዳንዶች የሚያስቱ መናፍስትንና በውሸተኞች ግብዝነት የተሰጠውን የአጋንንትን ትምህርት እያደመጡ፥ ሃይማኖትን ይክዳሉ፤” ይላል፤ በገዛ ሕሊናቸው እንደሚቃጠሉ ደንዝዘው፥'),
  ('13a2409e-abe1-5eb3-a2b9-093e88a670b1', 'f3ff6695-f570-5809-a3ef-5dc178dc6624', '6bd7a416-3393-556e-ac67-3752d7866452', 2, 3, 'እነዚህ ውሸተኞች መጋባትን ይከለክላሉ፤ አምነውም እውነትን የሚያውቁ ከምስጋና ጋር ይቀበሉ ዘንድ እግዚአብሔር ከፈጠረው መብል እንዲርቁ ያዝዛሉ።'),
  ('2ecb96e6-bd8e-55df-a48a-c6b9e4d1589d', 'f3ff6695-f570-5809-a3ef-5dc178dc6624', '6bd7a416-3393-556e-ac67-3752d7866452', 3, 4, 'እግዚአብሔር የፈጠረው ሁሉ መልካም ነውና፥ ከምስጋናም ጋር ቢቀበሉት የሚጣል ምንም የለም፤'),
  ('47b5618b-b807-5789-af4e-a932a49a953f', 'f3ff6695-f570-5809-a3ef-5dc178dc6624', '6bd7a416-3393-556e-ac67-3752d7866452', 4, 5, 'በእግዚአብሔር ቃልና በጸሎት የተቀደሰ ነውና።'),
  ('916babea-16c9-5504-afd1-01cdfb324375', 'f3ff6695-f570-5809-a3ef-5dc178dc6624', '04c2ded4-ba88-5ab9-a5ef-df1461a6a1c1', 1, 6, 'ስለዚህ ወንድሞችን ብታሳስብ፥ በእምነትና በተከተልኸው በመልካም ትምህርት ቃል የምትመገብ የኢየሱስ ክርስቶስ መልካም አገልጋይ ትሆናለህ።'),
  ('45649256-aec9-51cd-ab0a-c1e9447f8a73', 'f3ff6695-f570-5809-a3ef-5dc178dc6624', '04c2ded4-ba88-5ab9-a5ef-df1461a6a1c1', 2, 7, 'ነገር ግን ለዚህ ዓለም ከሚመችና የአሮጊቶችን ሴቶች ጨዋታ ከሚመስለው ተረት ራቅ። እግዚአብሔርን ለመምሰል ግን ራስህን አስለምድ።'),
  ('6389e24a-f1dc-54d4-a9ba-58d73e316d34', 'f3ff6695-f570-5809-a3ef-5dc178dc6624', '04c2ded4-ba88-5ab9-a5ef-df1461a6a1c1', 3, 8, 'ሰውነትን ለሥጋዊ ነገር ማስለመድ ለጥቂት ይጠቅማልና፤ እግዚአብሔርን መምሰል ግን የአሁንና የሚመጣው ሕይወት ተስፋ ስላለው፥ ለነገር ሁሉ ይጠቅማል።'),
  ('fcccc035-8df1-5fa6-a88f-4697438f03a4', 'f3ff6695-f570-5809-a3ef-5dc178dc6624', '04c2ded4-ba88-5ab9-a5ef-df1461a6a1c1', 4, 9, 'ይህ ቃል የታመነ ሁሉም እንዲቀበሉት የተገባ ነው፤'),
  ('b78d0e25-6913-583d-ae85-a06649e63bc7', 'f3ff6695-f570-5809-a3ef-5dc178dc6624', '04c2ded4-ba88-5ab9-a5ef-df1461a6a1c1', 5, 10, 'ይህን ለማግኘት እንደክማለንና፤ ስለዚህም እንሰደባለን፤ ይህም ሰውን ሁሉ ይልቁንም የሚያምኑትን በሚያድን በሕያው አምላክ ተስፋ ስለምናደርግ ነው።'),
  ('41a0535c-c8be-5924-a89a-9cac0121bec1', 'f3ff6695-f570-5809-a3ef-5dc178dc6624', '04c2ded4-ba88-5ab9-a5ef-df1461a6a1c1', 6, 11, 'ይህን እዘዝና አስተምር። በቃልና በኑሮ በፍቅርም በእምነትም በንጽሕናም ለሚያምኑቱ ምሳሌ ሁን እንጂ፥ ማንም ታናሽነትህን አይናቀው።'),
  ('a0551f0e-afe1-570d-af0c-dee94c62a6fd', 'f3ff6695-f570-5809-a3ef-5dc178dc6624', '04c2ded4-ba88-5ab9-a5ef-df1461a6a1c1', 7, 13, 'እስክመጣ ድረስ ለማንበብና ለመምከር ለማስተማርም ተጠንቀቅ።'),
  ('d8e49ec2-142f-5518-ac45-654668f699ea', 'f3ff6695-f570-5809-a3ef-5dc178dc6624', '04c2ded4-ba88-5ab9-a5ef-df1461a6a1c1', 8, 14, 'በትንቢት ከሽማግሌዎች እጅ መጫን ጋር የተሰጠህን በአንተ ያለውን የጸጋ ስጦታ ቸል አትበል።'),
  ('74bd5e56-deef-5380-a3bc-fc8d4f7ddd6e', 'f3ff6695-f570-5809-a3ef-5dc178dc6624', '04c2ded4-ba88-5ab9-a5ef-df1461a6a1c1', 9, 15, 'ማደግህ በነገር ሁሉ እንዲገለጥ ይህን አስብ፤ ይህንም አዘውትር።'),
  ('d41b45cd-0b71-5c98-a5c1-3d96dda8f6e3', 'f3ff6695-f570-5809-a3ef-5dc178dc6624', '04c2ded4-ba88-5ab9-a5ef-df1461a6a1c1', 10, 16, 'ለራስህና ለትምህርትህ ተጠንቀቅ፤ በእነዚህም ጽና፤ ይህን ብታደርግ፥ ራስህንም የሚሰሙህንም ታድናለህና።'),
  ('48f9ef96-a722-530a-a1a0-e6c6b7c43ae4', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 1, 1, 'ሽማግሌ የሆነውን አትገሥጸው፤ እርሱን ግን እንደ አባት፥ ጎበዞችን እንደ ወንድሞች፥ የሸመገሉትን ሴቶች እንደ እናቶች፥ ቆነጃጅቱን እንደ እኅቶች በፍጹም ንጽሕና ለምናቸው።'),
  ('4325a249-3f31-5d05-a5be-449c7b266b79', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 2, 3, 'በእውነት ባልቴቶች የሆኑትን ባልቴቶች አክብር።'),
  ('78770943-0c70-549d-ad9e-a0dedd95e112', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 3, 4, 'ማንም ባልቴት ግን ልጆች ወይም የልጅ ልጆች ቢኖሩአት፥ እነርሱ አስቀድመው ለገዛ ቤተ ሰዎቻቸው እግዚአብሔርን መምሰል ያሳዩ ዘንድ፥ ለወላጆቻቸውም ብድራትን ይመልሱላቸው ዘንድ ይማሩ፤ ይህ በእግዚአብሔር ፊት መልካምና የተወደደ ነውና።'),
  ('7fb7b7c3-1276-5ee1-af61-782ea8d98346', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 4, 5, 'ብቻዋንም ኖራ በእውነት ባልቴት የምትሆን በእግዚአብሔር ተስፋ ታደርጋለች፤ ሌትና ቀንም በልመና በጸሎትም ጸንታ ትኖራለች፤'),
  ('6643bfa8-7a92-522f-a36b-e5e7eae49755', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 5, 6, 'ቅምጥሊቱ ግን በሕይወትዋ ሳለች የሞተች ናት።'),
  ('23b0bef0-9219-595b-a3a9-801a201d5170', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 6, 7, 'ያለ ነቀፋ እንዲሆኑ ይህን ደግሞ እዘዝ።'),
  ('924fd3e5-25e4-5534-ac27-76e6263ef4d0', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 7, 8, 'ነገር ግን ለእርሱ ስለ ሆኑት ይልቁንም ስለ ቤተ ሰዎቹ የማያስብ ማንም ቢሆን፥ ሃይማኖትን የካደ ከማያምንም ሰው ይልቅ የሚከፋ ነው።'),
  ('ee238709-2f54-5196-aa8a-265a1afd27c6', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 8, 9, 'ባልቴት በመዝገብ ብትጻፍ ዕድሜዋ ከስድሳ ዓመት እንዳያንስ፤ የአንድም ባል ሚስት የነበረች እንድትሆን ያስፈልጋል፤'),
  ('aa30bac3-6c11-5fd1-a2e5-f60b3cd60bc0', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 9, 10, 'ልጆችን በማሳደግ፥ እንግዶችንም በመቀበል፥ የቅዱሳንንም እግሮች በማጠብ፥ የተጨነቁትንም በመርዳት፥ በጎንም ሥራ ሁሉ በመከተል፥ ይህን መልካም ሥራ በማድረግ የተመሰከረላት ልትሆን ይገባል።'),
  ('39310179-864d-5888-a19c-1bb6191064a6', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 10, 11, 'ባል የሞተባቸውን ቆነጃጅት ግን አትቀበል፤ በክርስቶስ ላይ ተነሥተው ሲቀማጠሉ ሊያገቡ ይወዳሉና፤'),
  ('fb6c34ce-16e5-57e6-a544-301b678bdbfd', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 11, 12, 'የፊተኛውንም እምነታቸውን ስለ ናቁ ይፈረድባቸዋል፤'),
  ('fc14db59-b256-5b0f-a199-ba75ff517e9c', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 12, 13, 'ከዚህም ጋር ቤት ለቤት እየዞሩ ሥራን መፍታት ደግሞ ይማራሉ፤ የማይገባውንም እየተናገሩ ለፍላፊዎችና በነገር ገቢዎች ይሆናሉ እንጂ፥ ሥራ ፈቶች ብቻ አይደሉም።'),
  ('f5b322a2-6b0d-5a5d-af95-b75f40d6fb29', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 13, 14, 'እንግዲህ ቆነጃጅት ሊያገቡ፥ ልጆችንም ሊወልዱ፥ ቤቶቻቸውንም ሊያስተዳድሩ፥ ተቃዋሚውም የሚሳደብበትን አንድን ምክንያት ስንኳ እንዳይሰጡ እፈቅዳለሁ፤'),
  ('fe00dc86-0a4c-583a-ab71-8178826158a0', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 14, 15, 'ከአሁን በፊት አንዳንዶች ሰይጣንን እንዲከተሉ ፈቀቅ ብለዋልና።'),
  ('5b81f109-503d-5662-a0cc-da07ed2105c5', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 15, 16, 'ባልቴቶች ያሉት የሚያምን ቢሆን ወይም የምታምን ብትሆን፥ ይርዱአቸው፤ ቤተ ክርስቲያንም እውነተኞችን ባልቴቶች እንድትረዳ አይክበዱባት።'),
  ('6454c3d2-4aaa-5d17-a6f6-410932c28628', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 16, 17, 'በመልካም የሚያስተዳድሩ ሽማግሌዎች፥ ይልቁንም በመስበክና በማስተማር የሚደክሙት፥ እጥፍ ክብር ይገባቸዋል።'),
  ('b00769be-e10c-53ad-af7f-edb63b374681', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 17, 18, 'መጽሐፍ “የሚያበራየውን በሬ አፉን አትሰር፤” ደግሞ “ለሠራተኛ ደመወዙ ይገባዋል፤” ይላልና።'),
  ('a1058e73-e4c9-5a6e-ac99-7c79ee41e453', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 18, 19, 'ከሁለት ወይም ከሦስት ምስክር በቀር በሽማግሌ ላይ ክስ አትቀበል።'),
  ('02792569-5cf5-572d-abd3-c2f0a3a452b0', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 19, 20, 'ሌሎቹ ደግሞ እንዲፈሩ፥ ኀጢአት የሚሠሩትን በሁሉ ፊት ገሥጻቸው።'),
  ('f3812792-8587-58a2-a893-4245848c989a', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 20, 21, 'አንድን እንኳ በአድልዎ ሳታደርግ፥ እነዚህን ያለ ማዘንበል እንድትጠብቅ በእግዚአብሔርና በጌታ በኢየሱስ ክርስቶስ በተመረጡትም መላእክት ፊት እመክርሃለሁ።'),
  ('d56aa24b-700f-532f-ac24-caddcb93a463', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 21, 22, 'በማንም ላይ ፈጥነህ እጆችህን አትጫን፤ በሌሎችም ኀጢአት አትተባበር፤ ራስህን በንጽህና ጠብቅ።'),
  ('1579b003-6e7a-5972-a6be-3b7c0f6dd5eb', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 22, 23, 'ስለ ሆድህና ስለ በሽታህ ብዛት ጥቂት የወይን ጠጅ ጠጣ እንጂ፥ ወደ ፊት ውሃ ብቻ አትጠጣ።'),
  ('17c71e21-c249-530a-a987-ad309157c626', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 23, 24, 'የአንዳንዶች ሰዎች ኀጢአት የተገለጠ ነው፤ ፍርድንም ያመለክታል፤ ሌሎችን ግን ይከተላቸዋል፤'),
  ('b8d6dfd5-3656-545e-af0a-d3c977511847', 'b3302d04-4ac2-5142-a60b-b1413f588890', '671df879-ff96-5402-a9ec-fef9766e72fe', 24, 25, 'እንዲሁ መልካም ሥራ ደግሞ የተገለጠ ነው፤ ያልተገለጠም ከሆነ ሊሰወር አይችልም።'),
  ('322213cf-5797-55bc-af38-7c58f5c97641', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', 'c93736a5-ff7b-5b9e-a625-e7ad6eb7a20b', 1, 1, 'የእግዚአብሔር ስምና ትምህርቱ አንዳይሰደብ፥ ከቀንበር በታች ያሉቱ ባሪያዎች ሁሉ ለገዙአቸው ጌቶች ክብር ሁሉ እንደ ተገባቸው ይቍጠሩአቸው።'),
  ('73ec82bf-cda5-58de-a524-773d8c04ba01', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', 'c93736a5-ff7b-5b9e-a625-e7ad6eb7a20b', 2, 2, 'የሚያምኑም ጌቶች ያሉአቸው፥ ወንድሞች ስለ ሆኑ አይናቁአቸው፤ ነገር ግን በመልካም ሥራቸው የሚጠቅሙ የሚያምኑና የተወደዱ ስለ ሆኑ፥ ከፊት ይልቅ ያገልግሉ።'),
  ('2d52aaa5-41fd-55aa-a86d-fa466d984bfb', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', 'cdb67098-73f9-5eeb-a4d1-66a0d42d0568', 1, 3, 'እነዚህን አስተምርና ምከር። ማንም ልዩ ትምህርት የሚያስተምር ከጌታችንም ከኢየሱስ ክርስቶስ በሆነው ጤናማ ቃልና እግዚአብሔርን ለመምሰል በሚስማማ ትምህርት የማይጠጋ ቢሆን፥'),
  ('77d420aa-258a-522a-aa9e-cbb9a3c5732b', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', 'cdb67098-73f9-5eeb-a4d1-66a0d42d0568', 2, 4, 'በትዕቢት ተነፍቶአል፤ አንዳችም አያውቅም፤ ነገር ግን ምርመራን በቃልም መዋጋትን እንደ በሽተኛ ይናፍቃል፤ ከእነዚህም ቅንዓትና ክርክር ስድብም ክፉ አሳብም እርስ በርስ መናደድም ይወጣሉ፤ አእምሮአቸውም በጠፋባቸው እውነትንም በተቀሙ፥ እግዚአብሔርን መምሰል ማትረፊያ የሚሆን በመሰላቸው ሰዎች ይገኛሉ። እንደነዚህ ካሉት ራቅ።'),
  ('ce0a0be8-a4c3-5f0a-aa88-c9e54db62095', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', 'cdb67098-73f9-5eeb-a4d1-66a0d42d0568', 3, 6, '“ኑሮዬ ይበቃኛል፤” ለሚለው ግን እግዚአብሔርን መምሰል እጅግ ማትረፊያ ነው፤'),
  ('d4796573-96d6-5945-a2e6-7022fa740aef', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', 'cdb67098-73f9-5eeb-a4d1-66a0d42d0568', 4, 7, 'ወደ ዓለም ምንም እንኳ አላመጣንምና፤'),
  ('8f777f0a-63a3-52d5-a9f3-e54f853b540d', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', 'cdb67098-73f9-5eeb-a4d1-66a0d42d0568', 5, 8, 'አንዳችንም ልንወስድ አይቻለንም፤ ምግብና ልብስ ከኖረን ግን እርሱ ይበቃናል።'),
  ('c3ccb85c-a1a1-59ae-a7ba-611a95baef11', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', 'cdb67098-73f9-5eeb-a4d1-66a0d42d0568', 6, 9, 'ዳሩ ግን ባለ ጠጎች ሊሆኑ የሚፈልጉ በጥፋትና በመፍረስ ሰዎችን በሚያሰጥምና በሚያሰንፍ በሚጎዳም በብዙ ምኞትና በፈተና በወጥመድም ይወድቃሉ።'),
  ('a804b3a7-572b-53a9-a39d-22796ffa0338', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', 'cdb67098-73f9-5eeb-a4d1-66a0d42d0568', 7, 10, 'ገንዘብን መውደድ የክፋት ሁሉ ሥር ነውና፤ አንዳንዶች ይህን ሲመኙ ከሃይማኖት ተሳስተው በብዙ ሥቃይ ራሳቸውን ወጉ።'),
  ('18ea55fb-6da2-5b98-a154-bc49377e0469', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', '15b976c4-16eb-59a5-a780-0cdda37926d7', 1, 11, 'አንተ ግን የእግዚአብሔር ሰው ሆይ! ከዚህ ሽሽ፤ ጽድቅንና እግዚአብሔርን መምሰል እምነትንም ፍቅርንም መጽናትንም የዋህነትንም ተከታተል።'),
  ('c8ef9e6f-8ce4-5f6a-a3b7-20f7024a454a', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', '15b976c4-16eb-59a5-a780-0cdda37926d7', 2, 12, 'መልካሙን የእምነት ገድል ተጋደል፤ የተጠራህለትንም በብዙም ምስክሮች ፊት በመልካም መታመን የታመንህለትን የዘላለምን ሕይወት ያዝ።'),
  ('ae747242-080a-53d5-ab87-f040a9cf9db8', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', '15b976c4-16eb-59a5-a780-0cdda37926d7', 3, 13, 'ሁሉን በሕይወት በሚጠብቅ በእግዚአብሔር ፊት፥ በጴንጤናዊውም በጲላጦስ ዘንድ መልካሙን መታመን በመሰከረ በክርስቶስ ኢየሱስ ፊት አዝሃለሁ፤'),
  ('f23b5567-db09-5000-a1da-81780cfc27a2', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', '15b976c4-16eb-59a5-a780-0cdda37926d7', 4, 14, 'ጌታችን ኢየሱስ ክርስቶስ እስኪገለጥ ድረስ ያለ እድፍና ያለ ነቀፋ ሆነህ ትእዛዙን ጠብቅ፤'),
  ('f9206724-3cbd-5902-aa10-2f86b0e12c9e', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', '15b976c4-16eb-59a5-a780-0cdda37926d7', 5, 15, 'ያንም መገለጡን በራሱ ጊዜ ብፁዕና ብቻውን የሆነ ገዥ፥ የነገሥታት ንጉሥና የጌቶች ጌታ ያሳያል።'),
  ('a91f2e75-918c-53f0-aaf9-cb34fbf7ed51', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', '15b976c4-16eb-59a5-a780-0cdda37926d7', 6, 16, 'እርሱ ብቻ የማይሞት ነው፤ ማንም ሊቀርበው በማይችል ብርሃን ይኖራል፤ አንድ ሰው እንኳ አላየውም፤ ሊያይም አይቻለውም፤ ለእርሱ ክብርና የዘላለም ኀይል ይሁን፤ አሜን።'),
  ('2b732962-856e-5735-a503-0d3e758dfa3b', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', '15b976c4-16eb-59a5-a780-0cdda37926d7', 7, 17, 'በአሁኑ ዘመን ባለ ጠጎች የሆኑት የትዕቢትን ነገር እንዳያስቡ ደስም እንዲለን ሁሉን አትርፎ በሚሰጠን በሕያው እግዚአብሔር እንጂ፥ በሚያልፍ ባለ ጠግነት ተስፋ እንዳያደርጉ እዘዛቸው።'),
  ('c48f449a-9e0d-5935-a026-a49236cd8672', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', '15b976c4-16eb-59a5-a780-0cdda37926d7', 8, 18, 'እውነተኛውን ሕይወት ይይዙ ዘንድ፥ ለሚመጣው ዘመን ለራሳቸው መልካም መሠረት የሚሆንላቸውን መዝገብ እየሰበሰቡ መልካምን እንዲያደርጉ፤ በበጎም ሥራ ባለ ጠጎች እንዲሆኑ፤ ሊረዱና ሊያካፍሉም የተዘጋጁ እንዲሆኑ ምከራቸው።'),
  ('72954816-ace4-5077-ac8e-758f176c6a87', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', '15b976c4-16eb-59a5-a780-0cdda37926d7', 9, 20, 'ጢሞቴዎስ ሆይ! በውሸት እውቀት ከተባለ ለዓለም ከሚመች ከከንቱ መለፍለፍና መከራከር እየራቅህ የተሰጠህን አደራ ጠብቅ፤'),
  ('a8ffe452-a803-5e48-a747-c283b11dc857', '9ebcd5ba-0521-5400-a420-7bf2a1fb6029', '15b976c4-16eb-59a5-a780-0cdda37926d7', 10, 21, 'ይህ እውቀት አለን ብለው አንዳንዶች ስለ እምነት ስተዋልና። ጸጋ ከአንተ ጋር ይሁን።'),
  ('2cc6a41d-6ba8-5a7a-a8f0-7bbad32f556c', 'c71bccc1-0a2d-5d7d-a7df-21b62e941b07', '8042d7a3-1d79-5ba1-af68-232277770a4e', 1, 1, 'በክርስቶስ ኢየሱስ እንደሚሆን የሕይወት ተስፋ፥ በእግዚአብሔር ፈቃድ የኢየሱስ ክርስቶስ ሐዋርያ የሆነ ጳውሎስ፤'),
  ('96018707-fe2d-5889-a6ab-e4f5ae63d851', 'c71bccc1-0a2d-5d7d-a7df-21b62e941b07', '8042d7a3-1d79-5ba1-af68-232277770a4e', 2, 2, 'ለተወደደው ልጄ ለጢሞቴዎስ፤ ከእግዚአብሔር አብ ከጌታችንም ከክርስቶስ ኢየሱስ ጸጋና ምሕረት ሰላምም ይሁን።'),
  ('036a3a3e-1335-5794-aa8d-294aec04ad55', 'c71bccc1-0a2d-5d7d-a7df-21b62e941b07', '85ca3eef-d1dc-56ac-a1bf-501a45754375', 1, 3, 'ሌትና ቀን በልመናዬ ሳላቋርጥ ስለማስብህ እንደ አባቶቼ አድርጌ በንጹሕ ሕሊና የማመልከውን እግዚአብሔርን አመሰግናለሁ፤'),
  ('ed108f20-8396-57ea-a189-8259ebea03f0', 'c71bccc1-0a2d-5d7d-a7df-21b62e941b07', '85ca3eef-d1dc-56ac-a1bf-501a45754375', 2, 4, 'እንባህን እያሰብሁ በደስታ እሞላ ዘንድ ላይህ እናፍቃለሁ።'),
  ('5ec41a2a-a86a-5d7b-af57-aa65f0538dd1', 'c71bccc1-0a2d-5d7d-a7df-21b62e941b07', '85ca3eef-d1dc-56ac-a1bf-501a45754375', 3, 5, 'በአንተ ያለውን ግብዝነት የሌለበትን እምነትህን አስባለሁ፤ ይህም እምነት ቀድሞ በአያትህ በሎይድ በእናትህም በኤውንቄ ነበረባቸው፤ በአንተም ደግሞ እንዳለ ተረድቼአለሁ።'),
  ('c83438f3-b0a3-55f1-af1c-127c1a8e8c15', 'c71bccc1-0a2d-5d7d-a7df-21b62e941b07', '85ca3eef-d1dc-56ac-a1bf-501a45754375', 4, 6, 'ስለዚህ ምክንያት እሳት እንደሚያቀጣጥል ሰው እጆቼን በመጫኔ በአንተ ያለውን የእግዚአብሔርን ስጦታ እንድታነሣሣ አሳስብሃለሁ።'),
  ('9e21e04f-3410-51a8-ac43-104006cbbd74', 'c71bccc1-0a2d-5d7d-a7df-21b62e941b07', '85ca3eef-d1dc-56ac-a1bf-501a45754375', 5, 7, 'እግዚአብሔር የኀይልና የፍቅር ራስንም የመግዛት መንፈስ እንጂ የፍርሃት መንፈስ አልሰጠንምና።'),
  ('42abc4e8-4f15-5083-a796-8196f1a92682', 'c71bccc1-0a2d-5d7d-a7df-21b62e941b07', '85ca3eef-d1dc-56ac-a1bf-501a45754375', 6, 8, 'እንግዲህ በጌታችን ምስክርነት ወይም በእስረኛው በእኔ አትፈር፤ ነገር ግን እንደ እግዚአብሔር ኀይል መጠን ስለ ወንጌል አብረኸኝ መከራን ተቀበል፤'),
  ('47d56cc4-f93b-5e99-a02d-6fa4db2cd65e', 'c71bccc1-0a2d-5d7d-a7df-21b62e941b07', '85ca3eef-d1dc-56ac-a1bf-501a45754375', 7, 9, 'ያዳነን በቅዱስም አጠራር የጠራን እግዚአብሔር ነውና፤ ይህም እንደ ራሱ አሳብና ጸጋ መጠን ነው እንጂ፥ እንደ ሥራችን መጠን አይደለም፤ ይህም ጸጋ ከዘላለም ዘመናት በፊት በክርስቶስ ኢየሱስ ተሰጠን፤'),
  ('944f5dcd-49a1-5734-adb2-dc1dde7ee511', 'c71bccc1-0a2d-5d7d-a7df-21b62e941b07', '85ca3eef-d1dc-56ac-a1bf-501a45754375', 8, 10, 'አሁን ግን በመድኃኒታችን በኢየሱስ ክርስቶስ መገለጥ ታይቶአል። እርሱ ሞትን ሽሮአልና፤ እኔ ሰባኪና ሐዋርያ አሕዛብንም አስተማሪ እንድሆን በተሾምሁበት በወንጌል ሕይወትንና አለመጥፋትን ወደ ብርሃን አውጥቶአል።'),
  ('2234f30a-07fe-5b08-a388-3c292eb099af', 'c71bccc1-0a2d-5d7d-a7df-21b62e941b07', '85ca3eef-d1dc-56ac-a1bf-501a45754375', 9, 12, 'ስለዚህም ምክንያት ይህን መከራ ደግሞ ተቀብዬአለሁ፤ ነገር ግን አላፍርበትም፤ ያመንሁትን አውቃለሁና፤ የሰጠሁትንም አደራ እስከዚያ ቀን ድረስ ሊጠብቅ እንዲችል ተረድቼአለሁ።'),
  ('d0d350d1-b352-5ba3-a4b2-5b35f65e2a3c', 'c71bccc1-0a2d-5d7d-a7df-21b62e941b07', '85ca3eef-d1dc-56ac-a1bf-501a45754375', 10, 13, 'በክርስቶስ ኢየሱስ ባለ እምነትና ፍቅር አድርገህ፥ ከእኔ የሰማኸውንም ጤናማ ቃል ምሳሌ ያዝ፤'),
  ('00becf8f-f963-5838-ada9-f83ff6864a61', 'c71bccc1-0a2d-5d7d-a7df-21b62e941b07', '85ca3eef-d1dc-56ac-a1bf-501a45754375', 11, 14, 'መልካሙን አደራ በእኛ በሚኖረው በመንፈስ ቅዱስ ጠብቅ።'),
  ('568c6dd9-69db-5a67-acef-f03bf22283da', 'c71bccc1-0a2d-5d7d-a7df-21b62e941b07', '85ca3eef-d1dc-56ac-a1bf-501a45754375', 12, 15, 'በእስያ ያሉቱ ሁሉ ከእኔ ፈቀቅ እንዳሉ ታውቃለህ፤ ከእነርሱም ፊሎጎስና ሄርዋጌኔስ ናቸው።'),
  ('3c122573-60d1-58be-a965-795f42ae28f7', 'c71bccc1-0a2d-5d7d-a7df-21b62e941b07', '85ca3eef-d1dc-56ac-a1bf-501a45754375', 13, 16, 'ጌታ ልሄኔሲፎሩ ቤተ ሰዎች ምሕረትን ይስጥ፤ ብዙ ጊዜ አሳርፎኛልና፤'),
  ('7eb71e19-68c6-5e98-a19a-76abc14e8c2a', 'c71bccc1-0a2d-5d7d-a7df-21b62e941b07', '85ca3eef-d1dc-56ac-a1bf-501a45754375', 14, 17, 'በሰንሰለቴም አላፈረበትም፤ ነገር ግን በሮሜ ባደረ ጊዜ ፈልጎ ፈልጎ አገኘኝ፤'),
  ('ebac26ea-b877-5c8f-a13b-282525ff511e', 'c71bccc1-0a2d-5d7d-a7df-21b62e941b07', '85ca3eef-d1dc-56ac-a1bf-501a45754375', 15, 18, 'በዚያን ቀን ከጌታ ምሕረትን እንዲያገኝ ጌታ ይስጠው፤ በኤፌሶንም እንዴት እንዳገለገለኝ አንተ በደኅና ታውቃለህ።'),
  ('8694af35-4e49-5a4a-a252-63b8a954e8ae', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '8043dc49-f9a5-55c0-a1fb-166a54f7f137', 1, 1, 'እንግዲህ ልጄ ሆይ! አንተ በክርስቶስ ኢየሱስ ባለው ጸጋ በርታ።'),
  ('c56953c5-fa58-5d58-a699-19329e78469b', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '8043dc49-f9a5-55c0-a1fb-166a54f7f137', 2, 2, 'ብዙ ሰዎች የመሰከሩለትን ከእኔም የሰማኸውን ሌሎችን ደግሞ ሊያስተምሩ ለሚችሉ ለታመኑ ሰዎች አደራ ስጥ።'),
  ('e3873243-563b-5e74-aa54-5a8228c0d15a', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '8043dc49-f9a5-55c0-a1fb-166a54f7f137', 3, 3, 'እንደ ኢየሱስ ክርስቶስ በጎ ወታደር ሆነህ፥ አብረኸኝ መከራ ተቀበል።'),
  ('ee5e27c5-45a3-5106-a573-694f5672f4d3', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '8043dc49-f9a5-55c0-a1fb-166a54f7f137', 4, 4, 'የሚዘምተው ሁሉ ለጦር ያስከተተውን ደስ ያሰኝ ዘንድ ትዳር በሚገኝበት ንግድ ራሱን አያጠላልፍም።'),
  ('4f67d099-0f32-546d-ae50-db11ec939d18', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '8043dc49-f9a5-55c0-a1fb-166a54f7f137', 5, 5, 'ደግሞም በጨዋታ የሚታገል ማንም ቢሆን፥ እንደሚገባ አድርጎ ባይታገል፥ የድሉን አክሊል አያገኝም።'),
  ('28f83571-7b07-5e68-a73d-272983426e97', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '8043dc49-f9a5-55c0-a1fb-166a54f7f137', 6, 6, 'የሚደክመው ገበሬ ፍሬውን ከሚበሉት መጀመሪያ እንዲሆን ይገባዋል።'),
  ('21eb101d-6c57-53df-a60f-e1b6bf333f80', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '8043dc49-f9a5-55c0-a1fb-166a54f7f137', 7, 7, 'የምለውን ተመልከት፤ ጌታም በነገር ሁሉ ማስተዋልን ይስጥህ።'),
  ('88c8a87d-0b1b-5fdb-ab1a-b47a506f00de', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '8043dc49-f9a5-55c0-a1fb-166a54f7f137', 8, 8, 'በወንጌል እንደምሰብከው፥ ከሙታን የተነሣውን፥ ከዳዊት ዘርም የሆነውን ኢየሱስ ክርስቶስን አስብ።'),
  ('539330cd-6fc7-5a68-a123-5b766751ab5d', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '8043dc49-f9a5-55c0-a1fb-166a54f7f137', 9, 9, 'ይህንም በመስበክ እንደ ክፉ አድራጊ እስክታሰር ድረስ መከራ እቀበላለሁ፤ የእግዚአብሔር ቃል ግን አይታሰርም።'),
  ('14b4b1c0-a339-5d8c-acba-dd9c2f7433db', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '8043dc49-f9a5-55c0-a1fb-166a54f7f137', 10, 10, 'ስለዚህ እነርሱ ደግሞ በክርስቶስ ኢየሱስ ያለውን መዳን ከዘላለም ክብር ጋር እንዲያገኙ ስለ ተመረጡት በነገር ሁሉ እጸናለሁ።'),
  ('feea9cdd-d199-5191-adc6-24a73d1b29e0', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '8043dc49-f9a5-55c0-a1fb-166a54f7f137', 11, 11, 'እንዲህ የሚለው ቃሉ የታመነ ነው'),
  ('9a877699-68f6-5c9d-adeb-d358694687c0', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '8043dc49-f9a5-55c0-a1fb-166a54f7f137', 12, 12, 'ብንጸና፥ ከእርሱ ጋር ደግሞ እንነግሣለን፤'),
  ('1351bf25-1344-51b7-a081-cbfcca589566', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '8043dc49-f9a5-55c0-a1fb-166a54f7f137', 13, 13, 'ባናምነው፥ እርሱ የታመነ ሆኖ ይኖራል፤ ራሱን ሊክድ አይችልምና።”'),
  ('1ace972a-1626-551f-a051-094dfbe76322', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '65b27a9c-abf1-5c69-a0fe-9cff7bc7a96e', 1, 14, 'ይህን አሳስባቸው፤ በቃልም እንዳይጣሉ በእግዚአብሔር ፊት ምከራቸው፤ ይህ ምንም የማይረባ የሚሰሙትንም የሚያፈርስ ነውና።'),
  ('e1678a6a-aab4-5448-a2e6-ff0a5a7a3f2d', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '65b27a9c-abf1-5c69-a0fe-9cff7bc7a96e', 2, 15, 'የእውነትን ቃል በቅንነት የሚናገር የማያሳፍርም ሠራተኛ ሆነህ፥ የተፈተነውን ራስህን ለእግዚአብሔር ልታቀርብ ትጋ።'),
  ('53937978-5820-5564-abad-1edf7e5fe245', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '65b27a9c-abf1-5c69-a0fe-9cff7bc7a96e', 3, 16, 'ነገር ግን ለዓለም ከሚመች ከከንቱ መለፍለፍ ራቅ፤ ኀጢአተኝነታቸውን ከፊት ይልቅ ይጨምራሉና፤'),
  ('17bb2cad-c880-5240-ad3b-0951b2b14f95', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '65b27a9c-abf1-5c69-a0fe-9cff7bc7a96e', 4, 17, 'ቃላቸውም እንደ ጭንቁር ይባላል፤ ከእነርሱም ሄሜኔዎስና ፊሊጦስ ናቸው፤'),
  ('756e5685-368c-5919-aaaa-d287a9e1c43c', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '65b27a9c-abf1-5c69-a0fe-9cff7bc7a96e', 5, 18, 'እነዚህም “ትንሣኤ ከአሁን በፊት ሆኖአል፤” እያሉ ስለ እውነት ስተው የአንዳንዶችን እምነት ይገለብጣሉ።'),
  ('5ebd2051-b411-5abd-a31e-edebd4e1b2ce', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '65b27a9c-abf1-5c69-a0fe-9cff7bc7a96e', 6, 19, 'ሆኖም “ጌታ ለእርሱ የሆኑትን ያውቃል፤” ደግሞም “የጌታን ስም የሚጠራ ሁሉ ከዐመፅ ይራቅ፤” የሚለው ማኅተም ያለበት የተደላደለ የእግዚአብሔር መሠረት ቆሞአል።'),
  ('1e7c272f-8deb-5bd2-a85a-c9e928649646', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '65b27a9c-abf1-5c69-a0fe-9cff7bc7a96e', 7, 20, 'በትልቅም ቤት የእንጨትና የሸክላ ዕቃ ደግሞ አለ እንጂ የወርቅና የብር ዕቃ ብቻ አይደለም፤ እኵሌቶቹም ለክብር፥ እኵሌቶቹም ለውርደት ይሆናሉ፤'),
  ('f5df7585-a26e-51fb-ac4b-eeffaec6b45d', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '65b27a9c-abf1-5c69-a0fe-9cff7bc7a96e', 8, 21, 'እንግዲህ ማንም ራሱን ከእነዚህ ቢያነጻ፥ ለክብር የሚሆን የተቀደሰም ለጌታውም የሚጠቅም ለበጎም ሥራ ሁሉ የተዘጋጀ ዕቃ ይሆናል።'),
  ('b734cb1a-3bb7-5825-aa35-d910e6ad5a4f', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '65b27a9c-abf1-5c69-a0fe-9cff7bc7a96e', 9, 22, 'ከክፉ የጎልማሳነት ምኞት ግን ሽሽ፤ በንጹሕም ልብ ጌታን ከሚጠሩ ጋር ጽድቅን እምነትን ፍቅርን ሰላምን አጥብቀህ ተከተል።'),
  ('f29dba80-8c4e-5b73-a120-e679afd0bfef', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '65b27a9c-abf1-5c69-a0fe-9cff7bc7a96e', 10, 23, 'ነገር ግን ጠብን እንዲያመጣ አውቀህ ከሰነፎችና ካልተማሩ ምርመራ ራቅ፤'),
  ('167285e9-6bfb-5e12-a8f7-65c392761fa8', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '65b27a9c-abf1-5c69-a0fe-9cff7bc7a96e', 11, 24, 'የጌታም ባሪያ ለሰው ሁሉ ገር፥ ለማስተማርም የሚበቃ፥ ለትዕግሥትም የሚጸና ሊሆን እንጂ ሊጣላ አይገባውም።'),
  ('acc65794-553a-5ccd-a5d5-a7e019511fbd', '34b5f85f-6187-5bbe-a9f0-3593318ccc82', '65b27a9c-abf1-5c69-a0fe-9cff7bc7a96e', 12, 25, 'ደግሞም “ምናልባት እግዚአብሔር እውነትን ያውቁ ዘንድ ንስሓን ይሰጣቸዋልና ፈቃዱን ለማድረግ በዲያብሎስ ሕያዋን ሆነው ከተያዙበት ወጥመድ ወጥተው ወደ አእምሮ ይመለሳሉ፤” ብሎ የሚቃወሙትን በየዋህነት ይቅጣ።'),
  ('5dcb8b08-7a40-560a-a3c6-1f0b6aa29884', 'b505cb49-84e7-5f7c-a38c-83609507b34a', '8162aa9c-4622-5d65-a97d-2d8bff7c5ee7', 1, 1, 'ነገር ግን በመጨረሻው ቀን የሚያስጨንቅ ዘመን እንዲመጣ ይህን እወቅ።'),
  ('ab4d5a1a-d608-585c-a5c5-6589bc7e8d20', 'b505cb49-84e7-5f7c-a38c-83609507b34a', '8162aa9c-4622-5d65-a97d-2d8bff7c5ee7', 2, 2, 'ሰዎች ራሳቸውን የሚወዱ ይሆናሉና፤ ገንዘብን የሚወዱ፥ ትምክህተኞች፥ ትዕቢተኞች፥ ተሳዳቢዎች፥ ለወላጆቻቸው የማይታዘዙ፥ የማያመሰግኑ፥ ቅድስና የሌላቸው፥'),
  ('8bbcdd88-9512-5fc8-a0dd-898466f96150', 'b505cb49-84e7-5f7c-a38c-83609507b34a', '8162aa9c-4622-5d65-a97d-2d8bff7c5ee7', 3, 3, 'ፍቅር የሌላቸው፥ ዕርቅን የማይሰሙ፥ ሐሜተኞች፥ ራሳቸውን የማይገዙ፥ ጨካኞች፥ መልካም የሆነውን የማይወዱ፥'),
  ('39e20b96-6ee3-5736-ab28-667439439ddb', 'b505cb49-84e7-5f7c-a38c-83609507b34a', '8162aa9c-4622-5d65-a97d-2d8bff7c5ee7', 4, 4, 'ከዳተኞች፥ ችኩሎች፥ በትዕቢት የተነፉ፥ ከእግዚአብሔር ይልቅ ተድላን የሚወዱ ይሆናሉ፤'),
  ('10741da1-2a74-58c5-a370-b1d55b3c03ae', 'b505cb49-84e7-5f7c-a38c-83609507b34a', '8162aa9c-4622-5d65-a97d-2d8bff7c5ee7', 5, 5, 'የአምልኮት መልክ አላቸው፤ ኀይሉን ግን ክደዋል፤ ከእነዚህ ደግሞ ራቅ።'),
  ('c3757af6-e730-533f-ae87-e8ee153cb263', 'b505cb49-84e7-5f7c-a38c-83609507b34a', '8162aa9c-4622-5d65-a97d-2d8bff7c5ee7', 6, 6, 'ወደ ቤቶች ሾልከው እየገቡ ኀጢአታቸው የተከመረባቸውን በልዩ ልዩ ምኞትም የሚወሰዱትን ሁልጊዜም እየተማሩ እውነትን ወደ ማወቅ ሊደርሱ ከቶ የማይችሉትን ሞኞችን ሴቶች የሚማርኩ፥ ከእነዚህ ዘንድ ናቸውና።'),
  ('383170f3-54fe-5667-aa3f-329922b00623', 'b505cb49-84e7-5f7c-a38c-83609507b34a', '8162aa9c-4622-5d65-a97d-2d8bff7c5ee7', 7, 8, 'ኢያኔስና ኢያንበሬስም ሙሴን እንደ ተቃወሙት፥ እንዲሁ እነዚህ ደግሞ አእምሮአቸው የጠፋባቸው ስለ እምነትም የተጣሉ ሰዎች ሆነው እውነትን ይቃወማሉ።'),
  ('58ad00cc-bd55-53a0-a7bd-b1b9bce50952', 'b505cb49-84e7-5f7c-a38c-83609507b34a', '8162aa9c-4622-5d65-a97d-2d8bff7c5ee7', 8, 9, 'ዳሩ ግን የእነዚያ ሞኝነት ደግሞ ግልጥ እንደ ሆነ፥ ሞኝነታቸው ለሁሉ ይገለጣልና ከፊት ይልቅ አይቀናላቸውም።'),
  ('6c4db3cd-710a-5bd3-a75e-f77eb08100ea', 'b505cb49-84e7-5f7c-a38c-83609507b34a', '45c3cae2-8472-5768-a42c-57bb3e0e0e1b', 1, 10, 'አንተ ግን ትምህርቴንና አካሄዴን አሳቤንም እምነቴንም ትዕግሥቴንም ፍቅሬንም መጽናቴንም'),
  ('3f35fe42-1412-537c-a8c0-4945c9d7ac32', 'b505cb49-84e7-5f7c-a38c-83609507b34a', '45c3cae2-8472-5768-a42c-57bb3e0e0e1b', 2, 11, 'ስደቴንም መከራዬንም ተከተልህ፤ በአንጾኪያና በኢቆንዮን በልስጥራንም የሆነብኝን የታገሥሁትንም ስደት ታውቃለህ፤ ጌታም ከሁሉ አዳነኝ።'),
  ('9de9811a-9a1f-5044-ae55-d4d74b3c17a8', 'b505cb49-84e7-5f7c-a38c-83609507b34a', '45c3cae2-8472-5768-a42c-57bb3e0e0e1b', 3, 12, 'በእውነትም በክርስቶስ ኢየሱስ እግዚአብሔርን እየመሰሉ ሊኖሩ የሚወዱ ሁሉ ይሰደዳሉ።'),
  ('32de0b37-6d05-53c6-ac9b-73e3b60c5842', 'b505cb49-84e7-5f7c-a38c-83609507b34a', '45c3cae2-8472-5768-a42c-57bb3e0e0e1b', 4, 13, 'ነገር ግን ክፉዎች ሰዎችና አታላዮች እያሳቱና እየሳቱ በክፋት እየባሱ ይሄዳሉ።'),
  ('68d728d2-98ef-5f46-aafd-9930555ca002', 'b505cb49-84e7-5f7c-a38c-83609507b34a', '45c3cae2-8472-5768-a42c-57bb3e0e0e1b', 5, 14, 'አንተ ግን በተማርህበትና በተረዳህበት ነገር ጸንተህ ኑር፤ ከማን እንደ ተማርኸው ታውቃለህና፤'),
  ('66c2eb91-34ff-5cf2-a2fa-28ec8d43b083', 'b505cb49-84e7-5f7c-a38c-83609507b34a', '45c3cae2-8472-5768-a42c-57bb3e0e0e1b', 6, 15, 'ከሕፃንነትህም ጀምረህ ክርስቶስ ኢየሱስን በማመን መዳን የሚገኝበትን ጥበብ ሊሰጡህ የሚችሉትን ቅዱሳት መጻሕፍትን አውቀሃል።'),
  ('a2f5dd56-6bec-5d74-a1d5-8f113bca7fba', 'b505cb49-84e7-5f7c-a38c-83609507b34a', '45c3cae2-8472-5768-a42c-57bb3e0e0e1b', 7, 16, 'የእግዚአብሔር ሰው ፍጹምና ለበጎ ሥራ ሁሉ የተዘጋጀ ይሆን ዘንድ፥ የእግዚአብሔር መንፈስ ያለበት መጽሐፍ ሁሉ ለትምህርትና ለተግሣጽ ልብንም ለማቅናት በጽድቅም ላለው ምክር ደግሞ ይጠቅማል።'),
  ('5f86d775-f886-51c8-a48c-b4b225941ac3', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', '4ce919eb-d7bd-5fb2-adfc-ee39d44558c4', 1, 1, 'በእግዚአብሔር ፊት፥ በሕያዋንና በሙታንም ሊፈርድ ባለው በጌታ በኢየሱስ ክርስቶስ ፊት፥ በመገለጡና በመንግሥቱም እመክርሃለሁ፤'),
  ('4bd713dd-0472-5da1-a144-43ed20ba76d2', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', '4ce919eb-d7bd-5fb2-adfc-ee39d44558c4', 2, 2, 'ቃሉን ስበክ፤ በጊዜውም አለጊዜውም ጽና፤ ፈጽመህ እየታገሥህና እያስተማርህ ዝለፍና ገሥጽ፤ ምከርም።'),
  ('be0ba9dd-1db3-5125-a358-cddb4da4e922', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', '4ce919eb-d7bd-5fb2-adfc-ee39d44558c4', 3, 3, 'ሕይወት የሚገኝበትን ትምህርት የማይታገሡበት ዘመን ይመጣልና፤ ነገር ግን ጆሮቻቸውን የሚያሳክክ ስለ ሆነ፥ እንደ ገዛ ምኞታቸው ለራሳቸው አስተማሪዎችን ያከማቻሉ።'),
  ('4a0eb69a-5985-53ed-ae9d-ed1655e9700b', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', '9879535a-9039-5af4-a716-f42365fdaf8c', 1, 4, 'እውነትንም ከመስማት ጆሮቻቸውን ይመልሳሉ፤ ወደ ተረትም ፈቀቅ ይላሉ።'),
  ('b4eef6a1-9b9a-5a90-a0c8-1a0337e908af', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', '9879535a-9039-5af4-a716-f42365fdaf8c', 2, 5, 'አንተ ግን ነገርን ሁሉ በልክ አድርግ፤ መከራን ተቀበል፤ የወንጌል ሰባኪነትን ሥራ አድርግ፤ አገልግሎትህን ፈጽም።'),
  ('40ded825-7bfa-597e-af2a-c8effbd439f3', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', '9879535a-9039-5af4-a716-f42365fdaf8c', 3, 6, 'በመሥዋዕት እንደሚደረግ የእኔ ሕይወት ይሠዋልና፥ የምሄድበት ጊዜ ደርሶአል።'),
  ('3b31ebc3-c899-5a1c-a2e5-a889c6543883', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', '9879535a-9039-5af4-a716-f42365fdaf8c', 4, 7, 'መልካሙን ገድል ተጋድዬአለሁ፤ ሩጫውን ጨርሼአለሁ፤ ሃይማኖትን ጠብቄአለሁ፤'),
  ('5b1a70e4-0c32-5e04-a883-a63e2a09885b', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', '9879535a-9039-5af4-a716-f42365fdaf8c', 5, 8, 'ወደ ፊት የጽድቅ አክሊል ተዘጋጅቶልኛል፤ ይህንም ጻድቅ ፈራጅ የሆነው ጌታ ያን ቀን ለእኔ ያስረክባል፤ ደግሞም መገለጡን ለሚወዱት ሁሉ እንጂ ለእኔ ብቻ አይደለም።'),
  ('0b67fcb9-c130-51e7-a826-4cf6ccbc7ed8', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', 'c9b33aa5-5d10-5b21-af70-b02d1818b4e8', 1, 9, 'በቶሎ ወደ እኔ እንድትመጣ ትጋ፤'),
  ('84e158f6-5e58-5b4b-a04a-5bebe21a6b6f', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', 'c9b33aa5-5d10-5b21-af70-b02d1818b4e8', 2, 10, 'ዴማስ የአሁኑን ዓለም ወዶ ትቶኛልና፤ ወደ ተሰሎንቄም ሄዶአል፤ ቄርቂስም ወደ ገላትያ ቲቶም ወደ ድልማጥያ ሄደዋል።'),
  ('73b90de2-3b06-5867-a477-0534c490b5bf', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', 'c9b33aa5-5d10-5b21-af70-b02d1818b4e8', 3, 11, 'ሉቃስ ብቻ ከእኔ ጋር አለ፤ ማርቆስ ለአገልግሎት ብዙ ይጠቅመኛልና ይዘኸው ከአንተ ጋር አምጣው።'),
  ('bed1c363-aa85-5a52-a817-c7f18e7b9e75', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', 'c9b33aa5-5d10-5b21-af70-b02d1818b4e8', 4, 12, 'ቲኪቆስን ግን ወደ ኤፌሶን ላክሁት።'),
  ('55eec9f2-13d5-5458-acbc-ba6920b84e7e', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', 'c9b33aa5-5d10-5b21-af70-b02d1818b4e8', 5, 13, 'ስትመጣ በጢሮአዳ ከአክርጳ ዘንድ የተውሁትን በርኖሱንና መጻሕፍቱን ይልቁንም በብራና የተጻፉትን አምጣልኝ።'),
  ('446a5e76-c47c-5be8-ae0a-997912c0bc58', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', 'c9b33aa5-5d10-5b21-af70-b02d1818b4e8', 6, 14, 'የናስ አንጥረኛው እስክንድሮስ እጅግ ከፋብኝ፤ ጌታ እንደ ሥራው ይመልስለታል።'),
  ('835ca432-2b38-5d1d-a059-6fca50fe2806', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', 'c9b33aa5-5d10-5b21-af70-b02d1818b4e8', 7, 15, 'አንተም ደግሞ ከእርሱ ተጠበቅ፤ የምንናገረውን እጅግ ተቃውሞአልና።'),
  ('abf7a6c3-65ba-5b29-ab0a-0ed089653fa2', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', 'c9b33aa5-5d10-5b21-af70-b02d1818b4e8', 8, 16, 'በፊተኛው ሙግቴ አንድ ስንኳ አልደረሰልኝም፤ ሁሉም ተዉኝ እንጂ፤ ይህንም አይቍጠርባቸው፤'),
  ('ea55f19d-e97b-5ca6-a8ed-649f25187615', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', 'c9b33aa5-5d10-5b21-af70-b02d1818b4e8', 9, 17, 'ዳሩ ግን የስብከቱ ሥራ በእኔ እንዲፈጸም አሕዛብም ሁሉ እንዲሰሙት፥ ጌታ በእኔ አጠገብ ቆሞ አበረታኝ፤ ከአንበሳ አፍም ዳንሁ።'),
  ('8045f2fe-3f05-5262-a944-e240509bf874', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', 'c9b33aa5-5d10-5b21-af70-b02d1818b4e8', 10, 18, 'ጌታም ከክፉ ነገር ሁሉ ያድነኛል፤ ለሰማያዊውም መንግሥት ይጠብቀኛል፤ ለእርሱ ከዘላለም እስከ ዘላለም ክብር ይሁን፤ አሜን።'),
  ('eb978d57-5029-5669-abed-d3205f0d0fae', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', '7eb7dcfb-b596-52cc-a5ee-282e6fe35b90', 1, 19, 'ለጵርስቅላና ለአቂላ ለሄኔሲፎሩም ቤተ ሰዎች ሰላምታ አቅርብልኝ።'),
  ('4a5e1600-0ea1-5a96-ac3c-c07f7cc64f30', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', '7eb7dcfb-b596-52cc-a5ee-282e6fe35b90', 2, 20, 'ኤርስጦስ በቆሮንቶስ ቀረ፤ ጥሮፊሞስን ግን ታሞ በሚሊጢን ተውሁት።'),
  ('f3eca4af-9f13-56c6-a2c8-a129d9b1c3ad', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', '7eb7dcfb-b596-52cc-a5ee-282e6fe35b90', 3, 21, 'ከክረምት በፊት እንድትመጣ ትጋ። ኤውግሎስና ጱዴስ ሊኖስም ቅላውዲያም ወንድሞችም ሁሉ ሰላምታ ያቀርቡልሃል።'),
  ('e3bbf6ba-4a89-5d68-af9d-f822cd4f9dd8', '4fd68215-4cfc-5b5d-a863-de5ebc08a58f', '7eb7dcfb-b596-52cc-a5ee-282e6fe35b90', 4, 22, 'ጌታ ኢየሱስ ክርስቶስ ከመንፈስህ ጋር ይሁን። ጸጋ ከእናንተ ጋር ይሁን፤ አሜን።'),
  ('396fed57-439e-5a12-aab7-7adcfef8a0f5', 'f4bc2e9c-aea6-54d4-a90b-fcf9112e82a8', 'dcab1b5a-c707-5500-a545-ffcd23c4c7cd', 1, 1, 'የእግዚአብሔር ባሪያና የኢየሱስ ክርስቶስ ሐዋርያ የሆነ ጳውሎስ፥ በእግዚአብሔር ለተመረጡት እምነት እንዲሆንላቸው በዘላለምም ሕይወት ተስፋ እንደ አምልኮት ያለውን እውነት እንዲያውቁ የተላከ፤ ስለዚህም ሕይወት የማይዋሽ እግዚአብሔር ከዘላለም ዘመናት በፊት ተስፋ ሰጠ።'),
  ('f24dec1f-6aa5-54a9-ab49-669db911fe1a', 'f4bc2e9c-aea6-54d4-a90b-fcf9112e82a8', 'dcab1b5a-c707-5500-a545-ffcd23c4c7cd', 2, 3, 'በዘመኑም ጊዜ መድኃኒታችን እግዚአብሔር እንዳዘዘ፥ ለእኔ አደራ በተሰጠኝ ስብከት ቃሉን ገለጠ፤'),
  ('4e2cc326-6f7f-5df6-a7b3-5ab9d64cc600', 'f4bc2e9c-aea6-54d4-a90b-fcf9112e82a8', 'dcab1b5a-c707-5500-a545-ffcd23c4c7cd', 3, 4, 'በሃይማኖት ኅብረት እውነተኛ ልጄ ለሚሆን ለቲቶ፤'),
  ('351e6f9e-661e-5643-a7f6-7be68a1f9a58', 'f4bc2e9c-aea6-54d4-a90b-fcf9112e82a8', 'b7bc3003-1079-54a0-a30b-f176567dd9f2', 1, 5, 'ስለዚህ ምክንያት የቀረውን እንድታደራጅ በየከተማውም እኔ አንተን እንዳዘዝሁ፥ ሽማግሌዎችን እንድትሾም በቀርጤስ ተውሁህ፤'),
  ('889d4017-a029-5635-a8a5-0eafa6cda0ab', 'f4bc2e9c-aea6-54d4-a90b-fcf9112e82a8', 'b7bc3003-1079-54a0-a30b-f176567dd9f2', 2, 6, 'የማይነቀፍና የአንዲት ሚስትባል የሚሆን፥ የሚያምኑም ልጆች ያሉት፥ ስለ መዳራትም ወይም ስለ አለመታዘዝ የማይከሰስ ማንም ቢኖር፥ ሹመው።'),
  ('5810e51d-6fac-5703-a0dd-0c0549145ebc', 'f4bc2e9c-aea6-54d4-a90b-fcf9112e82a8', 'b7bc3003-1079-54a0-a30b-f176567dd9f2', 3, 7, 'ኤጲስቆጶስ እንደ እግዚአብሔር መጋቢ የማይነቀፍ ሊሆን ይገባዋልና፤ የማይኮራ፥ የማይቆጣ፥ የማይሰክር፥ የማይጨቃጨቅ፥ ነውረኛ ረብ የማይወድ፥'),
  ('2dc77920-d856-57fd-a5fe-253bf89d6774', 'f4bc2e9c-aea6-54d4-a90b-fcf9112e82a8', 'b7bc3003-1079-54a0-a30b-f176567dd9f2', 4, 8, 'ነገር ግን እንግዳ ተቀባይ፥ በጎ የሆነውን ነገር የሚወድ፥ ጠንቃቃ፥ ጻድቅ፥ ቅዱስ፥ ራሱን የሚገዛ ይሁን፤'),
  ('f92c5f6a-727c-5756-ab22-1db58637f6ab', 'f4bc2e9c-aea6-54d4-a90b-fcf9112e82a8', 'b7bc3003-1079-54a0-a30b-f176567dd9f2', 5, 9, 'ሕይወት በሚገኝበት ትምህርት ደግሞ ሊመክር ተቃዋሚዎቹንም ሊወቅስ ይችል ዘንድ፥ እንደተማረው በታመነ ቃል ይጽና።'),
  ('19a0e116-f0a3-5e33-a7b0-d06d60b42acb', 'f4bc2e9c-aea6-54d4-a90b-fcf9112e82a8', 'b7bc3003-1079-54a0-a30b-f176567dd9f2', 6, 10, 'የማይታዘዙና ከንቱ የሚናገሩ የሚያታልሉ ይልቁንም ከተገረዙት ወገን የሚሆኑ ብዙ ናቸውና፤'),
  ('7eeec4c1-07a1-570c-abb2-d445870c74f4', 'f4bc2e9c-aea6-54d4-a90b-fcf9112e82a8', 'b7bc3003-1079-54a0-a30b-f176567dd9f2', 7, 11, 'እነዚህም ስለ ነውረኛ ረብ የማይገባውን እያስተማሩ ቤቶችን በሞላው ስለ ሚገለብጡ፥ አፋቸውን መዝጋት ይገባል።'),
  ('cdd0311d-5885-5371-a22d-17dfc1d47ae3', 'f4bc2e9c-aea6-54d4-a90b-fcf9112e82a8', 'b7bc3003-1079-54a0-a30b-f176567dd9f2', 8, 12, 'የገዛ ራሳቸው ነቢይ የሆነ ከእነርሱ አንዱ “የቀርጤስ ሰዎች ዘወትር ውሸተኞች፥ ክፉዎች አራዊት፥ በላተኞች፥ ሥራ ፈቶች ናቸው፤” ብሎአል።'),
  ('4642ec7d-2e52-52a5-a173-7fb7647a93bd', 'f4bc2e9c-aea6-54d4-a90b-fcf9112e82a8', 'b7bc3003-1079-54a0-a30b-f176567dd9f2', 9, 13, 'ይህ ምስክር እውነተኛ ነው። ስለዚህ ምክንያት የአይሁድን ተረትና ከእውነት ፈቀቅ የሚሉትን ሰዎች ትእዛዝ ሳያዳምጡ፥ በሃይማኖት ጤናሞች እንዲሆኑ በብርቱ ውቀሳቸው።'),
  ('b731ccc1-8dce-5c28-ac4b-6545cc2fd58a', 'f4bc2e9c-aea6-54d4-a90b-fcf9112e82a8', 'b7bc3003-1079-54a0-a30b-f176567dd9f2', 10, 15, 'ሁሉ ለንጹሖች ንጹሕ ነው፤ ለርኵሳንና ለማያምኑ ግን ንጹሕ የሆነ ምንም የለም፤ ነገር ግን አእምሮአቸውም ሕሊናቸውም ረክሶአል።'),
  ('14bead84-9406-509f-a295-a2f3ce6fb0d3', 'f4bc2e9c-aea6-54d4-a90b-fcf9112e82a8', 'b7bc3003-1079-54a0-a30b-f176567dd9f2', 11, 16, 'እግዚአብሔርን እንዲያውቁ በግልጥ ይናገራሉ፤ ዳሩ ግን የሚያስጸይፉና የማይታዘዙ ለበጎ ሥራም ሁሉ የማይበቁ ስለ ሆኑ፥ በሥራቸው ይክዱታል።'),
  ('2d066670-364b-54c8-a40f-a081d5abcedb', '2971efa1-8664-5239-ac63-bda3ed0f7a5b', '08266874-cdf4-5580-a17b-dbcb10062e89', 1, 1, 'አንተ ግን ሕይወት ለሚገኝበት ትምህርት የሚገባውን ተናገር።'),
  ('7eb20799-f7b0-5606-a84b-d1d39556bdda', '2971efa1-8664-5239-ac63-bda3ed0f7a5b', '08266874-cdf4-5580-a17b-dbcb10062e89', 2, 2, 'ሽማግሌዎች ልከኞች፥ ጭምቶች፥ ራሳቸውን የሚገዙ፥ በእምነትና በፍቅር በመጽናትም ጤናሞች እንዲሆኑ ምከራቸው፤'),
  ('25e30b06-993e-5421-a9e6-3a701bb63d18', '2971efa1-8664-5239-ac63-bda3ed0f7a5b', '08266874-cdf4-5580-a17b-dbcb10062e89', 3, 3, 'እንዲሁም አሮጊቶች ሴቶች አካሄዳቸው ለቅዱስ አገልግሎት የሚገባ፥ የማያሙ፥ ለብዙ ወይን ጠጅ የማይገዙ፥ በጎ የሆነውን ነገር የሚያስተምሩ ይሁኑ፤'),
  ('f5b7fe38-48b8-536c-aaac-6e73400cd1b9', '2971efa1-8664-5239-ac63-bda3ed0f7a5b', '08266874-cdf4-5580-a17b-dbcb10062e89', 4, 4, 'ቆነጃጅትም የእግዚአብሔር ቃል እንዳይሰደብ፥ ባሎቻቸውን የሚወዱ፥ ልጆቻቸውን የሚወዱ፥ ራሳቸውን የሚገዙ፥ ንጹሖች፥ በቤት የሚሠሩ፥ በጎዎች፥ ለባሎቻቸው የሚታዘዙ እንዲሆኑ ይምከሩአቸው።'),
  ('77abba74-81ac-513b-ab89-4b4d7df23c38', '2971efa1-8664-5239-ac63-bda3ed0f7a5b', '08266874-cdf4-5580-a17b-dbcb10062e89', 5, 6, 'ጎበዞችም እንዲሁ ራሳቸውን እንዲገዙ ምከራቸው።'),
  ('99550116-9301-59f1-a5cb-bf25b368f4fb', '2971efa1-8664-5239-ac63-bda3ed0f7a5b', '08266874-cdf4-5580-a17b-dbcb10062e89', 6, 7, 'የሚቃወም ሰው ስለ እኛ የሚናገረውን መጥፎ ነገር ሲያጣ እንዲያፍር፥ በነገር ሁሉ መልካምን በማድረግህ ምሳሌ የሚሆን ራስህን አሳይ፤ በትምህርትህም ደኅንነትን፥ ጭምትነትን፥ ጤናማና የማይነቀፍ ንግግርን ግለጥ።'),
  ('2e2a661f-a7b2-571e-ae10-6b6c22eedcf8', '2971efa1-8664-5239-ac63-bda3ed0f7a5b', '08266874-cdf4-5580-a17b-dbcb10062e89', 7, 9, 'ባሪያዎች ስለ መድኃኒታችን ስለ እግዚአብሔር የሚሆነውን ትምህርት በሁሉ ነገር ያስመሰግኑ ዘንድ፥ ለገዛ ጌቶቻቸው እንዲገዙ በሁሉም ደስ እንዲያሰኙ፥ ሳይቃወሙና ሳይሰርቁም በጎ ታማኝነትን ሁሉ እንዲያሳዩ ምከራቸው።'),
  ('7fb4097a-65b0-5925-a3f4-6eee823a5e03', '2971efa1-8664-5239-ac63-bda3ed0f7a5b', '08266874-cdf4-5580-a17b-dbcb10062e89', 8, 11, 'ሰዎችን ሁሉ የሚያድን የእግዚአብሔር ጸጋ ተገልጦአልና፤'),
  ('469bbd45-bd25-559f-abc4-0a9c37cd85ed', '2971efa1-8664-5239-ac63-bda3ed0f7a5b', '08266874-cdf4-5580-a17b-dbcb10062e89', 9, 12, 'ይህም ጸጋ፥ ኀጢአተኝነትንና ዓለማዊን ምኞት ክደን፥ የተባረከውን ተስፋችንን እርሱም የታላቁን የአምላካችንንና የመድኃኒታችንን የኢየሱስ ክርስቶስን ክብር መገለጥ እየጠበቅን፥ ራሳችንን በመግዛትና በጽድቅ እግዚአብሔርንም በመምሰል በአሁኑ ዘመን እንድንኖር ያስተምረናል፤'),
  ('84b641df-6e5a-5506-abc1-898c13d5f6b8', '2971efa1-8664-5239-ac63-bda3ed0f7a5b', '08266874-cdf4-5580-a17b-dbcb10062e89', 10, 14, 'መድኃኒታችንም ከዐመፅ ሁሉ እንዲቤዠን፥ መልካሙንም ለማድረግ የሚቀናውን ገንዘቡም የሚሆነውን ሕዝብ ለራሱ እንዲያነጻ፥ ስለ እኛ ነፍሱን ሰጥቶአል።'),
  ('a75bdc12-882b-5134-aaf7-49d2b50aef1c', '2971efa1-8664-5239-ac63-bda3ed0f7a5b', '08266874-cdf4-5580-a17b-dbcb10062e89', 11, 15, 'ይህን በሙሉ ሥልጣን ተናገርና ምከር፤ ገሥጽም፤ ማንም አይናቅህ።'),
  ('08b7cfee-290a-56be-a701-082c1a3e9225', '662504d8-9f81-523d-ae27-a5267c40c726', 'e1e91d51-273d-5ebc-a5eb-9ffa70530594', 1, 1, 'ለገዦችና ለባለ ሥልጣኖች የሚገዙና የሚታዘዙ፥ ለበጎ ሥራ ሁሉ የተዘጋጁ፥ ማንንም የማይሰድቡ፥ የማይከራከሩ፥ ገሮች፥ ለሰው ሁሉ የዋህነትን ሁሉ የሚያሳዩ እንዲሆኑ ኣሳስባቸው።'),
  ('ebfa9b8c-5422-5a87-a899-01ed20148f8e', '662504d8-9f81-523d-ae27-a5267c40c726', 'e1e91d51-273d-5ebc-a5eb-9ffa70530594', 2, 3, 'እኛ ደግሞ አስቀድመን የማናስተውል ነበርንና፤ የማንታዘዝ፥ የምንስት፥ ለምኞትና ለልዩ ልዩ ተድላ እንደ ባሪያዎች የምንገዛ፥ በክፋትና በምቀኝነት የምንኖር፥ የምንጣላ፥ እርስ በርሳችን የምንጠላላ ነበርን።'),
  ('8dba5cde-1314-5352-a7bc-8a0271cba839', '662504d8-9f81-523d-ae27-a5267c40c726', 'e1e91d51-273d-5ebc-a5eb-9ffa70530594', 3, 4, 'ነገር ግን የመድኃኒታችን የእግዚአብሔር ቸርነትና ሰውን መውደዱ በተገለጠ ጊዜ፥'),
  ('383b7079-2f28-524a-a6a1-b27f52e1340e', '662504d8-9f81-523d-ae27-a5267c40c726', 'e1e91d51-273d-5ebc-a5eb-9ffa70530594', 4, 5, 'እንደ ምሕረቱ መጠን ለአዲስ ልደት በሚሆነው መታጠብና በመንፈስ ቅዱስ በመታደስ አዳነን እንጂ፥ እኛ ስላደረግነው በጽድቅ ስለ ነበረው ሥራ አይደለም፤'),
  ('b22252f3-971f-52a2-a2a5-c04d9703f781', '662504d8-9f81-523d-ae27-a5267c40c726', 'e1e91d51-273d-5ebc-a5eb-9ffa70530594', 5, 6, 'ያን መንፈስም፥ በጸጋው ጸድቀን በዘላለም ሕይወት ተስፋ ወራሾች እንድንሆን፥ በመድኃኒታችን በኢየሱስ ክርስቶስ በእኛ ላይ አትርፎ አፈሰሰው።'),
  ('8a54ce03-7a27-51e3-abf0-feb95529d74b', '662504d8-9f81-523d-ae27-a5267c40c726', 'e1e91d51-273d-5ebc-a5eb-9ffa70530594', 6, 8, 'ቃሉ የታመነ ነው። እግዚአብሔርንም የሚያምኑት በመልካም ሥራ በጥንቃቄ እንዲጸኑ፥ እነዚህን አስረግጠህ እንድትናገር እፈቅዳለሁ። ይህ መልካምና ለሰዎች የሚጠቅም ነው፤'),
  ('10881d68-6a0c-55c6-a2e0-661e889d2ccb', '662504d8-9f81-523d-ae27-a5267c40c726', 'e1e91d51-273d-5ebc-a5eb-9ffa70530594', 7, 9, 'ነገር ግን ሞኝነት ካለው ምርመራና ከትውልዶች ታሪክ ከክርክርም ስለ ሕግም ከሚሆን ጠብ ራቅ፤ የማይጠቅሙና ከንቱዎች ናቸውና፤'),
  ('6d028246-f302-5949-a0eb-7538cfd7ca56', '662504d8-9f81-523d-ae27-a5267c40c726', 'e1e91d51-273d-5ebc-a5eb-9ffa70530594', 8, 10, 'መለያየትን የሚያነሣ ሰው ጠማማ እንዲሆን በራሱም ላይ ፈርዶ ኀጢአትን እንዲያደርግ አውቀህ፥ አንድ ጊዜ ሁለት ጊዜም ከገሠጽኸው በኋላ እንዲህ ከሚመስል ሰው ራቅ።'),
  ('bc160e0c-fece-5945-a3af-1c60af0e5c01', '662504d8-9f81-523d-ae27-a5267c40c726', '334563bd-f9d1-5b50-a344-e38798c8dd7c', 1, 12, 'አርጢሞንን ወይም ቲኪቆስን ወደ አንተ ስልክ፥ ወደ ኒቆጵልዮን ወደ እኔ እንድትመጣ ትጋ፤ በዚያ ልከርም ቈርጫለሁና።'),
  ('7e53f07d-9521-5702-ad62-04f4c384e2a8', '662504d8-9f81-523d-ae27-a5267c40c726', '334563bd-f9d1-5b50-a344-e38798c8dd7c', 2, 13, 'ሕግ አዋቂውን ዜማስንና አጵሎስን ምንም እንዳይጎድልባቸው በጉዞአቸው ተግተህ እርዳ።'),
  ('2e14449d-8f97-56d3-ac3e-2cbc58158157', '662504d8-9f81-523d-ae27-a5267c40c726', '334563bd-f9d1-5b50-a344-e38798c8dd7c', 3, 14, 'ከወገናችንም ያሉት ደግሞ ፍሬ ቢሶች ሆነው እንዳይቀሩ፥ የግድ ስለሚያስፈልገው ነገር በመልካም ሥራ እንዲጸኑ ይማሩ።'),
  ('689ebe39-fce3-514b-a040-ff1969aa93e0', '662504d8-9f81-523d-ae27-a5267c40c726', '334563bd-f9d1-5b50-a344-e38798c8dd7c', 4, 15, 'ከእኔ ጋር ያሉት ሁሉ ሰላምታ ያቀርቡልሃል። በእምነት ለሚወዱን ሰላምታ አቅርብልን። ጸጋ ከሁላችሁ ጋር ይሁን፤ አሜን።'),
  ('de6a21be-a312-5f97-a2a8-202bdd32e6e0', '01e89c1c-930a-560e-a418-4507b82885de', '6a74f1c1-466b-52cb-a070-c0f517eda3c2', 1, 1, 'የክርስቶስ ኢየሱስ እስረኛ ጳውሎስ ወንድሙም ጢሞቴዎስ፥ ለተወደደውና አብሮን ለሚሠራ ለፊልሞና፥'),
  ('88c92774-0044-5815-a4e0-af356f907681', '01e89c1c-930a-560e-a418-4507b82885de', '6a74f1c1-466b-52cb-a070-c0f517eda3c2', 2, 2, 'ለእኅታችንም ለአፍብያ፥ ከእኛም ጋር አብሮ ወታደር ለሆነ ለአርክጳ፥ በቤትህም ላለች ቤተ ክርስቲያን፤'),
  ('fc176bce-dbf3-53eb-acf8-5403117ded3a', '01e89c1c-930a-560e-a418-4507b82885de', '6a74f1c1-466b-52cb-a070-c0f517eda3c2', 3, 3, 'ከእግዚአብሔር ከአባታችን ከጌታም ከኢየሱስ ክርስቶስ ጸጋና ሰላም ለእናንተ ይሁን።'),
  ('cb1298eb-a8be-515b-a5b3-0694483cb427', '01e89c1c-930a-560e-a418-4507b82885de', '12b4827e-0e9a-5a88-a366-03e5727f8e14', 1, 4, 'በጌታ በኢየሱስ ዘንድ በቅዱሳንም ሁሉ ዘንድ ስላለህ ስለ ፍቅርህና ስለ እምነትህ ሰምቼ፥ በጸሎቴ እያሳሰብሁ ሁልጊዜ አምላኬን አመሰግናለሁ፤'),
  ('f6bfd554-0234-54de-a3e4-9dc7723980d4', '01e89c1c-930a-560e-a418-4507b82885de', '12b4827e-0e9a-5a88-a366-03e5727f8e14', 2, 6, 'የእምነትህም ኅብረት፥ በእኛ ዘንድ ያለውን በጎ ነገር ሁሉ በማወቅ፥ ለክርስቶስ ኢየሱስ ፍሬ እንዲያፈራ እለምናለሁ፤'),
  ('b43b6ab2-2914-5b60-a22e-7e19a3249a3a', '01e89c1c-930a-560e-a418-4507b82885de', '12b4827e-0e9a-5a88-a366-03e5727f8e14', 3, 7, 'የቅዱሳን ልብ በአንተ ሥራ ስለ ዐረፈ፥ ወንድሜ ሆይ! በፍቅርህ ብዙ ደስታንና መጽናናትን አግኝቼአለሁና።'),
  ('e27d40f8-87b4-56a7-ac52-8b6f7836d6ed', '01e89c1c-930a-560e-a418-4507b82885de', 'fc6daee1-662b-5e43-a980-d6b262f5274e', 1, 8, 'ስለዚህ የሚገባውን አዝህ ዘንድ በክርስቶስ ምንም እንኳ ብዙ ድፍረት ቢኖረኝ፥'),
  ('bef54742-9397-519c-aeca-d1f1a5f730cf', '01e89c1c-930a-560e-a418-4507b82885de', 'fc6daee1-662b-5e43-a980-d6b262f5274e', 2, 9, 'ይልቁንም እንደዚህ የሆንሁ እኔ ጳውሎስ ሽማግሌው፥ አሁንም ደግሞ የኢየሱስ ክርስቶስ እስረኛ የሆንሁ፥ ስለ ፍቅር እለምናለሁ።'),
  ('75cdc192-11bf-557d-a2c6-adb59e2650fe', '01e89c1c-930a-560e-a418-4507b82885de', 'fc6daee1-662b-5e43-a980-d6b262f5274e', 3, 10, 'አስቀድሞ ስላልጠቀመህ፥ አሁን ግን ለእኔም ለአንተም ስለሚጠቅም በእስራቴ ስለ ወለድሁት ስለ ልጄ ስለ አናሲሞስ እለምንሃለሁ።'),
  ('9e094213-7012-5009-ae14-43147a29343b', '01e89c1c-930a-560e-a418-4507b82885de', 'fc6daee1-662b-5e43-a980-d6b262f5274e', 4, 12, 'እርሱን እልከዋለሁ፤ አንተም ልቤ እንደሚሆን ተቀበለው።'),
  ('c342c263-b9fc-5077-afe9-c912c9daf0ed', '01e89c1c-930a-560e-a418-4507b82885de', 'fc6daee1-662b-5e43-a980-d6b262f5274e', 5, 13, 'እኔስ በወንጌል እስራት ስለ አንተ እንዲያገለግለኝ ለራሴ ላስቀረው እፈቅድ ነበር፤'),
  ('edae21f3-7a8c-564b-a70b-35c853df8c47', '01e89c1c-930a-560e-a418-4507b82885de', 'fc6daee1-662b-5e43-a980-d6b262f5274e', 6, 14, 'ነገር ግን በጎነትህ በፈቃድህ እንጂ በግድ እንዳይሆን፥ ሳልማከርህ ምንም እንኳ ላደርግ አልወደድሁም።'),
  ('c0732eab-62bf-5874-abf0-d6b60a5e15a7', '01e89c1c-930a-560e-a418-4507b82885de', 'fc6daee1-662b-5e43-a980-d6b262f5274e', 7, 15, 'ተቀብለህ ለዘላለም እንድትይዘው ስለዚህ ምናልባት ለጊዜው ተለይቶሃልና፤'),
  ('595f2729-c56e-51a1-a256-144c24f62b87', '01e89c1c-930a-560e-a418-4507b82885de', 'fc6daee1-662b-5e43-a980-d6b262f5274e', 8, 16, 'ከእንግዲህ ወዲህ እንደ ባሪያ አይሆንም፤ ነገር ግን ለእኔ በተለየ የተወደደ ወንድም ከሆነ፥ ለአንተማ ይልቅ በሥጋውም በጌታም ዘንድ ከባሪያ የሚሻል የተወደደ ወንድም እንዴት አይሆንም?'),
  ('fbbb906d-f170-5011-a3d4-d52d4756e44e', '01e89c1c-930a-560e-a418-4507b82885de', 'fc6daee1-662b-5e43-a980-d6b262f5274e', 9, 17, 'እንግዲህ እንደ ባልንጀራ ብትቈጥረኝ፥ እንደ እኔ አድርገህ ተቀበለው።'),
  ('3d0e5f84-da32-5f27-a97d-5585bb60bfe2', '01e89c1c-930a-560e-a418-4507b82885de', 'fc6daee1-662b-5e43-a980-d6b262f5274e', 10, 18, 'በአንዳች ነገር የበደለህ ቢኖር ግን ወይም ብድር ያለበት እንደሆነ፥ ይህን በእኔ ላይ ቍጠር፤'),
  ('0812d584-7b77-5080-a75d-5cf7ffb3d546', '01e89c1c-930a-560e-a418-4507b82885de', 'fc6daee1-662b-5e43-a980-d6b262f5274e', 11, 19, 'እኔ ጳውሎስ “እኔ እመልሰዋለሁ፤” ብዬ በእጄ እጽፋለሁ፤ ከዚህም በላይ ለእኔ የራስህ ደግሞ ብድር እንዳለብህ አልልህም።'),
  ('b747b8c4-bd90-5243-afbf-e2db09add24e', '01e89c1c-930a-560e-a418-4507b82885de', 'fc6daee1-662b-5e43-a980-d6b262f5274e', 12, 20, 'አዎን፥ ወንድሜ ሆይ! በጌታ እኔ እንድጠቀምብህ ይሁን፤ በክርስቶስ ልቤን አሳርፍልኝ።'),
  ('1df205ba-62f5-59e3-a064-3449ef2fe7c7', '01e89c1c-930a-560e-a418-4507b82885de', 'fc6daee1-662b-5e43-a980-d6b262f5274e', 13, 21, 'ከምልህ ይልቅ አብልጠህ እንድታደርግ አውቄ እንድትታዘዝም ታምኜ እጽፍልሃለሁ።'),
  ('3948d3aa-771b-5975-ae8b-32dd59a1ce5e', '01e89c1c-930a-560e-a418-4507b82885de', 'fc6daee1-662b-5e43-a980-d6b262f5274e', 14, 22, 'ደግሞ ከዚህም ጋር የማስተናገጃ ቤት አዘጋጅልኝ፤ በጸሎታችሁ ለእናንተ እንድሰጥ ተስፋ አደርጋለሁና።'),
  ('f93f8586-0402-57b4-aaca-e8ed0e450980', '01e89c1c-930a-560e-a418-4507b82885de', 'ea79a6bc-0389-5a03-ab99-b195532fa5e1', 1, 23, 'በክርስቶስ ኢየሱስ ከእኔ ጋር የታሰረ ኤጳፍራ'),
  ('e9cb25b2-9ce6-582a-a62c-aacfdfd3788c', '01e89c1c-930a-560e-a418-4507b82885de', 'ea79a6bc-0389-5a03-ab99-b195532fa5e1', 2, 24, 'አብረውኝም የሚሠሩ ማርቆስና አርስጥሮኮስ ዴማስም ሉቃስም ሰላምታ ያቀርቡልሃል።'),
  ('d95df626-7ecc-5fdf-a035-baeb95072d95', '01e89c1c-930a-560e-a418-4507b82885de', 'ea79a6bc-0389-5a03-ab99-b195532fa5e1', 3, 25, 'የጌታችን የኢሱስ ክርስቶስ ጸጋ ከመንፈሳችሁ ጋር ይሁን፤ አሜን።'),
  ('dc5da21f-5e9b-50a0-ae51-7eb4404b7c2d', 'ca9c0b49-8a51-5643-a72b-6ebe5f2cd347', '583b2f6c-dd5c-55dc-a9ea-8e22b9f101b0', 1, 1, 'ከጥንት ጀምሮ እግዚአብሔር በብዙ ዐይነትና በብዙ ጎዳና ለአባቶቻችን በነቢያት ተናገረ።'),
  ('c3c062e2-eb18-5188-a4ee-68f6c2bba2ed', 'ca9c0b49-8a51-5643-a72b-6ebe5f2cd347', '583b2f6c-dd5c-55dc-a9ea-8e22b9f101b0', 2, 2, 'በኋላ ዘመን ግን ሁሉን ወራሽ ባደረገው፥ ሁሉንም በፈጠረበት በልጁ ነገረን።'),
  ('5eae8db2-3f0c-5747-aaba-956625bc8a96', 'ca9c0b49-8a51-5643-a72b-6ebe5f2cd347', '583b2f6c-dd5c-55dc-a9ea-8e22b9f101b0', 3, 3, 'እርሱም የክብሩ መንጸባረቅና የመልኩ ምሳሌ ሆኖ፥ ሁሉን በሥልጣኑ ቃል እየደገፈ ኀጢአታችንን በራሱ ካነጻ በኋላ፥ በሰማያት በግርማው ቀኝ ተቀመጠ።'),
  ('dc785dad-618d-5bc6-a930-d1f6080fbe78', 'ca9c0b49-8a51-5643-a72b-6ebe5f2cd347', '583b2f6c-dd5c-55dc-a9ea-8e22b9f101b0', 4, 4, 'በዚህን ያህል መብለጥ ከመላእክት በላይ ሆኖ ከስማቸው የሚበልጥና የሚከብር ስምን ወረሰ።'),
  ('3bf84d8c-927d-5587-a666-b1a9a2f8b3d0', 'ca9c0b49-8a51-5643-a72b-6ebe5f2cd347', '583b2f6c-dd5c-55dc-a9ea-8e22b9f101b0', 5, 5, 'ከመላእክትስ ከሆነ ጀምሮ፥ “አንተ ልጄ ነህ፥ እኔ ዛሬ ወለድሁህ” ዳግመኛም፥ “እኔ አባት እሆነዋለሁ እርሱም ልጄ ይሆነኛል” ያለው ከቶ ለማን ነው?'),
  ('a4c2af8d-8adf-5def-a5b7-28bb7c8f91e3', 'ca9c0b49-8a51-5643-a72b-6ebe5f2cd347', '583b2f6c-dd5c-55dc-a9ea-8e22b9f101b0', 6, 6, 'ዳግመኛም በኵርን ወደ ዓለም በላከው ጊዜ “የእግዚአብሔር መላእክት ሁሉ ይሰግዱለታል” አለ።'),
  ('bb1fcf40-3f00-5f00-a232-65680f419ba3', 'ca9c0b49-8a51-5643-a72b-6ebe5f2cd347', '583b2f6c-dd5c-55dc-a9ea-8e22b9f101b0', 7, 7, 'ስለ መላእክቱም፥ “መላእክቱን ነፋሳት፥ የሚላኩትንም የእሳት ነበልባል የሚያደርጋቸው እርሱ ነው” አለ።'),
  ('10ae6335-210b-5f46-a92d-3f523d72109b', 'ca9c0b49-8a51-5643-a72b-6ebe5f2cd347', '583b2f6c-dd5c-55dc-a9ea-8e22b9f101b0', 8, 8, 'ስለ ልጁ ግን፥ “ጌታ ሆይ፥ ዙፋንህ ለዘለዓለም ነው፤ የመንግሥትህ በትርም የጽድቅ በትር ነው” አለ።'),
  ('205fb660-afb4-5f0b-aed3-1048df542640', 'ca9c0b49-8a51-5643-a72b-6ebe5f2cd347', '583b2f6c-dd5c-55dc-a9ea-8e22b9f101b0', 9, 9, '“ጽድቅን ወደድህ፤ ዐመፃንም ጠላህ፤ ስለዚህም እግዚአብሔር አምላክህ እንዳንተ ካሉት ይልቅ የሚበልጥ የደስታ ዘይትን ቀባህ።”'),
  ('f89981c2-44f6-51d9-a410-ebe9f573a1e2', 'ca9c0b49-8a51-5643-a72b-6ebe5f2cd347', '583b2f6c-dd5c-55dc-a9ea-8e22b9f101b0', 10, 10, 'ዳግመኛም እንዲህ አለ፥ “አቤቱ አንተ አስቀድሞ ምድርን መሠረትህ፤ ሰማያትም የእጆችህ ሥራ ናቸው።'),
  ('e65429fa-f974-520d-a4c5-4d051d118077', 'ca9c0b49-8a51-5643-a72b-6ebe5f2cd347', '583b2f6c-dd5c-55dc-a9ea-8e22b9f101b0', 11, 11, 'እነርሱ ያልፋሉ፤ አንተ ግን ትኖራለህ፤ ሁሉ እንደ ልብስ ያረጃል፤'),
  ('1aea7360-debb-51bc-aeab-07ffc34287b8', 'ca9c0b49-8a51-5643-a72b-6ebe5f2cd347', '583b2f6c-dd5c-55dc-a9ea-8e22b9f101b0', 12, 12, 'እንደ መጋረጃም ትጠቀልላቸዋለህ፤ ይለወጣሉም፤ አንተ ግን መቼም መች አንተ ነህ፤ ዘመንህም የማይፈጸም ነው።”'),
  ('2e798f04-d18b-5cbb-a8da-52819be5db66', 'ca9c0b49-8a51-5643-a72b-6ebe5f2cd347', '583b2f6c-dd5c-55dc-a9ea-8e22b9f101b0', 13, 13, 'ከሆነ ጀምሮ ከመላእክት፥ “ጠላቶችህን ከእግርህ ጫማ በታች እስከ አደርግልህ ድረስ በቀኜ ተቀመጥ” ማንን አለው?'),
  ('ddce01d6-5982-5dc9-a79b-8362bf01dab8', 'ca9c0b49-8a51-5643-a72b-6ebe5f2cd347', '583b2f6c-dd5c-55dc-a9ea-8e22b9f101b0', 14, 14, 'መላእክት ሁሉ መናፍስት አይደሉምን? የዘለዓለም ሕይወትን ይወርሱ ዘንድ ስለ አላቸው ሰዎችስ ለአገልግሎት ይላኩ የለምን?'),
  ('2857a2c9-80f5-5d95-a872-4d45f84d01dd', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 1, 1, 'ስለዚህም ከሰማነው ነገር ምንአልባት እንዳንወሰድ ለእርሱ አብዝተን ልንጠነቀቅ ይገባናል።'),
  ('b8985334-462e-5d4d-aef4-fc9990cb37bd', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 2, 2, 'በመላእክት የተነገረው ቃል ጽኑ ከሆነ፥ መተላለፍና አለመታዘዝም ሁሉ የጽድቅን ብድራት ከተቀበለ፥'),
  ('bf2da579-225a-5514-aa1c-20970d52f321', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 3, 3, 'እኛስ እንዲህ ያለውን ታላቅ መዳን ቸል ብንለው እንዴት እናመልጣለን? ይህ በጌታ በመጀመሪያ የተነገረ ነበረና የሰሙትም ለእኛ አጸኑት።'),
  ('71aa081b-c291-5eda-a861-75792ae95616', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 4, 4, 'እግዚአብሔርም እንደ ራሱ ፈቃድ የመንፈስ ቅዱስን ጸጋ በመስጠት፥ በምልክትና በድንቅ ነገር፥ በልዩ ልዩ ተአምራትም መሰከረላቸው፤ ነገራቸውንም አስረዳላቸው።'),
  ('6081e0a4-4b02-5b63-ac9c-69ba00cc2bb0', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 5, 5, 'ስለ እርሱ የምንናገርለትን የሚመጣውን ዓለም ለመላእክት ያስገዛ አይደለም።'),
  ('257bfadd-9a59-5ecf-a7b8-e0089b2740ad', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 6, 6, 'ነገር ግን መጽሐፍ እንዲህ ብሎ የመሰከረበት ስፍራ አለ፤ “ታስበው ዘንድ ሰው ምንድን ነው? ትጐበኘውስ ዘንድ የሰው ልጅ ምንድን ነው?'),
  ('55c5d631-9b72-51b8-a400-42ec0f8e8999', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 7, 7, 'ከመላእክትህ ጥቂት አሳነስኸው፤ የክብርና የምስጋና ዘውድንም ጫንህለት፤ በእጆችህም ሥራ ሁሉ ላይ ሾምኸው።'),
  ('fd38be8b-73e7-5948-a177-a75f222d022f', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 8, 8, 'ሁሉንም ከእግሩ በታች አድርገህ አስገዛህለት።” ሁሉን ለእርሱ ባስገዛለት ጊዜም የተወውና ያላስገዛለት የለም፤ አሁን ግን ሁሉን እንዳስገዛለት አናይም።'),
  ('7f099e7f-c12c-58f3-aaba-1ad11aba8558', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 9, 9, 'ነገር ግን በእግዚአብሔር ጸጋ ስለ ሰው ሁሉ ሞትን ይቀምስ ዘንድ ከመላእክት ይልቅ በጥቂት አንሶ የነበረውን ኢየሱስን ከሞት መከራ የተነሣ የክብርና የምስጋናን ዘውድ ጭኖ እናየዋለን።'),
  ('3bb2c8be-ab91-5067-a930-5bedd4c6f8c7', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 10, 10, 'ብዙ ልጆችን ወደ ክብር ሲያመጣ የመዳናቸውን ራስ በመከራ ይፈጽም ዘንድ ከእርሱ የተነሣ ሁሉ በእጁ ለተያዘ፥ በእርሱም ሁሉ ለሆነ ለእርሱ ተገብቶታልና።'),
  ('99d88315-d83a-56c6-a89b-c91855914c50', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 11, 11, 'እነርሱን የቀደሳቸው እርሱ፥ የተቀደሱት እነርሱም ሁሉም በአንድነት ከአንዱ ናቸውና። ስለዚህም እነርሱን፥ “ወንድሞች” ማለትን አያፍርም።'),
  ('4ca0a258-f378-5dcd-aca6-e578c7c02a62', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 12, 12, '“ስምህን ለወንድሞች እነግራቸዋለሁ፤ በማኅበር መካከልም አመሰግንሃለሁ” አለ።'),
  ('bdfaa46d-74ae-59f9-a4c6-8466c1d138fc', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 13, 13, 'ዳግመኛም፥ “እኔና እግዚአብሔር የሰጠኝ ልጆች እነሆ፥” አለ፤ ዳግመኛም፥ “እኔ እታመንበታለሁ” አለ።'),
  ('5968294c-b95e-5b76-a604-1cae65e02a6c', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 14, 14, 'ልጆች በሥጋና በደም አንድ ናቸውና፤ እርሱ ደግሞ በዚህ ከእነርሱ ጋር አንድ ሆነ፤ ለእነርሱም እንደ ወንድም ሆነላቸው፤ መልአከ ሞትን በሞቱ ይሽረው ዘንድ፥ ይኸውም ሰይጣን ነው።'),
  ('c6b820c9-4fa3-5bb6-a87f-d6d250a65df6', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 15, 15, 'በሕይወት ዘመናቸው ሁሉ ሞትን በመፍራት የተቀጡትን፥ ለባርነት የተገዙትንም ሁሉ ያሳርፋቸው ዘንድ።'),
  ('204bccc6-5965-5f40-a659-68340f7f3f95', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 16, 16, 'የነሣውን ከአብርሃም ዘር እንጂ ከመላእክት የነሣው አይደለምና።'),
  ('c390a6c9-7ebb-54b9-a2fa-07c6e280349e', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 17, 17, 'ስለዚህም የሕዝብን ኀጢአት ለማስተስረይ ለእግዚአብሔር በሆነው ነገር ሁሉ የሚምርና የታመነ ሊቀ ካህናት እንዲሆን በነገር ሁሉ ወንድሞቹን ሊመስል ተገባው።'),
  ('776d5498-44b0-50fd-a13c-f46aa2a855a6', '44077b7d-1adc-5cc8-aee1-1f7280627609', '26c74f73-f6a3-5c90-a9bb-ead4c66724d7', 18, 18, 'እርሱ ራሱ ተፈትኖ መከራን ስለ ተቀበለ የሚፈተኑትን ሊረዳቸው ይችላልና።'),
  ('7c895680-6d5d-57bc-a553-b9346142a6f8', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 1, 1, 'አሁንም ከሰማያዊ ጥሪ ተካፋዮች የሆናችሁ ቅዱሳን ወንድሞቻችን ሆይ፥ የሃይማኖታችንን ሐዋርያና ሊቀ ካህናት ኢየሱስ ክርስቶስን ተመልከቱ።'),
  ('5539b1ce-c447-53a6-a3fe-e9e5796589a5', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 2, 2, 'ሙሴ ደግሞ በቤቱ ሁሉ የታመነ እንደ ሆነ፥ እርሱ ለላከው የታመነ እውነተኛ ነው።'),
  ('0faadec7-3db5-5a8e-ac76-78dcbb3546c3', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 3, 3, 'ነገር ግን የባለቤት ክብሩ ከቤቱ እንደሚበልጥ፥ ክብሩ ከሙሴ ክብር ይልቅ እጅግ ይበልጣል፤'),
  ('ccec585d-caac-502f-a808-7450bde54758', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 4, 4, 'ቤትን ሁሉ ሰው ይሠራዋልና፤ ለሁሉ ግን ሠሪው እግዚአብሔር ነው።'),
  ('0f2855d6-0a81-5a3a-adbc-38682154e603', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 5, 5, 'ሙሴስ በኋላ ስለሚነገረው ነገር ምስክር ሊሆን በቤቱ ሁሉ እንደ ሎሌ የታመነ ነበረ።'),
  ('a2491ffc-91cf-57aa-acfc-d6a4a3d0aae2', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 6, 6, 'ክርስቶስ ግን እንደ ልጅ በቤቱ ላይ የታመነ ነው፤ እኛም የምንደፍርበትን፥ የምንመካበትንም ተስፋ እስከ መጨረሻው አጽንተን ብንጠብቅ ቤቱ ነን።'),
  ('edcae1d9-8f4c-59ef-a1ef-b3784155ad27', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 7, 7, 'መንፈስ ቅዱስ እንዲህ ብሎአልና፥ “ዛሬ ቃሉን ብትሰሙ ልባችሁን አታጽኑ።'),
  ('28bc49cd-2f17-5c57-a590-2c983697ecc5', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 8, 8, 'በምድረ በዳ በተፈታተኑበት ቀን እንደ አሳዘኑት ጊዜ።'),
  ('61cc5702-f8cc-5cf0-a191-ce451eead4d6', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 9, 9, 'የተፈታተኑኝ አባቶቻችሁ ፈተኑኝ፤ አርባ ዘመንም ሥራዬን አዩ።'),
  ('be977ed1-a304-5443-a9de-d5dd749b87b4', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 10, 10, 'ስለዚህ ይህቺን ትውልድ ተቈጣኋት፤ እንዲህም አልሁ፦ ‘ልባቸው ዘወትር ይስታል፤ እነርሱ ግን መንገዴን አላወቁም።’'),
  ('8556e5d0-b24c-5391-a612-96cd583ec1bc', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 11, 11, 'ወደ ዕረፍቴ አይገቡም ብዬ በቍጣዬ ማልሁ።”'),
  ('b529d1ad-b4b5-58b9-af18-a3fbc246ccdd', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 12, 12, 'ወንድሞቻችን ሆይ፥ እንግዲህ ዕወቁ፤ ከእናንተ ባንዱ ላይ ስንኳ ሃይማኖት የጐደለውና ተጠራጣሪ፥ ከሕያው እግዚአብሔር የሚለያችሁ ክፉ ልብ አይኑር።'),
  ('62db68c4-85b9-55f8-a399-386982f53872', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 13, 13, 'ዛሬ የሚባለው ቀን ሳለ ከእናንተ ማንም ቢሆን ወደ ኀጢአት በሚያደርስ ስሕተት እንዳይጸና ሁልጊዜ ሰውነታችሁን መርምሩ።'),
  ('44be38cb-80f7-5a00-a265-3da1905dbf5e', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 14, 14, 'በዚች ጽድቅ እስከ መጨረሻ የቀደመውን ሥርዐታችንን አጽንተን ከጠበቅን ከክርስቶስ ጋር አንድ ሁነናልና።'),
  ('c9835526-2429-5a35-ad6e-a4e8484c7451', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 15, 15, '“ዛሬ ቃሉን ብትሰሙ እነዚያ እንደ አሳዘኑት ጊዜ ልባችሁን አታጽኑ” ብሎአልና።'),
  ('b2b87ba0-65c1-56ee-a85c-a0d2b6e4e806', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 16, 16, 'ሰምተው ያሳዘኑትስ እነማን ናቸው? በሙሴ እጅ ከግብፅ የወጡት ሁሉ አይደሉምን?')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('ba41a44c-74d1-5088-a78e-a3e8df719e2a', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 17, 17, 'አርባ ዘመን የተቈጣቸውስ እነማን ነበሩ? የበደሉ፥ ሬሳቸውም በምድረ በዳ የወደቀው አይደሉምን?'),
  ('ddcf2b76-d02b-5afb-a97b-53db48ec39b3', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 18, 18, 'ከካዱት በቀር ወደ ዕረፍቱ እንዳይገቡ በማን ላይ ማለ?'),
  ('0eabc8f9-daff-5fde-a1a0-ee20bbeb957c', '9ea1e6df-64f2-5a22-a074-edc174e93ab7', '997c47ab-1336-55f3-addb-b58d22ac3518', 19, 19, 'አላመኑምና፥ ለመግባት እንዳልቻሉ እነሆ፥ እናያለን።'),
  ('4ddea778-15f8-593d-a45e-66fd023e65a5', '6a4e0169-e84b-50cc-a912-396047950f6c', 'c31a88dd-782f-591e-a2c8-f157227d7e5f', 1, 1, 'እንግዲህ አንፍራ፤ ወደ ዕረፍቱም እንድንገባ ትእዛዙን አንተው፤ ከእናንተም ምንአልባት በተለመደ ስሕተት የሚገኝና የሚጸና ቢኖር ወደ ዕረፍቱ እንዲገባ የሚተዉት አይምሰለው።'),
  ('aa5bda53-7747-566a-ab7b-1810088a7484', '6a4e0169-e84b-50cc-a912-396047950f6c', 'c31a88dd-782f-591e-a2c8-f157227d7e5f', 2, 2, 'ለእነዚያ ደግሞ እንደ ተነገረ ለእኛም የምሥራች ተሰብኮልናል፤ ነገር ግን የሰሙት ቃል ከሰሚዎቹ ጋር በእምነት ስላልተዋሐደ አልጠቀማቸውም።'),
  ('42d1b472-8a7f-5032-a6a5-31974d1df3f6', '6a4e0169-e84b-50cc-a912-396047950f6c', 'c31a88dd-782f-591e-a2c8-f157227d7e5f', 3, 3, 'ሥራዉ ዓለም ከተፈጠረ ጀምሮ ምንም እንኳ ቢፈጸም፥ “እንግዲህ ወደ ዕረፍቴ አይገቡም ብዬ በቍጣዬ ማልሁ” እንዳለ እኛስ ያመንን ወደ ዕረፍቱ እንገባለን።'),
  ('169370e3-a09b-582b-a481-88e1d5b37dc3', '6a4e0169-e84b-50cc-a912-396047950f6c', 'c31a88dd-782f-591e-a2c8-f157227d7e5f', 4, 4, 'ስለ ሰባተኛውም ቀን፥ “እግዚአብሔር በሰባተኛው ቀን ከሥራው ሁሉ ዐረፈ” ብሎአልና።'),
  ('cf6b4ed0-6d3e-500c-a442-f510eabc2c40', '6a4e0169-e84b-50cc-a912-396047950f6c', 'c31a88dd-782f-591e-a2c8-f157227d7e5f', 5, 5, 'ዳግመኛም፥ “ወደ ዕረፍቴ አይገቡም” ብሎአል።'),
  ('515ad20d-f057-5d89-aead-4c6c5af0d3dd', '6a4e0169-e84b-50cc-a912-396047950f6c', 'c31a88dd-782f-591e-a2c8-f157227d7e5f', 6, 6, 'እንግዲህ አንዳንዶች በዚያ እንዲገቡ መንገድ ስለ ነበራቸው ቀድሞም የምሥራች የተሰበከላቸው ባለ መታዘዝ ጠንቅ ስላልገቡ፦'),
  ('85861dc0-d0df-5977-a80a-cfadb009f64e', '6a4e0169-e84b-50cc-a912-396047950f6c', 'c31a88dd-782f-591e-a2c8-f157227d7e5f', 7, 7, '“ዛሬ ቃሉን ብትሰሙት ልባችሁን እልከኛ አታድርጉ፤” በፊት እንደ ተባለ ይህን ከሚያህል ዘመን በኋላ በዳዊት ሲናገር፥ “ዛሬ” ብሎ አንድ ቀን እንደ ገና ይቀጥራል።'),
  ('7c4da6af-6dec-59a2-a730-05c8da6f6ffd', '6a4e0169-e84b-50cc-a912-396047950f6c', 'c31a88dd-782f-591e-a2c8-f157227d7e5f', 8, 8, 'ኢያሱ አሳርፎአቸው ቢሆን ኖሮስ፥ ከብዙ ዘመን በኋላ ስለ ሌላ ቀን ባልተናገረም ነበር።'),
  ('05ff21da-d9a5-5b94-a67b-5c04e544a9ca', '6a4e0169-e84b-50cc-a912-396047950f6c', 'c31a88dd-782f-591e-a2c8-f157227d7e5f', 9, 9, 'እንኪያስ የእግዚአብሔር ሕዝብ የሚገቡበት ጸንቶ የሚኖር ዕረፍት እንዳለ ታወቀ።'),
  ('a8f69aaf-11e9-5b56-a9b1-7e568df96afa', '6a4e0169-e84b-50cc-a912-396047950f6c', 'c31a88dd-782f-591e-a2c8-f157227d7e5f', 10, 10, 'ወደ ዕረፍቱ የገባስ እግዚአብሔር ከሥራው እንደ ዐረፈ፥ እነሆ፥ እርሱ ከሥራው ሁሉ ዐረፈ።'),
  ('dbec90c0-2a97-5a9f-afd8-52d63478aae8', '6a4e0169-e84b-50cc-a912-396047950f6c', 'c31a88dd-782f-591e-a2c8-f157227d7e5f', 11, 11, 'እንግዲህ እንደ እነዚያ እንደ ካዱት እንዳንወድቅ፥ ወደ ዕረፍቱ እንገባ ዘንድ እንፋጠን።'),
  ('451ac063-45b5-59ce-a9d5-c44332732870', '6a4e0169-e84b-50cc-a912-396047950f6c', 'c31a88dd-782f-591e-a2c8-f157227d7e5f', 12, 12, 'የእግዚአብሔር ቃል ሕያው ነውና፤ የሚሠራም ሁለት ልሳን ካለው ሰይፍም ሁሉ ይልቅ የተሳለ ነው፤ ነፍስንና መንፈስንም፥ ጅማትንና ቅልጥምንም እስኪለይ ድረስ ይወጋል፤ የልብንም ስሜትና አሳብ ይመረምራል።'),
  ('5d0c411c-aa7e-5d16-ad26-d8b0230da05a', '6a4e0169-e84b-50cc-a912-396047950f6c', 'c31a88dd-782f-591e-a2c8-f157227d7e5f', 13, 13, 'እኛን በሚቈጣጠር በእርሱ በዐይኖቹ ፊት ሁሉ ነገር የተራቈተና የተገለጠ ነው እንጂ በእርሱ ፊት የተሰወረ ፍጥረት የለም።'),
  ('5d35617f-d399-59c0-aea7-eebb27754630', '6a4e0169-e84b-50cc-a912-396047950f6c', '27457083-966f-55ba-ac06-1e75d7058bc3', 1, 14, 'እንግዲህ ወደ ሰማያት የወጣ ታላቅ ሊቀ ካህናት የእግዚአብሔር ልጅ ኢየሱስ ክርስቶስ አለን፤ በእርሱ በማመን ጸንተን እንኑር።'),
  ('b7d56922-0de7-576d-aa84-ada37556eb7d', '6a4e0169-e84b-50cc-a912-396047950f6c', '27457083-966f-55ba-ac06-1e75d7058bc3', 2, 15, 'ሊቀ ካህናታችን ለድካማችን መከራ መቀበልን የማይችል አይደለምና፤ ነገር ግን ከብቻዋ ከኀጢአት በቀር እኛን በመሰለበት ሁሉ የተፈተነ ነው።'),
  ('77cb7350-0c2a-5d4d-a0d6-e903a4d66f14', '6a4e0169-e84b-50cc-a912-396047950f6c', '27457083-966f-55ba-ac06-1e75d7058bc3', 3, 16, 'እንግዲህ ምሕረትን እንድንቀበል፥ በሚያስፈልገንም ጊዜ የሚረዳንን ጸጋ እንድናገኝ፥ ወደ ጸጋው ዙፋን በእምነት እንቅረብ።'),
  ('cd375e45-2891-5546-aea8-8ed81171e10b', 'f7e54ac1-24bd-5bff-ad63-9bfc2d63b012', '16bfd4a9-1a22-5ca4-aebc-279f2a35a6cb', 1, 1, 'ሊቀ ካህናት ሁሉ ስለ ኀጢአት መባንና መሥዋዕትን ሊያቀርብ ከሰው ተመርጦ ለእግዚአብሔር በሆነው ነገር ሁሉ ስለ ሰው ይሾማልና።'),
  ('000b5672-3d96-55b6-aad9-80e9c5c2ce17', 'f7e54ac1-24bd-5bff-ad63-9bfc2d63b012', '16bfd4a9-1a22-5ca4-aebc-279f2a35a6cb', 2, 2, 'እርሱ ራሱም ደካማ ነውና ባለማወቃቸው ከሳቱ ሰዎች ጋር መከራን ሊቀበል ይችላል።'),
  ('95c5badd-f74f-5a54-a4b6-e42469513c2e', 'f7e54ac1-24bd-5bff-ad63-9bfc2d63b012', '16bfd4a9-1a22-5ca4-aebc-279f2a35a6cb', 3, 3, 'በዚህም ምክንያት ስለ ሕዝብ እንደሚያቀርብ እንዲሁ ስለ ራሱ ደግሞ መሥዋዕትን ስለ ኀጢአት ማቅረብ ይገባዋል።'),
  ('4cac122b-9247-5f9c-ae67-438bd82f1f84', 'f7e54ac1-24bd-5bff-ad63-9bfc2d63b012', '16bfd4a9-1a22-5ca4-aebc-279f2a35a6cb', 4, 4, 'እንደ አሮንም በእግዚአብሔር ከተጠራ በቀር፥ ማንም ለራሱ ክብርን የሚወስድ የለም።'),
  ('bb83bbb6-239c-556c-ab38-76041536bd34', 'f7e54ac1-24bd-5bff-ad63-9bfc2d63b012', '16bfd4a9-1a22-5ca4-aebc-279f2a35a6cb', 5, 5, 'እንዲሁ ክርስቶስም ሊቀ ካህናት ይሆን ዘንድ ራሱን ያከበረ አይደለም፤ ነገር ግን፥ “አንተ ልጄ ነህ፥ እኔም ዛሬ ወለድሁህ” ያለው እርሱ ራሱ ነው።'),
  ('d1958415-fd3b-5b56-a7f9-c083f629390b', 'f7e54ac1-24bd-5bff-ad63-9bfc2d63b012', '16bfd4a9-1a22-5ca4-aebc-279f2a35a6cb', 6, 6, 'ዳግመኛም፥ “እንደ መልከ ጼዴቅ ሹመት የዘለዓለም ካህን አንተ ነህ” ይላል።'),
  ('ab958c0a-19da-5305-a870-6de34a9d7c04', 'f7e54ac1-24bd-5bff-ad63-9bfc2d63b012', '16bfd4a9-1a22-5ca4-aebc-279f2a35a6cb', 7, 7, 'እርሱም ሥጋ ለብሶ በዚህ ዓለም በነበረበት ጊዜ፥ በታላቅ ጩኸትና እንባ ከሞት ሊያድነው ወደሚችለው ጸሎትንና ምልጃን አቀረበ፤ ጽድቁንም ሰማው።'),
  ('a6f14924-45ed-5f72-a140-63e0d2a2c4ec', 'f7e54ac1-24bd-5bff-ad63-9bfc2d63b012', '16bfd4a9-1a22-5ca4-aebc-279f2a35a6cb', 8, 8, 'ልጅም ቢሆን መከራን ስለ ተቀበለ መታዘዝን ዐወቀ።'),
  ('07a6329c-27b2-53e3-a950-a2fafa7aa0d0', 'f7e54ac1-24bd-5bff-ad63-9bfc2d63b012', '16bfd4a9-1a22-5ca4-aebc-279f2a35a6cb', 9, 9, 'ከተፈጸመም በኋላ ለሚታዘዝለት ሁሉ ሕይወትን የሚሰጥ የዘለዓለም መድኅን ሆነ።'),
  ('cffb6c38-43e9-581b-a262-61a3b9f9d598', 'f7e54ac1-24bd-5bff-ad63-9bfc2d63b012', '16bfd4a9-1a22-5ca4-aebc-279f2a35a6cb', 10, 10, 'እግዚአብሔርም እንደ መልከ ጼዴቅ ሹመት የዘለዓለም ሊቀ ካህናት አለው።'),
  ('360343e3-2344-56b3-ad4f-b3ecca65b804', 'f7e54ac1-24bd-5bff-ad63-9bfc2d63b012', '16bfd4a9-1a22-5ca4-aebc-279f2a35a6cb', 11, 11, 'ስለ እርሱም የምንናገረው ብዙ ነገር አለን፤ ጆሮዎቻችሁም ስለ ፈዘዙ በቃል ልንተረጕመው ጭንቅ ነው።'),
  ('7751e76b-954d-5cee-a4aa-68d74ea4130f', 'f7e54ac1-24bd-5bff-ad63-9bfc2d63b012', '16bfd4a9-1a22-5ca4-aebc-279f2a35a6cb', 12, 12, 'መምህራን ልትሆኑ ሲገባችሁ፥ ካመናችሁ ጀምሮ በትምህርት ላይ የቈያችሁ ስለ ሆነ፥ እስከ ዛሬም ገና የእግዚአብሔርን የቃሉን መጀመሪያ ትምህርት ሊያስተምሩአችሁ ትወዳላችሁ፤ ወተትንም ሊግቱአችሁ ትሻላችሁ፤ ጽኑ ምግብንም አይደለም።'),
  ('db050eb8-3978-552c-a8a0-febd4a6a3528', 'f7e54ac1-24bd-5bff-ad63-9bfc2d63b012', '16bfd4a9-1a22-5ca4-aebc-279f2a35a6cb', 13, 13, 'ወተትን የሚጋት ሁሉ ሕፃን ስለሆነ፥ የጽድቅን ቃል ሊያውቅ አይሻም።'),
  ('3439badf-6a20-5477-aae7-c1b65ce91433', 'f7e54ac1-24bd-5bff-ad63-9bfc2d63b012', '16bfd4a9-1a22-5ca4-aebc-279f2a35a6cb', 14, 14, 'ጠንካራ ምግብ ግን መልካሙንና ክፉዉን ለመለየት በሥራቸው የለመደ ልቡና ላላቸው ለፍጹማን ሰዎች ነው።'),
  ('1d1e5319-da4e-58a0-a814-5cf51ab0711b', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '100e10bc-af56-5224-afd5-a727b2fecea2', 1, 1, 'ስለዚህም የክርስቶስን የነገሩን መጀመሪያ ትተን ወደ ፍጻሜው እንሂድ፤ እንግዲህ ደግሞ ሌላ መሠረት እንዳትሹ ዕወቁ፤ ይኸውም ከሞት ሥራ ለመመለስ፥ በእግዚአብሔርም ለማመን፥'),
  ('3d92975d-c547-5872-ab20-7cedd84e6d78', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '100e10bc-af56-5224-afd5-a727b2fecea2', 2, 2, 'ጥምቀትን፥ በአንብሮተ እድ መሾምን፥ የሙታንን ትንሣኤና የዘለዓለም ፍርድን ለመማር ነው።'),
  ('c303498c-d539-54bf-acb6-a7c7ec6d1c2f', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '100e10bc-af56-5224-afd5-a727b2fecea2', 3, 3, 'እግዚአብሔርም ቢፈቅድ ይህን ባደረግን ነበር።'),
  ('a894ed17-5746-5099-a800-46a683d03789', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '100e10bc-af56-5224-afd5-a727b2fecea2', 4, 4, 'ነገር ግን አንድ ጊዜ ብርሃን የበራላቸውን፥ ሰማያዊውንም ስጦታ የቀመሱትን፥ ከመንፈስ ቅዱስም ተካፋዮች ሆነው የነበሩትን፥'),
  ('35e7203b-e2d6-57b0-ae36-27b11e58c8f8', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '100e10bc-af56-5224-afd5-a727b2fecea2', 5, 5, 'መልካሙን የእግዚአብሔርን ቃል፥ የሚመጣውንም የዓለምን ኀይል የቀመሱትን፥'),
  ('4174142e-b1a2-53e4-a719-9b9230a85397', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '100e10bc-af56-5224-afd5-a727b2fecea2', 6, 6, 'በኋላም የካዱትን እንደ ገና ለንስሓ እነርሱን ማደስ አይቻልም፤ ራሳቸው የእግዚአብሔርን ልጅ ይሰቅሉታልና፥ ያዋርዱትማልና።'),
  ('ba93f101-424e-5ea9-a3a7-7a54460b5ea7', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '100e10bc-af56-5224-afd5-a727b2fecea2', 7, 7, 'ምድርም በእርስዋ የሚወርደውን ዝናም ከጠጣች፥ ያንጊዜ ስለ እርሱ ያረሱላትን መላካም ቡቃያ ታበቅላለች፤ ከእግዚአብሔር ዘንድም በረከትን ታገኛለች።'),
  ('3e08859d-8da9-598a-a5d6-7173edde2aaa', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '100e10bc-af56-5224-afd5-a727b2fecea2', 8, 8, 'እሾህንና ኵርንችትን ብታወጣ ግን የተጣለች ናት፤ ለመርገምም የቀረበች ናት፤ ፍጻሜዋም ለመቃጠል ይሆናል።'),
  ('7b3b0940-1149-5746-ad04-4e43313b4f58', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '100e10bc-af56-5224-afd5-a727b2fecea2', 9, 9, 'የተመረጣችሁ ወንድሞቻችን ሆይ፥ ምንም እንኳን እንዲህ ብንላችሁ ሕይወት ወዳለባት ትምህርት እንድትቀርቡ እንታመንባችኋለን።'),
  ('885c0146-bd34-55b0-a30f-51e5a6915df5', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '100e10bc-af56-5224-afd5-a727b2fecea2', 10, 10, 'እግዚአብሔር ቅዱሳንን ስለ አገለገላችሁ፥ እስከ አሁንም ስለምታገለግሉአቸው ያደረጋችትሁን ሥራ፥ በስሙም ያሳያችሁትን ፍቅር ይረሳ ዘንድ ዐመፀኛ አይደለምና።'),
  ('03f9e4c4-2bd1-501b-a29d-351c86690ed7', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '100e10bc-af56-5224-afd5-a727b2fecea2', 11, 11, 'ነገር ግን ሁላችሁም በዚች ተስፋችሁ እንዲሁ ትጋታችሁን እስከ መጨረሻው ታሳዩ ዘንድ እንወዳለን።'),
  ('9b96955f-15ea-5a8f-af78-bb2e83ab7970', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '100e10bc-af56-5224-afd5-a727b2fecea2', 12, 12, 'ዳተኞች እንዳትሆኑ በሃይማኖትና በትዕግሥት ተስፋቸውን የወረሱትን ሰዎች ምሰሉአቸው።'),
  ('17e3b059-befc-5eec-a83a-d63dcc4beb3b', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '02893028-9b2f-576a-aeb5-945721f45658', 1, 13, 'እግዚአብሔርም ለአብርሃም ተስፋዉን በሰጠው ጊዜ ይምልበት ዘንድ ከእርሱ የሚበልጥ ሌላ ባይኖር፥ በራሱ ማለ።'),
  ('6f39d45a-a96e-5522-a825-365ae8abe97d', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '02893028-9b2f-576a-aeb5-945721f45658', 2, 14, 'እንዲህ ብሎ፦“ መባረክን እባርክሃለሁ፥ ማብዛትንም አበዛሃለሁ።”'),
  ('4e116a6f-0b84-5cca-a2a3-cd163e07567e', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '02893028-9b2f-576a-aeb5-945721f45658', 3, 15, 'ከዚህም በኋላ ታግሦ ተስፋዉን አገኘ።'),
  ('e047d458-77d6-5d35-afd7-601e0dbb8e6b', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '02893028-9b2f-576a-aeb5-945721f45658', 4, 16, 'ሰው ግን ከእርሱ በሚበልጠው ይምላል፤ የክርክርም መነሻው በመሐላ ይፈጸማል።'),
  ('56eea645-338e-5e19-ae5a-07ba7e549cb8', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '02893028-9b2f-576a-aeb5-945721f45658', 5, 17, 'ስለዚህም እግዚአብሔር ተስፋውን ለሚወርሱ ሰዎች ምክሩን እንደማይለውጥ ሊገልጥ ወደደ፤ እንደማይለውጥም በመሓላ አጸናው።'),
  ('5ad2295c-8777-5b99-a809-4b9d0ab98c26', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '02893028-9b2f-576a-aeb5-945721f45658', 6, 18, 'የእግዚአብሔር ቃል ሐሰት ሊሆን አይቻልም፤ በእርሱ ለተማፀን ተጠብቆልን ባለ ተስፋችንም ማመንን ላጸናን ለእኛ ታላቅ ደስታ አለን።'),
  ('8141104c-4c80-534b-a587-55970f710f98', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '02893028-9b2f-576a-aeb5-945721f45658', 7, 19, 'ይህችም ተስፋ ነፍሳችን እንዳትነዋወጥ እንደ መልሕቅ የምታጸና ናት፤'),
  ('f3b3b4e2-20a4-561f-ac79-703712662b23', 'ed780740-0963-51c2-a9e8-4fc4cd5229c2', '02893028-9b2f-576a-aeb5-945721f45658', 8, 20, 'እንደ መልከ ጼዴቅ ሹመት ለዘለዓለም ሊቀ ካህናት ሆኖ ሐዋርያችን ኢየሱስ ከእኛ በፊት ወደ ገባባት መጋረጃም ውስጥ የምታስገባ ናት።'),
  ('9cd4a4d2-ef7d-5b0b-aaaa-3f14ae6696a1', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 1, 1, 'የሳሌም ንጉሥ፥ የልዑል እግዚአብሔርም ካህን የሆነ፥ ይህ መልከ ጼዴቅ፥ አብርሃም ነገሥታትን ድል ነሥቶ በተመለሰ ጊዜ ከእርሱ ጋር ተገናኝቶ ባረከው።'),
  ('d9e64521-99e8-566b-a118-e0c96e08bd18', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 2, 2, 'አብርሃምም ከገንዘቡ ሁሉ ከዐሥር አንድ ሰጠው፤ መጀመሪያ የስሙ ትርጓሜ የጽድቅ ንጉሥ ነበር፤ በኋላም የሳሌም ንጉሥ ተባለ፤ የሰላም ንጉሥ ማለት ነው።'),
  ('59ee662e-87a9-526d-a696-b2518cd6bd54', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 3, 3, 'አባት የለውም፤ እናትም የለችውም፤ ትውልዱም አይታወቅም፤ ለዘመኑ መጀመሪያ፥ ለሕይወቱም መጨረሻ የለውም፤ ክህነቱ የወልደ እግዚአብሔር ምሳሌ ሆኖ ለዘለዓለም ይኖራል።'),
  ('e95ed90f-d6db-5e52-afb9-08aca96561ed', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 4, 4, 'የአባቶች አለቃ አብርሃም ከምርኮው ሁሉ የሚሻለውን ዐሥራት የሰጠውን የዚህን ካህን ክብር ታያላችሁን?'),
  ('9eb7d13f-7e9b-53ae-a6fe-471ab5fcafff', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 5, 5, 'ከሌዊ ልጆችም፥ ክህነትን የሚቀበሉት ከሕዝቡ ማለት ከወንድሞቻቸው፥ እነርሱ ምንም ከአብርሃም ወገብ ቢወጡ ከእነርሱ ዐሥራትን በሕግ እንዲያስወጡ ትእዛዝ አላቸው።'),
  ('14dafa53-4a78-5e8a-a4d2-dc34bdb1bdde', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 6, 6, 'ወገናቸው ላይደለ ለእርሱ ግን አብርሃም ዐሥራትን ሰጠው፤ እርሱም ተስፋ ያለው አብርሃምን ባረከው።'),
  ('cc8eaa66-76ae-51fa-aa44-3febc667815d', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 7, 7, 'ነገር ግን ታላቁ ታናሹን እንደሚባርከው ያለ ጥርጥር ይታወቃል።'),
  ('db43f006-4715-5a4e-a909-aaebcb9e86aa', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 8, 8, 'በዚህስ የሚሞት ሰው ዐሥራትን ይቀበላል፤ በወዲያው ግን ሕያው እንደ ሆነ መጽሐፍ የሚመሰክርለት እርሱ ይቀበላል።'),
  ('0de6a585-6338-517c-aabf-c892eecbe5e4', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 9, 9, 'እንደ ተነገረም ዐሥራትን የሚቀበል ሌዊ ስንኳን በአብርሃም በኩል ዐሥራትን ሰጠ።'),
  ('f014c796-b73a-5734-a7d0-8204dd89e2d9', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 10, 10, 'መልከ ጼዴቅ በተገናኘው ጊዜ ገና በአባቱ በአብርሃም ወገብ ነበርና።'),
  ('de078756-7499-54d0-a926-7c21950dd507', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 11, 11, 'እንግዲህ ሕዝቡ በሌዊ ክህነት የተመሠረተን ሕግ ተቀብለዋልና በዚያ ክህነት ፍጹምነት የተገኘ ቢሆን፥ እንደ አሮን ሹመት የማይቈጠር፥ እንደ መልከ ጼዴቅ ሹመት ግን የሆነ ሌላ ካህን ሊነሣ ወደ ፊት ስለምን ያስፈልጋል?'),
  ('120b4794-69ed-5390-ab5e-e87310c34035', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 12, 12, 'ክህነታቸው ታልፍ ዘንድ አላትና፤ ክህነታቸው ካለፈችም ኦሪታቸው ታልፋለች።'),
  ('5428229d-ff19-5adb-a046-4095f64867e6', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 13, 13, 'ይህ ነገር የተነገረለት እርሱ በሌላ ወገን ተካፍሎአልና፥ ከዚያም መሠዊያውን ያገለገለ ማንም የለም።'),
  ('4d8f1212-a141-51a9-a5a1-a3d20f988200', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 14, 14, 'ጌታችን ከይሁዳ ነገድ እንደ ወጣ የተገለጠ ነውና፤ ስለዚህም ነገድ ሙሴ ምንም እንኳን ስለ ክህነት አልተናገረም።'),
  ('7761e071-8f31-5161-a253-dffd5e703f41', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 15, 15, 'ይልቁንም ይህ እጅግ ያስረዳል፤ በመልከ ጼዴቅ ክህነት አምሳል ሌላ ካህን ይነሣል ብሎአልና።'),
  ('742e641d-08be-5331-a08d-097b7cb338d4', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 16, 16, 'ይኸውም በማያልፍ ሕይወት ኀይል እንጂ ለሥጋና ለደም በተሠራ ሕግ አይደለም።'),
  ('daaffcda-f799-55bf-a41d-28b02844a24a', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 17, 17, '“እንደ መልከ ጼዴቅ ሹመት የዘለዓለም ካህን አንተ ነህ” ብሎ ይመሰክራልና።'),
  ('ab6aee3c-36b6-58ad-abeb-758ec5cfe8be', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 18, 18, 'ስለዚህም የምትደክም፥ የማትጠቅምም ስለ ሆነች የቀደመችው ትእዛዝ ተሽራለች።'),
  ('37a1087b-c415-5a5f-acf4-4b77ac95e7ac', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 19, 19, 'ኦሪት ምንም ግዳጅ አልፈጸመችምና፤ ነገር ግን በእርስዋ ፋንታ ወደ እግዚአብሔር የምንቀርብበት ከእርስዋ የሚሻል ተስፋ ገብቶአል።'),
  ('57cf86da-78e0-50bd-a73e-63be54d117af', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 20, 20, 'እርሱ ያለ መሐላ አልሆነም፤ ያለ መሐላ የተሾሙ ካህናት አሉና።'),
  ('c9cf03c1-15c4-5b93-ab4e-10e876f8300e', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 21, 21, 'በመሐላ የሾመውን ግን፥ “እግዚአብሔር ማለ፥ አይጸጸትምም፤ አንተ እንደ መልከ ጼዴቅ ሹመት የዘለዓለም ካህን ነህ” አለው።'),
  ('7df208b8-6182-5f48-acdc-2bd2d79a0025', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 22, 22, 'ኢየሱስ ይህን ያህል በምትበልጥና ከፍ ባለች ሹመት ተሾመ።'),
  ('c5a6b9c8-b789-57d3-ae27-3b28b9329792', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 23, 23, 'ለእነዚያስ ብዙዎች ካህናት ነበሩአቸው፤ ሞት ይሽራቸው፥ እንዲኖሩም አያሰናበታቸውም ነበርና።'),
  ('28077092-c3a3-57e4-a058-22ecc43e3337', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 24, 24, 'እርሱ ግን ለዘለዓለም ይኖራል፤ ክህነቱ አይሻርምና።'),
  ('50443669-6a28-524c-a502-16ed2abc3013', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 25, 25, 'ዘወትር በእርሱ በኩል ወደ እግዚአብሔር የሚቀርቡትን ሊያድናቸው ይቻለዋል፤ ለዘለዓለምም ሕያው ነውና ያስታርቃቸዋል።'),
  ('0c2fb892-1435-50a8-a5e2-3f5dfe79e378', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 26, 26, 'ቅዱስና ያለ ተንኰል፥ ነውርም የሌለበት፥ ከኀጢአተኞችም የተለየ፥ ከሰማያትም ከፍ ከፍ ያለ፥ እንደዚህ ያለ ሊቀ ካህናት ይገባናል።'),
  ('1a97f499-df46-587c-af98-6db2403fee0e', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 27, 27, 'እርሱም እንደ እነዚያ ሊቃነ ካህናት አስቀድሞ ስለ ራሱ ኀጢአት በኋላም ስለ ሕዝቡ ኀጢአት ዕለት ዕለት መሥዋዕትን ሊያቀርብ አያስፈልገውም፤ ራሱን ባቀረበ ጊዜ ይህን አንድ ጊዜ ፈጽሞ አድርጎአልና።'),
  ('885eac7a-87d1-58de-abf8-df85d8102fe0', '1359e415-d703-58b8-a702-3bd1904375ea', '3b018989-0e85-5a16-af1f-c0d36651680f', 28, 28, 'ኦሪትስ የሚሞት ሰውን ሊቀ ካህናት አድርጋ ትሾማለች፤ ከኦሪት በኋላ የመጣው የእግዚአብሔር የመሐላ ቃሉ ግን ዘለዓለም የማይለወጥ ፍጹም ወልድን ካህን አድርጎ ሾመልን።'),
  ('81ab291b-4abc-57d7-a3c9-e0303041ed45', 'f13d6542-db7b-5b52-abe0-a8c15fd461a9', '980993a1-24e8-517d-a6c9-c6264f6fe55b', 1, 1, 'ከተናገርነውም ዋናው ነገር ይህ ነው፤ በሰማያት በግርማው ዙፋን ቀኝ የተቀመጠ እንዲህ ያለ ሊቀ ካህናት አለን።'),
  ('e2d45c91-9aa3-5197-ae48-c5631d471251', 'f13d6542-db7b-5b52-abe0-a8c15fd461a9', '980993a1-24e8-517d-a6c9-c6264f6fe55b', 2, 2, 'እርሱም የመቅደስና የእውነተኛይቱ ድንኳን አገልጋይ ነው፤ እርስዋም በሰው ሳይሆን በእግዚአብሔር የተተከለች ናት።'),
  ('a3ea7f5d-a35a-5b8d-aa72-da96a7a67de5', 'f13d6542-db7b-5b52-abe0-a8c15fd461a9', '980993a1-24e8-517d-a6c9-c6264f6fe55b', 3, 3, 'ሊቀ ካህናት ሁሉ መባንና መሥዋዕትን ያቀርብ ዘንድ ይሾማል፤ ለዚህም ደግሞ የሚያቀርበው አንዳች ነገር ይኖረው ዘንድ ይገባል።'),
  ('3c41ac0b-5e67-5c82-a65b-ecba1daf6ade', 'f13d6542-db7b-5b52-abe0-a8c15fd461a9', '980993a1-24e8-517d-a6c9-c6264f6fe55b', 4, 4, 'በምድር ቢሆን ኖሮ፥ ሊቀ ካህናት ባልሆነም ነበር፤ በኦሪት ሕግ መሥዋዕት የሚያቀርቡ ካህናት በእርስዋ አሉና።'),
  ('62a88ef3-035e-5dea-a476-1c29bdfab28e', 'f13d6542-db7b-5b52-abe0-a8c15fd461a9', '980993a1-24e8-517d-a6c9-c6264f6fe55b', 5, 5, 'እነርሱም ሙሴ ድንኳኒቱን ሲሠራ ሳለ እንደ ተረዳ፥ ለሰማያዊ ነገር ምሳሌና ጥላ የሚሆነውን ያገለግላሉ፤ “በተራራው እንደ ተገለጠልህ ምሳሌ ሁሉን ታደርግ ዘንድ ተጠንቀቅ” ብሎት ነበርና።'),
  ('8b837449-458b-514e-a95f-602c3beb9610', 'f13d6542-db7b-5b52-abe0-a8c15fd461a9', '980993a1-24e8-517d-a6c9-c6264f6fe55b', 6, 6, 'ዛሬ ግን ኢየሱስ ክርስቶስ የምትበልጠውን አገልግሎት ገንዘብ አደረገ፤ ለታላቂቱ ሥርዐትም መካከለኛ ሆነ፤ የምትበልጠውንም ተስፋ ሠራ።'),
  ('487ce86c-3cf4-56b7-ac50-e9b5ca739afc', 'f13d6542-db7b-5b52-abe0-a8c15fd461a9', '980993a1-24e8-517d-a6c9-c6264f6fe55b', 7, 7, 'ፊተኛይቱ ያለ ነቀፋ ብትሆን ኖሮ ሁለተኛይቱን ባልፈለገም ነበር።'),
  ('8f0eeaed-fb8b-5c64-aee9-bbb001f6a4bd', 'f13d6542-db7b-5b52-abe0-a8c15fd461a9', '980993a1-24e8-517d-a6c9-c6264f6fe55b', 8, 8, 'ነገር ግን እነርሱን ነቅፎ እንዲህ አለ፥ “እነሆ፥ ለቤተ እስራኤልና ለቤተ ይሁዳም አዲስ ኪዳን የምሠራበት ዘመን ይመጣል ይላል እግዚአብሔር።'),
  ('e48ffacd-002a-5047-a403-e0a39c5851ee', 'f13d6542-db7b-5b52-abe0-a8c15fd461a9', '980993a1-24e8-517d-a6c9-c6264f6fe55b', 9, 9, 'እጃቸውን ይዤ ከምድረ ግብፅ ባወጣኋቸው ጊዜ ለአባቶቻቸው እንደ ገባሁት እንደዚያ ያለ ኪዳን አይደለም፤ እነርሱ በኪዳኔ አልኖሩምና፤ እኔም ቸል ብያቸዋለሁና” ይላል እግዚአብሔር።'),
  ('a1067938-b171-5161-ace5-21adbfe3d4fd', 'f13d6542-db7b-5b52-abe0-a8c15fd461a9', '980993a1-24e8-517d-a6c9-c6264f6fe55b', 10, 10, 'ከእነዚያ ዘመናት በኋላ ለቤተ እስራኤል የምገባው ቃል ይህ ነው፦ ሕጌን በልባቸው አሳድራለሁ፤ በሕሊናቸውም እጽፈዋለሁ፤ አምላክ እሆናቸዋለሁ፤ እነርሱም ሕዝቤ ይሆኑኛል ይላል እግዚአብሔር።'),
  ('af099320-e12e-514c-ad51-967985391bd0', 'f13d6542-db7b-5b52-abe0-a8c15fd461a9', '980993a1-24e8-517d-a6c9-c6264f6fe55b', 11, 11, 'እንግዲህ አንዱ ሌላውን አያስተምርም፤ ወንድምም ወንድሙን እግዚአብሔርን ዕወቅ ብሎ አያስተምርም፤ ከታናሹ ጀምሮ እስከ ታላቁ ድረስ ሁሉ ያውቁኛልና።'),
  ('24bbc7a8-a5da-53c6-af11-3207f6d8311d', 'f13d6542-db7b-5b52-abe0-a8c15fd461a9', '980993a1-24e8-517d-a6c9-c6264f6fe55b', 12, 12, 'ዐመፃቸውን እምራቸዋለሁና ኀጢአታቸውንም ደግሜ አላስብም።”'),
  ('3a785681-037d-5e98-a775-8c943d1e4b6e', 'f13d6542-db7b-5b52-abe0-a8c15fd461a9', '980993a1-24e8-517d-a6c9-c6264f6fe55b', 13, 13, 'አዲስ ትእዛዝ በማለቱ የቀደመችቱን አስረጃት፤ አሮጌና ውራጅ የሆነውስ ለጥፋት የቀረበ ነው።'),
  ('ae3c9607-58f2-5416-a368-0654edba5272', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 1, 1, 'ፊተኛይቱም ደግሞ የአገልግሎት ሥርዐትና የዚህ ዓለም የሆነው መቅደስ ነበራት።'),
  ('c85de72e-901c-5a1e-acbe-db835165bfc3', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 2, 2, 'የመጀመሪያዪቱም ድንኳን ተዘጋጅታ ነበርና፥ በእርስዋም ቅድስት በምትባለው ውስጥ መቅረዙና ጠረጴዛው፥ የመሥዋዕቱም ኅብስት ነበረባት።'),
  ('eeaf947c-8b1b-534e-a464-2729d3effb2f', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 3, 3, 'ከሁለተኛው መጋረጃ በስተኋላ የነበረችውን የውስጠኛዪቱን ድንኳን ግን ቅድስተ ቅዱሳን ይሉአት ነበር።'),
  ('d1db404a-11a4-5386-a16a-ba792faf6b98', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 4, 4, 'በውስጥዋም የወርቅ ማዕጠንትና ሁለንተናዋን በወርቅ የለበጡአት፥ የኪዳን ታቦት፥ መና ያለባት የወርቅ መሶብና የለመለመችው የአሮን በትር፥ የኪዳኑም ጽላት ነበሩባት።'),
  ('c4ea9b9f-d91d-5233-ac08-1006ba859180', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 5, 5, 'በላይዋም ማስተስረያውን የሚጋርዱ የክብር ኪሩቤል ነበሩ፤ ነገር ግን በየመልኩ እናገረው ዘንድ ዛሬ ጊዜው አይደለም።'),
  ('c785e7b2-a0b5-538a-aa4c-a1755f77412e', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 6, 6, 'ሥርዐቱ፥ ዝግጅቱም እንዲህ ነበር፤ በመጀመሪያዪቱም ድንኳን በየጊዜው አገልግሎታቸውን ይፈጽሙ ዘንድ፥ ካህናት ዘወትር ይገቡ ነበር።'),
  ('77619a8e-5acb-57d9-a574-92781afd0398', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 7, 7, 'ወደ ሁለተኛዪቱ ክፍል ግን ሊቀ ካህናቱ ኀጢአታቸውን ለማስተስረይ ስለ ራሱና ስለ ሕዝቡ የሚያቀርበውን ደም ይዞ፥ በየዓመቱ አንድ ጊዜ ብቻውን ይገባ ነበር።'),
  ('aa1188da-268a-59e0-abb6-1e54bd3fea3e', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 8, 8, 'ፊተኛይቱም ድንኳን በዚህ ገና ቆማ ሳለች፥ ወደ ቅድስት የሚወስደው መንገድ ገና እንዳልተገለጠ መንፈስ ቅዱስ ያሳያል።'),
  ('5f940557-2fd8-5286-a773-43e44847e10d', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 9, 9, 'ነገር ግን ለሚያቀርበው ሰው ግዳጅ መፈጸም የማይቻለውን መባና መሥዋዕት ያቀርቡበት የነበረው ለዚህ ዘመን ምሳሌ ሆነ።'),
  ('4b7250e7-3bbf-5ee1-a63e-c3c2eecc429d', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 10, 10, 'እነዚህም እስከ መታደስ ዘመን ድረስ የተደረጉ፥ ስለ ምግብና ስለ መጠጥም፥ ስለ ልዩ ልዩ ጥምቀትም የሚሆኑ የሥጋ ሥርዐቶች ብቻ ናቸው።'),
  ('3e46aa56-3101-5a26-a55b-54104a174581', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 11, 11, 'ክርስቶስ ግን ለምትመጣይቱ መልካም ነገር ሊቀ ካህናት ሆኖ፥ የሰው እጅ ወደ አልሠራት፥ በዚህ ዓለም ወደ አልሆነችው፥ ከፊተኛዪቱ ወደምትበልጠውና ወደምትሻለው ድንኳን፥'),
  ('516dbccb-32be-5d20-a693-e68de32e10a3', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 12, 12, 'የዘለዓለም መድኀኒትን ገንዘብ አድርጎ፥ በገዛ ደሙ አንድ ጊዜ ወደ መቅደስ ገባ እንጂ በላምና በፍየል ደም አይደለም።'),
  ('fc65cf6c-2366-5df6-a643-8200063b33d0', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 13, 13, 'የላምና የፍየል ደም፥ በረከሱትም ላይ የሚረጭ የጊደር አመድ፥ የሚያነጻና የረከሱትንም ሥጋቸውን የሚቀድሳቸው ከሆነ፥'),
  ('0f4e89f0-639a-5307-ae2f-df3ad3a6b9af', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 14, 14, 'ነውር የሌለው ሆኖ፥ በዘለዓለም መንፈስ ራሱን ለእግዚአብሔር ያቀረበ የክርስቶስ ደም ሕያው እግዚአብሔርን እናመልከው ዘንድ ሕሊናችንን ከሞት ሥራ እንዴት ይልቅ ያነጻ ይሆን?'),
  ('e5fbccd9-81a5-53f8-a831-d2cfc943964e', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 15, 15, 'ስለዚህ ኢየሱስ ሞትን ተቀብሎ፥ በቀደመው ሥርዐት ስተው የነበሩትን ያድናቸው ዘንድ ወደ ዘለዓለም ርስቱም የጠራቸው ተስፋውን ያገኙ ዘንድ፥ ለአዲሲቱ ኪዳን መካከለኛ ሆነ።'),
  ('081c8852-6562-5419-a613-f62898993eac', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 16, 16, 'ኑዛዜ ያለ እንደሆነ የተናዛዡ ሰው ሞት ይመጣ ዘንድ ግድ ነው።'),
  ('7cec35b3-cc34-5914-a63b-33a2d9b6ef16', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 17, 17, 'የሙአች ሰው ኑዛዜ የጸናች ናት፤ ተናዛዡ በሕይወት ባለበት ጊዜ አትጠቅምምና።'),
  ('699ffed7-e45c-54c4-ac81-dcb02c7758e5', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 18, 18, 'ስለዚህም ፊተኛው ኪዳን እንኳ ያለ ደም አልከበረም።'),
  ('2f74304c-5cb9-5a00-a4f4-e48080af02fa', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 19, 19, 'ሙሴ የኦሪትን ትእዛዝ ሁሉ ለመላው ሕዝብ ከነገረ በኋላ፥ የላምና የፍየል ደም ከውኃ ጋር ቀላቅሎ፥ ቀይ የበግ ጠጕርና የስሚዛ ቅጠል ነክሮ መጽሐፈ ኦሪቱንና ሕዝቡን ሁሉ ይረጭ ነበር።'),
  ('b2238fbd-b201-57d1-af38-e2500f0dc354', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 20, 20, '“እግዚአብሔር ያዘዛችሁ የኪዳኑ ደም ይህ ነው” ይላቸው ነበር።'),
  ('a89cf1e6-91ba-5c93-a90c-77651ae8af9c', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 21, 21, 'ድንኳኑንና የመገልገያውን ዕቃ ሁሉ በደሙ ይረጭ ነበር።'),
  ('9c6d95be-2ab5-53e6-a093-47c1c70b53eb', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 22, 22, 'ደግሞም በቀረበው ሁሉ እንዲህ ያደርግ ነበር፥ በኦሪት ሕግ ሁሉ በደም ይነጻ ነበር፤ ደም ሳይረጭ ግን አይሰረይም ነበር።'),
  ('53507877-b1fa-5c4a-af44-ea14a31a4297', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 23, 23, 'በሰማይ ባለው አምሳል የተሠራው ይህ ሥራ፥ በዚህ ደም የሚነጻ ከሆነ፥ ይህ ሰማያዊ መሥዋዕትስ ከዚህ ይበልጣል።'),
  ('3d38486c-150b-5bf8-a3c9-0891c6163455', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 24, 24, 'ክርስቶስ በእጅ ወደ ተሠራች የእውነተኛይቱ ምሳሌ ወደምትሆን ቅድስት አልገባምና፥ ነገር ግን በእግዚአብሔር ፊት ስለ እኛ አሁን ይታይ ዘንድ፥ ወደ እርስዋ ወደ ሰማይ ገባ።'),
  ('58d9615c-fbfd-50d9-a6a4-c82f47d38b0b', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 25, 25, 'ሊቀ ካህናቱ ያደርገው እንደ ነበረ፥ በያመቱም ደም ይዞ ወደ ቅድስት ይገባ እንደ ነበረ ዘወትር ራሱን የሚሠዋ አይደለም።'),
  ('fc54f591-152c-50ac-a2bb-088ffaff4339', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 26, 26, 'ይህስ ባይሆን ዓለም ከተፈጠረ ጀምሮ ብዙ ጊዜ በሞተ ነበር፤ አሁን ግን በዓለም ፍጻሜ፥ ራሱን በመሠዋት ኀጢአትን ይሽራት ዘንድ አንድ ጊዜ ተገለጠ።'),
  ('42803491-0a1c-5b6b-a372-804a7f037fc6', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 27, 27, 'ለሰው አንድ ጊዜ ሞት፥ ከዚያም በኋላ ፍርድ እንደሚጠብቀው፥'),
  ('8feb13af-3bb9-5ee0-a88a-8a272a6bdf29', 'e3f91808-f392-57cf-a17b-6e3b0da01567', '0f9376a1-7f72-59e7-a6cc-6781912c1dd7', 28, 28, 'እንዲሁ ክርስቶስም የብዙዎችን ኀጢአት ያስተሰርይ ዘንድ ራሱን አንድ ጊዜ ሠዋ፤ በኋላ ግን ያድናቸው ዘንድ ተስፋ ለሚያደርጉት ያለ ኀጢአት ይገለጥላቸዋል።'),
  ('bee88a09-c5a8-55b2-ac42-9fec798727a9', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 1, 1, 'ሕጉ ሊመጣ ያለው የበጎ ነገር እውነተኛ አምሳል ሳይሆን የነገር ጥላ አለውና፤ ስለዚህም በየዓመቱ ዘወትር በሚያቀርቡት በዚያ መሥዋዕት የሚቀርቡትን ሊፈጽም ከቶ አይችልም።'),
  ('21bc6190-b7e6-5b99-a0e0-13f2706aa477', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 2, 2, 'ይህስ ባይሆን ከሚሠዉት መሥዋዕት ባረፉ ነበር፥ ለሚሠዉት ኀጢአታቸውን ያስተሰርይላቸው ነበርና፥ ባአንድ ጊዜም ያነጻቸው ነበርና።'),
  ('b05e5a5a-f630-5cc9-a8ff-6dc67188a108', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 3, 3, 'ነገር ግን በዚያው መሥዋዕት በየዓመቱ የኀጢአት መታሰቢያ አድርገው የሚያቀርቡት ነበራቸው።'),
  ('888772ea-00c2-5c20-a4de-886153ecad21', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 4, 4, 'የላምና የፍየል ደም ኀጢአትን ሊያስተሰርይ አይችልምና።'),
  ('6cfef24f-cbee-598e-a82b-50690c840fa7', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 5, 5, 'ስለዚህም ወደ ዓለም በሚመጣበት ጊዜ እንዲህ አለ፥ “መሥዋዕትንና ቍርባንን አልወደድህም፤ ሥጋን አለበስኸኝ እንጂ።'),
  ('cf689e6c-8838-5fee-a213-580d9a07354b', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 6, 6, 'በሚቃጠል መሥዋዕትና ስለ ኀጢአት በሚቀርበው መሥዋዕት ደስ አላለህም።'),
  ('93be08b3-8648-581f-adea-8f73d02b6319', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 7, 7, 'ያንጊዜ እነሆ፥ በመጽሐፍ ራስ ስለ እኔ እንደ ተጻፈ፥ አምላኬ ሆይ፥ ፈቃድህን አደርግ ዘንድ መጥቻለሁ አልሁ።”'),
  ('9b1a1b9c-aab2-53a1-aa1c-31acb12058ef', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 8, 8, 'በዚህ ላይ “መሥዋዕትንና መባን፥ በሙሉ የሚቃጠል መሥዋዕትንም፥ ስለ ኀጢአትም የሚሠዋ መሥዋዕትን አልወደድህም፤ በእርሱም ደስ አላለህም” ብሎ ተናገረ፤ እነዚህም እንደ ሕግ የሚቀርቡ ናቸው።'),
  ('2a601ad7-3425-592c-a95a-0a1c2de42b2b', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 9, 9, 'ከዚህ በኋላ፥ “አምላኬ ሆይ፥ ፈቃድህን አደርግ ዘንድ እነሆ፥ መጣሁ” አለ፤ ይህ ቃል የኋለኛውን ያቆም ዘንድ የፊተኛውን ያፈርሳል።'),
  ('ad56fcc2-7eb7-5ac6-a6c5-c4fa140ac533', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 10, 10, 'በፈቃዱም አንድ ጊዜ በተደረገው በኢየሱስ ክርስቶስ በሥጋዉ ቍርባን ተቀደስን።'),
  ('56eead77-5d4e-5548-a8c8-e3782ec6e5a0', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 11, 11, 'ሊቀ ካህናትም ሁሉ ዘወትር እያገለገለ ይቆም ነበር፤ ፈጽሞ ኀጢአት ማስተስረይ የማይቻላቸውን እነዚያን መሥዋዕቶች ብቻም ይሠዋ ነበር።'),
  ('108869a3-9399-571e-a343-586f880a781d', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 12, 12, 'እርሱ ግን ስለ ኀጢአት አንድን መሥዋዕት ለዘለዓለም አቅርቦ በእግዚአብሔር ቀኝ ተቀመጠ።'),
  ('4529ecbf-e41e-5cc0-aee4-5caef34c2ce6', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 13, 13, 'እንግዲህ ጠላቶቹ ከእግሩ በታች እስኪወድቁ ድረስ ይጠብቃል።'),
  ('c240076d-c629-5f74-a3d3-e5425bb95c5c', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 14, 14, 'ለሚቀደሱትም ለዘለዓለም የምትሆን አንዲት መሥዋዕትን ሠዋ።'),
  ('7d01b1e3-37b8-5ae2-ab8c-f829ebce8d24', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 15, 15, 'መንፈስ ቅዱስም ምስክራችን ነው።'),
  ('1c916324-8953-5ae4-acdb-52f38fa83fa4', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 16, 16, '“ከእነዚያ ወራቶች በኋላ የምገባላቸው ኪዳን ይህቺ ናት ይላል እግዚአብሔር፤ ሕጌን በልባቸው አኖረዋለሁ፤ በልቡናቸውም እጽፈዋለሁ ካለ በኋላ።'),
  ('09d964a8-2440-5b36-a6e7-f95513248016', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 17, 17, 'ከእንግዲህ ወዲህ ኀጢአታቸውንና በደላቸውን ደግሜ አላስብባቸውም” ብሏል።'),
  ('e755a401-4ab1-54d9-a873-546d78cf3b47', '22c89b56-16e1-5183-a002-61e6af257092', '85565b1a-6ec0-54f0-a3bc-406130fd9295', 18, 18, 'እንዲህም ኀጢአት የሚሰረይ ከሆነ፥ እንግዲህ ወዲህ ስለ ኀጢአት መሥዋዕት አያስፈልግም።'),
  ('0d2d90bd-db6f-5300-ada9-a1d867211d24', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 1, 19, 'እንግዲህ ወንድሞቻችን ሆይ፥ በኢየሱስ ክርስቶስ ደም ወደ መቅደስ ለመግባት ባለሙአልነት አለን።'),
  ('2583ff87-08e6-50bb-ac3f-86ae82a9fba8', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 2, 20, 'በሥጋው መጋረጃ በኩል የሕይወትንና የጽድቅን መንገድ ፈጽሞ አድሶልናልና።'),
  ('e2a1966f-ca61-5a9c-ae4b-6ba867720273', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 3, 21, 'በእግዚአብሔር ቤት ታላቅ ካህን አለን።'),
  ('c68540e1-757b-5054-aee4-075db0471303', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 4, 22, 'እንግዲህ ከክፉ ሕሊና ለመንጻት ልባችንን ተረጭተን፥ ሰውነታችንንም በጥሩ ውኃ ታጥበን በተረዳንበት እምነት በቅን ልብ እንቅረብ።'),
  ('afbc64d6-34ec-58e7-a701-527851f6e529', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 5, 23, 'እንግዲህ የማይናወጠውን የተስፋችንን እምነት እናጽና፤ ተስፋ የሰጠ እርሱ የታመነ ነውና።'),
  ('cebf6da6-b858-5127-a487-0a96cf239e07', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 6, 24, 'በፍቅርና በበጎ ምግባርም ከባልንጀሮቻችን ጋር እንፎካከር።'),
  ('e70db7d0-a625-55da-ab94-0ee3b007a3c9', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 7, 25, 'ሌሎች ልማድ አድርገው እንደ ያዙት ማኅበራችንን አንተው፤ እርስ በርሳችን እንመካከር እንጂ፤ ይልቁንም ቀኑ ሲቀርብ እያያችሁ አብልጣችሁ ይህን አድርጉ።'),
  ('d02dfdf2-75f0-5e37-a0d9-a50091da250d', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 8, 26, 'እውነትን ካወቅናት በኋላ፥ ተጋፍተን ብንበድል ከእንግዲህ ወዲህ ስለ ኀጢአት መሥዋዕት አይኖርም።'),
  ('ad7f845c-d6f1-5226-af36-e6b276dffd3c', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 9, 27, 'ነገር ግን የሚያስፈራ ፍርድ ከሓዲዎችንም የሚበላቸው የቅናት እሳት ይጠብቃቸዋል።'),
  ('e6424339-b35b-5920-a4de-4775ab8ffbb7', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 10, 28, 'ከሙሴ ሕግ የተላለፈ ቢኖር ሁለት፥ ወይም ሦስት ምስክሮች ከመሰከሩበት ያለ ምሕረት ይሞታል።'),
  ('a6cced35-184d-5a45-a869-ce0beed1aa08', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 11, 29, 'የእግዚአብሔርን ልጅ የከዳ፥ ያንንም የተቀደሰበትን የኪዳኑን ደም እንደ ርኩስ ነገር የቈጠረ፥ የጸጋውንም መንፈስ ያክፋፋ እንዴት ይልቅ የሚብስ ቅጣት የሚገባው ይመስላችኋል?'),
  ('20da6d6e-b283-5fc8-a950-3c63ac39d8b3', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 12, 30, '“እኔ እበቀላለሁ፤ እኔም ብድራትን እመልሳለሁ፥” ያለውን እናውቀዋለንና፤ ዳግመኛም “እግዚአብሔር በሕዝቡ ላይ ይፈርዳል።”'),
  ('9a2306ad-547c-56ad-ad37-0842ae9aad51', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 13, 31, 'በሕያው እግዚአብሔር እጅ መውደቅ እጅግ የሚያስፈራ ነው።'),
  ('179efc6f-3a69-58ef-a009-d8177c2162a2', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 14, 32, 'እናንተ የተጠመቃችሁበትንና ብዙ መከራ የታገሣችሁበትን የቀደመውን ዘመን አስቡ፤'),
  ('aca07f82-7b8b-5c67-a5b6-1ffd4405e45d', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 15, 33, 'እናንተ ተሰድባችሁ ነበር፤ መከራም አጽንተውባችሁ ነበር፤ ተዘባብተውባችሁም ነበር፤ በዚህም መንገድ እንዲህ ከሆኑት ጋር ተባብራችሁ ነበር።'),
  ('9d4861a3-717f-5936-a107-f4da80c15dc6', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 16, 34, 'በእስራቴም ጊዜ ከእኔ ጋር በመከራ ተባብራችኋል፤ የገንዘባችሁንም መዘረፍ በደስታ ተቀብላችኋል፤ በሰማያት ለዘለዓለም የሚኖር ከዚህ የሚበልጥና የተሻለ ገንዘብ እንዳላችሁ ታውቃላችሁና።'),
  ('1edc80ab-956e-56b0-a4b0-75ab6e4c1881', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 17, 35, 'ትልቁን ዋጋችሁን የምታገኙባትን መታመናችሁን አትጣሉ።'),
  ('fc001cb3-8e39-50b6-a207-8682d6df231d', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 18, 36, 'ነገር ግን የእግዚአብሔርን ፈቃድ አድርጋችሁ የተሰጣችሁን ተስፋ ታገኙ ዘንድ መታገሥ ያስፈልጋችኋል።'),
  ('9fd557d6-56ec-5173-adfe-15393ea4fde1', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 19, 37, '“ገና ጥቂት ቀን አለና፤ የሚመጣውም ፈጥኖ ይደርሳል፥ አይዘገይምም።'),
  ('1aa24ff2-25f8-5c30-a2a8-e77e9868c1fe', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 20, 38, 'ጻድቅ በእምነት ይድናል፤ ወደኋላ ቢመለስ ግን ልቡናዬ በእርሱ ደስ አይላትም።”'),
  ('4bee12bd-cddc-5288-a8a9-d55af51b42c3', '22c89b56-16e1-5183-a002-61e6af257092', '16e5703f-e589-5bbd-a595-ffe5ffdc6dff', 21, 39, 'እኛ ግን ነፍሳቸውን ሊያድኑ ከሚያምኑት ነን እንጂ ወደ ጥፋት ከሚያፈገፍጉት አይደለንም።'),
  ('e28e7456-df2e-5af4-aee7-c66bbee1dd13', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 1, 1, 'እምነትስ ተስፋ ስለምናደርገው ነገር የምታረጋግጥ፥ የማናየውንም ነገር የምታስረዳ ናት።'),
  ('52955886-b6f6-5e8a-aa4c-b0bf19423c0a', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 2, 2, 'በዚህም ለሽማግሌዎች ተመሰከረላቸው።'),
  ('34f794a1-ca75-5d62-aac2-c6c627b8c8cc', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 3, 3, 'ዓለም በእግዚአብሔር ቃል እንደ ተፈጠረ፥ የሚታየውም ነገር ከማይታየው እንደ ሆነ በእምነት እናውቃለን።'),
  ('68834531-506c-5803-a981-9db18b219c40', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 4, 4, 'አቤል ከቃኤል ይልቅ የሚበልጥ መሥዋዕትን ለእግዚአብሔር በእምነት አቀረበ፤ በዚህም ጻድቅ እንደ ሆነ ተመሰከረለት፤ ምስክሩም መሥዋዕቱን በመቀበል እግዚአብሔር ነው። በዚህም ከሞተ በኋላ እንኳ ተናገረ።'),
  ('a4dbe55e-be24-5774-af26-2b07c53f6cb4', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 5, 5, 'ሄኖክ ሞትን እንዳያይ በእምነት ተወሰደ፤ እግዚአብሔርም ስለ ወሰደው አልተገኘም፤ ሳይወሰድም እግዚአብሔርን ደስ እንደ አሰኘው ተመስክሮለታል።'),
  ('fb78c632-0602-533e-a8fe-e6dae96fbeeb', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 6, 6, 'ያለ እምነትም እግዚአብሔርን ደስ ማሰኘት አይቻልም፤ ወደ እግዚአብሔር የሚቀርብ ሰው አስቀድሞ እግዚአብሔር እንዳለ፥ ለሚሹትም ዋጋ እንደሚሰጣቸው ሊያምን ይገባዋል።'),
  ('4c24c258-538d-59ad-a651-43dc6421dc37', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 7, 7, 'ኖኅም ስለማይታየው ነገር የነገሩትን ባመነ ጊዜ ፈራ፤ ቤተ ሰቡንም ያድን ዘንድ ክፍል ያላት መርከብን ሠራ፤ በዚህም ዓለምን አስፈረደበት፤ በእምነትም የሚገኘውን ጽድቅ ወራሽ ሆነ።'),
  ('9a74e7b4-b739-5881-a5e3-5c7e53433052', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 8, 8, 'አብርሃም በተጠራ ጊዜ ርስት አድርጎ ይወርሰው ዘንድ ወዳለው ሀገር ለመሄድ በእምነት ታዘዘ፤ ወዴት እንደሚደርስም ሳያውቅ ሄደ።'),
  ('fd4c93dd-edfa-5744-abf8-dda610e61fa0', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 9, 9, 'በእምነትም ከሀገሩ ወጥቶ ተስፋ በሰጠው ሀገር እንደ ስደተኛ በድንኳን፥ ተስፋውን ከሚወርሱአት ከይስሐቅና ከያዕቆብ ጋር ኖረ።'),
  ('3cea6686-9733-5431-a652-690e9330cf0d', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 10, 10, 'መሠረት ያላትን ሠሪዋና ፈጣሪዋ እግዚአብሔር የሆነላትን ከተማ ደጅ ይጠኑ ነበርና።'),
  ('15967262-35e9-5ad8-a4e6-1929e83e3bb0', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 11, 11, 'ራስዋ ሳራም መካን ሳለች ባረጀችበት ወራት ዘር ታስገኝ ዘንድ በእምነት ኀይልን አገኘች፤ ተስፋ የሰጣት የታመነ እንደ ሆነ አምናለችና።'),
  ('8e72d699-7e08-5b28-aeca-86adbb002c4d', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 12, 12, 'ስለዚህም ደግሞ በብዛታቸው እንደ ሰማይ ኮከብ፥ እንደማይቈጠርም በባሕር ዳር እንዳለ አሸዋ የነበሩት የሞተን ሰው እንኳ ከመሰለው ከአንዱ ተወለዱ።'),
  ('dab1de1c-1c94-5d02-af8e-4aec87c621e6', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 13, 13, 'እነዚህ ሁሉ አምነው ሞቱ፤ ተስፋቸውንም አላገኙም፤ ነገር ግን ከሩቅ አይተው እጅ ነሱኣት፤ በምድሪቱም ላይ እነርሱ እንግዶችና መጻተኞች እንደ ሆኑ ዐወቁ።'),
  ('7a6d33de-abb4-5c92-aa2f-be63e82130dc', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 14, 14, 'እንዲህ የሚሉ ግን ሀገራቸውን እንደሚሹ ያሳያሉ።'),
  ('187ca62e-f201-5d67-a551-41f645a0ac52', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 15, 15, 'ከእርስዋ የወጡባትን ሀገር ቢሹ ኖሮስ፥ ወደ እርስዋ ሊመለሱ በተቻላቸው ነበር።'),
  ('c301fce4-98c4-5d3a-a80b-f6f352a4d147', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 16, 16, 'አሁን ግን፥ በሰማያት ያለችውን የምትበልጠውን ሀገር ተስፋ ያደርጉ እንደ ነበር ታወቀ፤ ስለዚህም እግዚአብሔር አምላካቸው ተብሎ ይጠራ ዘንድ በእነርሱ አያፍርም፤ ተስፋ ያደረጉአትን ሀገር አዘጋጅቶላቸዋልና።'),
  ('96a44ab3-4e95-5125-a7ea-80ef00cbd23b', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 17, 17, 'አብርሃምም እግዚአብሔር በፈተነው ጊዜ ልጁን ይስሐቅን ይሠዋው ዘንድ በእምነት ወሰደው።'),
  ('756d8742-06b3-5018-a03d-b664138d28d5', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 18, 18, '“በይስሐቅ ዘር ይጠራልሃል” ብሎ ተስፋ ያናገረለትን አንድ ልጁን አቀረበው።'),
  ('0ebdc267-8a39-5a96-ab89-375eb3ae259b', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 19, 19, 'እግዚአብሔር ከሙታን ለይቶ ሊያስነሣው እንደሚችል አምኖአልና፤ ስለዚህም ያው የተሰጠው መታሰቢያ ሆነለት።'),
  ('0b4cf6b8-6540-543e-a716-0fbf4255aa6a', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 20, 20, 'ያገኙት ዘንድ ስለ አላቸው ነገር ይስሐቅ ያዕቆብንና ኤሳውን በእምነት ባረካቸው።'),
  ('896c20f1-37a9-54ee-a667-5d790ff57475', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 21, 21, 'ያዕቆብም በሚሞትበት ጊዜ የዮሴፍን ልጆች እያንዳንዳቸውን በእምነት ባረካቸው፤ በበትሩ ጫፍም ሰገደ።'),
  ('136fe1b3-0bfa-5059-ad37-4651d533985d', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 22, 22, 'ዮሴፍም በሚሞትበት ጊዜ፥ ስለ እስራኤል ልጆች ከግብፅ መውጣት በእምነት ዐሰበ፤ ዐጽሙንም ትተው እንዳይወጡ አዘዘ።'),
  ('91752f45-07b2-5e76-aa5f-b4dcf055265c', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 23, 23, 'ሙሴ በተወለደ ጊዜ በእምነት ሦስት ወር በአባቱ ቤት ሸሸጉት፤ ሕፃኑ መልካም እንደ ሆነ አይተውታልና፤ የንጉሥንም ትእዛዝ አልፈሩም።'),
  ('8bea26f8-2e24-586a-acf8-950a092ccb0f', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 24, 24, 'ሙሴም በአደገ ጊዜ የፈርዖን የልጅ ልጅ እንዳይባል በእምነት እንቢ አለ፤'),
  ('06800813-6054-50ba-a986-7cdaaa103824', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 25, 25, 'ለጊዜው በኀጢአት ከሚገኝ ደስታ ይልቅ ከእግዚአብሔር ሕዝብ ጋር መከራ መቀበልን መረጠ።'),
  ('fb3e224e-984b-5ba7-a838-605c59fa1725', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 26, 26, 'የክርስቶስ የመስቀሉ ተግዳሮት ከግብፅ ሀብት ሁሉ ይልቅ እጅግ የሚበልጥ ባለጠግነት እንደሚሆን ዐውቆአልና፥ ዋጋውንም ተመልክቶአልና።'),
  ('34e5ac13-5081-5627-ae3c-385ffcb803f2', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 27, 27, 'የንጉሡንም ቍጣ ሳይፈራ፥ የግብፅን ሀገር በእምነት ተወ፤ ከሚያየው ይልቅ የማይታየውን ሊፈራ ወዶአልና።'),
  ('a3d85e4e-f2c3-5bae-a14e-dd6bc6a9355e', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 28, 28, 'ቸነፈር በኵራቸውን እንዳያጠፋባቸው በእምነት ፋሲካን አደረገ፤ ደሙንም ረጨ።'),
  ('089c97ce-f17d-546c-a2db-21e57d945e33', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 29, 29, 'በደረቅ ምድር እንደ መሄድ የኤርትራን ባሕር በእምነት ተሻገሩአት፤ የግብፅ ሰዎች ግን ሲሞክሩ ሰጠሙ።'),
  ('0790199d-ece4-5534-a439-6dea4a07ebba', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 30, 30, 'ሰባት ቀን ከዞሩአት በኋላ የኢያሪኮ ቅጽር በእምነት ወደቀ።'),
  ('2c3a80d4-46d7-50da-af13-7f639d85ce68', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 31, 31, 'ዘማ ረአብም በእምነት ከከሓዲዎች ጋር አልጠፋችም፤ ጕበኞችን በሰላም ተቀብላ ሰውራቸዋለችና።'),
  ('df85f2be-8104-5294-aeab-879954e8d545', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 32, 32, 'እንግዲህ ምን እላለሁ? ስለ ጌዴዎን፥ ስለ ባርቅ፥ ስለ ሶምሶን፥ ስለ ዮፍታሔ፥ ስለ ዳዊት፥ ስለ ሳሙኤልና ስለ ሌሎች ነቢያት እነግራችሁ ዘንድ ጊዜዬ አጭር ነውና።'),
  ('02251d03-c3f4-550d-afcb-dd48c2e05393', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 33, 33, 'እነርሱ በእምነት ተጋደሉ፤ ነገሥታትን ድል ነሡ፤ ጽድቅን አደረጉ፤ ተስፋቸውን አገኙ፤ የአናብስትንም አፍ ዘጉ ።'),
  ('6db35c21-37dc-5d09-aeec-f222de58c20b', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 34, 34, 'የእሳት ኀይልን አጠፉ፤ ከሰይፍ ስለት አመለጡ፤ ከድካማቸው በረቱ፤ በጦርነት ኀይለኞች ሆኑ፤ የባዕድ ጭፍሮችንም አባረሩ።'),
  ('afde474d-52b0-5d19-ad11-7795846b6d0d', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 35, 35, 'ሴቶችም እንደ ትንሣኤ ቀን ተነሥተውላቸው ሙታኖቻቸውን ተቀበሉ፤ ተፈርዶባቸው የሞቱም አሉ፤ የምትበልጠውን ሕይወት ያገኙ ዘንድ ሊድኑ አልወደዱምና።'),
  ('c027f98a-623b-5dca-a288-a65957b87313', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 36, 36, 'የገረፉአቸው፥ የዘበቱባቸውና ያሠሩአቸው ወደ ወህኒ ያገቡአቸውም አሉ።'),
  ('f7e960c8-9f57-5f5c-a1f5-b48b5d215ea1', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 37, 37, 'በመጋዝ የሰነጠቁአቸው፥ በድንጋይ የወገሩአቸው፥ በሰይፍም ስለት የገደሉዋቸው አሉ፤ ማቅ፥ ምንጣፍና የፍየል ሌጦ ለብሰው ዞሩ፤ ተጨነቁ፤ ተቸገሩ፤ መከራ ተቀበሉ፤ ተራቡ፥ ተጠሙም።'),
  ('4c4d9d1a-d882-5f79-a694-506f37688133', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 38, 38, 'ዓለም የማይገባቸው እነዚህ ናቸው፤ ዱር ለዱርና ተራራ ለተራራ፥ ዋሻ ለዋሻና ፍርኩታ ለፍርኩታም ዞሩ።'),
  ('345153d3-2e21-5668-a0c2-86c5d56ede30', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 39, 39, 'እነዚህም ሁሉ በእምነታቸው ተመስክሮላቸው ሳሉ፥ የተሰጣቸውን የተስፋ ቃል አላገኙም።'),
  ('9d508163-b60f-5ffa-a098-e8b400a6ced4', '0f99b667-58be-50ac-af69-b6b4695c76ac', 'c6bb05d6-ee7b-5d59-a023-faafadd9d99e', 40, 40, 'ያለ እኛ ፍጹማን እንዳይሆኑ፥ እግዚአብሔር ስለ እኛ የምትበልጠውን አስቀድሞ በይኖአልና።'),
  ('911cc0e8-24c2-5d15-ab70-c5f73ba95980', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 1, 1, 'እንግዲህ እነዚህን የሚያህሉ ምስክሮች እንደ ደመና በዙሪያችን ካሉልን እኛ ደግሞ ሸክምን ሁሉ፥ የኀጢአትንም ጭንቀት ከእኛ አስወግደን፥ በፊታችን ያለውን ሩጫ በትዕግሥት እንሩጥ።'),
  ('cf76f1e7-e7b1-548a-a5c2-34c7cc480de3', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 2, 2, 'የእምነታችንንም ራስና ፈጻሚውን ኢየሱስን እንከተለው፤ እርሱ ነውርን ንቆ፥ በፊቱም ስላለው ደስታ በመስቀል ታግሦ በእግዚአብሔር ዙፋን ቀኝ ተቀምጦአልና።'),
  ('820decbd-fa35-514e-a6a8-42f63960efcc', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 3, 3, 'በነፍሳችሁ ዝላችሁ እንዳትደክሙ፥ ከኀጢአተኞች በደረሰበት እንዲህ ባለ መቃወም የጸናውን እስኪ ዐስቡት።'),
  ('88416288-1bcb-51f5-a51a-7cc7163901ff', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 4, 4, 'ገና አልጸናችሁምና ደማችሁን ለማፍሰስ እስክትደርሱ ኀጢአትን ተጋደሉኣት፥ አሸንፉኣትም፤ ተስፋችሁን የምታገኙባትን ትምህርትም ውደዷት።'),
  ('62fa98f5-5748-51c5-a89a-6762a47d0f26', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 5, 5, 'እንደ ልጆችም ከእናንተ ጋር፥ “ልጄ ሆይ፥ የጌታን ቅጣት አታቅልል በሚገሥጽህም ጊዜ አትድከም።'),
  ('b5902eb7-ecbd-5cd6-a848-17bdd13ccbf3', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 6, 6, 'እግዚአብሔር የሚወደውን ይገሥጻልና፥ የሚወደደውንም ልጅ ሁሉ ይገርፈዋል” ብሎ የሚነጋገረውን ምክር ረስታችኋል።'),
  ('8060445d-33fe-5a3c-ab14-b43e4b202661', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 7, 7, 'ቅጣታችሁን ታገሡ፤ ልጆቹ እንደ መሆናችሁ ይወዳችኋልና፤ አባቱ የማይቈጣው ልጅ ማን ነው?'),
  ('79bea8f7-31d1-522b-a407-9e1b75e31b3e', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 8, 8, 'ነገር ግን ሁሉ የቅጣት ተካፋይ ሆኖአልና፥ ያለ ቅጣት ብትኖሩ ዲቃሎች እንጂ ልጆች አይደላችሁም።'),
  ('4ef42abe-13c7-501e-ace4-365f0003b3a8', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 9, 9, 'በሥጋ የወለዱን አባቶቻችን የሚቀጡን፥ እኛም የምንፈራቸው ከሆነ፥ እንግዲያ ይልቁን ለመንፈስ አባታችን ልንታዘዝና ልንገዛ በሕይወትም ልንኖር እንዴት ይገባን ይሆን?'),
  ('3a83c7d7-4f31-5168-a71a-7e2c34ff295a', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 10, 10, 'እነርሱ መልካም ሆኖ እንደ ታያቸው ለጥቂት ቀን ይቀጡናል፤ እርሱ ግን ከቅድስናው እንድንካፈል ለጥቅማችን ይቀጣናል።'),
  ('cfc88943-12dc-5eac-ac08-4767f6cba968', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 11, 11, 'ቅጣት ሁሉ በጊዜው ያሳዝናል እንጂ ደስ አያሰኝም፤ በኋላ ግን ለተቀጡ ሰላምን ያፈራል፤ ጽድቅንም ያሰጣቸዋል።'),
  ('0ad44b27-dae3-531e-a40a-88e9cd1b779a', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 12, 12, 'ስለዚህም የላሉትን እጆች፥ የሰለሉትንም ጕልበቶች አቅኑ።'),
  ('76394670-c9fd-5b3a-a1e1-5860b9dfbdf9', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 13, 13, 'አንካሳነታችሁ እንዲድንና እንዳትሰነካከሉ ለእግሮቻችሁ የቀና መንገድን አድርጉ።'),
  ('0956a92a-c61d-56ec-a5a2-caed1e7ac140', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 14, 14, 'ከሁሉ ጋር ወደ ሰላም ሩጡ፤ ቅድስናችሁንም አትተዉ፤ ያለ እርሱ ግን እግዚአብሔርን የሚያየው የለም።'),
  ('6db91723-7c03-5381-af74-f6e84ac81c9a', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 15, 15, 'አስተውሉ፤ የእግዚአብሔርንም ጸጋ የሚያቃልል አይኑር፤ ሕማምን የምታመጣ፥ ብዙዎችንም የምታስታቸውና የምታረክሳቸው መራራ ሥር የምትገኝበትም አይኑር።'),
  ('d095a8ea-a487-5a1d-a120-a3ea03e70bc1', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 16, 16, 'ለጥቂት መብል ብኵርናውን እንደ ሸጠ እንደ ዔሳው ሴሰኛና ርኩስ የሚሆን አይኑር።'),
  ('910b644a-bd20-5275-addf-6530c3e4bb98', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 17, 17, 'ከዚያ በኋላ እንኳ በረከትን ሊወርስ በወደደ ጊዜ እንደ ተጣለ ታውቃላችሁና፤ በእንባም ተግቶ ምንም ቢፈልጋት ለንስሓ ስፍራ አላገኘምና።'),
  ('0d289291-f390-529c-a0b3-503943a97cbe', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 18, 18, 'ሊዳሰስ ወደሚችል ወደሚቃጠልም እሳት ወደ ጭጋግም፥ ወደ ጨለማም ወደ ዐውሎ ነፋስም፥'),
  ('c683c9cb-de6a-5b88-a120-dbdd3c1d5eb2', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 19, 19, 'ወደ መለከት ድምፅም፥ ወደ ቃሎችም ነገር አልደረሳችሁምና፥ ያንም ነገር የሰሙት ሌላ ቃል እንዳይጨመርባቸው ለመኑ።'),
  ('1fa683e3-2b28-55dd-ad9b-84dbe2e14ee7', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 20, 20, 'የተነጋገራቸውን ሊሰሙት አልተቻላቸውም ነበርና፥ “እንስሳም ያን ተራራ ቢቀርበው በድንጋይ ይወግሩት” ነበር።'),
  ('9483670d-5187-5e44-a9ef-e1af05599ff8', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 21, 21, 'የታያቸውም እንዲህ ግሩም ነበር፤ ሙሴም እንኳን፥ “እኔ ፈርቻለሁ፥ ደንግጫለሁም” አለ።'),
  ('c33b5ba0-c1ba-5b9a-ad20-644c7627000c', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 22, 22, 'እናንተ ግን፥ የሕያው እግዚአብሔር ከተማ ወደምትሆን ወደ ጽዮን ተራራ፥ በሰማያት ወደ አለችው ኢየሩሳሌም፥ ደስ ብሎአቸው ወደሚኖሩ አእላፍ መላእክትም ደርሳችኋል።'),
  ('1e93b120-fbc7-5d8a-a7a1-352fbf38bb7c', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 23, 23, 'ስማቸው በሰማይ ወደ ተጻፈ ወደ ማኅበረ በኵርም፥ ሁሉን ወደሚገዛም ወደ እግዚአብሔር፥ ወደ ፍጹማን ጻድቃንም ነፍሳት፥'),
  ('13bd252c-a376-5c8f-afb9-f5681ef33c48', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 24, 24, 'የአዲስ ኪዳንም መካከለኛ ወደሚሆን ወደ ኢየሱስ፥ ከአቤልም ደም ይልቅ የሚሻለውን ወደሚናገር ወደ ተረጨው ደሙ ደርሳችኋል።'),
  ('d3b1c6f1-dd49-56ac-a761-93c2a3c304b7', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 25, 25, 'ለሚናገረው እንቢ እንዳትሉ ተጠንቀቁ፤ እነርሱ በደብረ ሲና የተገለጠላቸውን እንቢ ስለ አሉት ካልዳኑ፥ ከሰማይ ከመጣው ፊታችንን ብንመልስ እኛማ እንዴታ?'),
  ('bc2ffbad-773e-543b-afd2-08a1c085eb89', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 26, 26, 'ያንጊዜ ቃል ምድርን አናወጣት፤ “አሁንም እኔ ምድርን እንደ ገና አንድ ጊዜ አናውጣታለሁ” ብሎ ተናገረ፤ ምድርን ብቻም አይደለም፤ ሰማይንም ጭምር እንጂ።'),
  ('346926f8-b35d-5c72-ad9c-bfce5fb202b7', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 27, 27, 'አንድ ጊዜ ደግሞ ያለውም ፍጡራን ናቸውና፥ የማይናወጠው ይኖር ዘንድ፥ የሚናወጠውን እንደሚያሳልፈው ያሳያል።'),
  ('7c2c99ea-0d4b-5a20-a121-5f6ea5a75d81', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 28, 28, 'ስለዚህ የማይናወጥ መንግሥትን ስለምንቀበል በማክበርና በፍርሀት እግዚአብሔርን ደስ እያሰኘን የምናመልክበትን ጸጋ እንያዝ።'),
  ('2ce7e75e-d8c6-52ab-a283-8631adafb41d', '5a2b1b0f-be76-57f2-acfa-95c93fa8e4d6', 'c5319e04-bb94-5c66-aa4e-c7642782ad96', 29, 29, 'አምላካችን በእውነት የሚያቃጥል እሳት ነውና።'),
  ('7828417d-8488-52a5-a7f3-645ba179d95a', '34fbce9d-518c-52f7-a107-84ebda20f71a', '63c57e31-5257-5ff8-ac30-228e8cf69854', 1, 1, 'ከወንድሞቻችሁ ጋር በፍቅር ኑሩ።'),
  ('04b1cc08-8493-5af5-a901-136c42921fab', '34fbce9d-518c-52f7-a107-84ebda20f71a', '63c57e31-5257-5ff8-ac30-228e8cf69854', 2, 2, 'እንግዳ መቀበልንም አትርሱ፤ በዚህ ምክንያት ሳያውቁ መላእክትን በእንግድነት ለመቀበል ያታደሉ አሉና።'),
  ('c057f71d-3b89-580b-aa18-1aaa01849382', '34fbce9d-518c-52f7-a107-84ebda20f71a', '63c57e31-5257-5ff8-ac30-228e8cf69854', 3, 3, 'ከእነርሱ ጋር አብራችኋቸው እንደ ታሰራችሁ ሆናችሁ እስረኞችን ዐስቡ፤ መከራ የጸናባቸውንም በሥጋችሁ ከእነሱ ጋር እንዳላችሁ ሆናችሁ ዐስቡ።'),
  ('ddf14858-f449-5a7a-abdc-4c648df0e771', '34fbce9d-518c-52f7-a107-84ebda20f71a', '63c57e31-5257-5ff8-ac30-228e8cf69854', 4, 4, 'መጋባት በሁሉ ዘንድ ክቡር ነው፥ ለመኝታቸውም ርኵሰት የለውም፤ ሴሰኞችንና አመንዝሮችን ግን እግዚአብሔር ይፈርድባቸዋል።'),
  ('7166a4ac-08c9-5159-afed-fd67e85021c2', '34fbce9d-518c-52f7-a107-84ebda20f71a', '63c57e31-5257-5ff8-ac30-228e8cf69854', 5, 5, 'ገንዘብ ሳትወዱ ኑሩ፤ ያላችሁም ይበቃችኋል፤ እርሱ “አልጥልህም፤ ቸልም አልልህም” ብሎአልና።'),
  ('b8d15e31-f4c4-54eb-a9b7-d71cfe978e0a', '34fbce9d-518c-52f7-a107-84ebda20f71a', '63c57e31-5257-5ff8-ac30-228e8cf69854', 6, 6, 'አሁንም አምነን፥ “እግዚአብሔር ይረዳኛል፥ አልፈራም፥ ሰው ምን ያደርገኛል?” እንበል።'),
  ('3265cc01-28d9-56f4-a2d2-21850ffbd1a8', '34fbce9d-518c-52f7-a107-84ebda20f71a', '63c57e31-5257-5ff8-ac30-228e8cf69854', 7, 7, 'የእግዚአብሔርን ቃል የነገሩአችሁን መምህሮቻችሁን ዐስቡ፤ መልካም ጠባያቸውን አይታችሁ በእምነት ምሰሉአቸው።'),
  ('66ed8164-e16c-521e-a357-3de7305dd5b4', '34fbce9d-518c-52f7-a107-84ebda20f71a', '63c57e31-5257-5ff8-ac30-228e8cf69854', 8, 8, 'ኢየሱስ ክርስቶስ ትናንትናና ዛሬ እስከ ዘለዓለም የሚኖር እርሱ ነውና።'),
  ('bf62fe45-6eb5-502c-a3db-4762fad2e189', '34fbce9d-518c-52f7-a107-84ebda20f71a', '63c57e31-5257-5ff8-ac30-228e8cf69854', 9, 9, 'ሌላ ልዩ ትምህርት አታምጡ፤ ልባችሁ በመብል ያይደለ በጸጋ ቢጸና ይበልጣልና፤ በዚያ ይሄዱ የነበሩ እነዚያ አልተጠቀሙምና።'),
  ('50048acb-01b0-5c9a-a660-8efb19a37b9d', '34fbce9d-518c-52f7-a107-84ebda20f71a', '63c57e31-5257-5ff8-ac30-228e8cf69854', 10, 10, 'ድንኳኒቱን ሲያገለግሉ የነበሩ ካህናት ከእርሱ ሊበሉ የማይቻላቸው መሠዊያ አለን፤'),
  ('a46f860b-1207-50a6-ab5f-9d8a094eb0bb', '34fbce9d-518c-52f7-a107-84ebda20f71a', '63c57e31-5257-5ff8-ac30-228e8cf69854', 11, 11, 'ሊቀ ካህናቱ የሚሠዉትን እንስሳ ደም ስለ ኀጢአት ወደ ቅድስተ ቅዱሳን ያቀርብ ነበርና፤ ሥጋውንም ከሰፈር ውጭ ያቃጥሉት ነበር።'),
  ('7ac7595a-faa6-5c4e-a687-6116496b4773', '34fbce9d-518c-52f7-a107-84ebda20f71a', '63c57e31-5257-5ff8-ac30-228e8cf69854', 12, 12, 'ስለዚህም ኢየሱስ ሕዝቡን በደሙ ይቀድሳቸው ዘንድ ከከተማ ውጭ ተሰቀለ።'),
  ('7a27b9ab-d0ec-5ba0-a538-4dfb2b93ecfe', '34fbce9d-518c-52f7-a107-84ebda20f71a', '63c57e31-5257-5ff8-ac30-228e8cf69854', 13, 13, 'አሁንም ተግዳሮቱን ተሸክመን፥ ወደ እርሱ ወደ ከተማው ውጭ እንውጣ።'),
  ('6c496e5b-ed73-5542-af2d-64cb75c328fb', '34fbce9d-518c-52f7-a107-84ebda20f71a', '63c57e31-5257-5ff8-ac30-228e8cf69854', 14, 14, 'በዚህ የሚኖር ከተማ ያለን አይደለም፤ የምትመጣውን እንሻለን እንጂ።'),
  ('374eccd5-28af-5e6b-ab19-11f847f265a6', '34fbce9d-518c-52f7-a107-84ebda20f71a', '63c57e31-5257-5ff8-ac30-228e8cf69854', 15, 15, 'በውኑ እንግዲህ በስሙ እናምን ዘንድ የከንፈሮቻችን ፍሬ የሚሆን የምስጋና መሥዋዕትን በየጊዜው ለእግዚአብሔር ልናቀርብ አይገባንምን?'),
  ('c14b9e1b-2ca6-5f4f-ac19-ffdab84f2e48', '34fbce9d-518c-52f7-a107-84ebda20f71a', '63c57e31-5257-5ff8-ac30-228e8cf69854', 16, 16, 'ነገር ግን ለድሆች መራራትን፥ ከእነርሱም ጋር መተባበርን አትርሱ፤ እንዲህ ያለው መሥዋዕት እግዚአብሔርን ደስ ያሰኘዋልና።'),
  ('c942398e-3a88-549d-a1c1-3fd7abc3a206', '34fbce9d-518c-52f7-a107-84ebda20f71a', 'b2f395bf-5fdd-56d9-a375-bc9701fbaa9a', 1, 17, 'ለመምህሮቻችሁ ታዘዙ፤ ተገዙላቸውም፤ ስለ እናንተ በእግዚአብሔር ፊት ምላሽ የሚሰጡ እንደ መሆናቸው፥ ይህን ሳያዝኑ ደስ ብሎአቸው ያደርጉት ዘንድ ስለ ነፍሳችሁ ይተጋሉና።'),
  ('fff19fb0-d304-5897-aae8-26432be6009f', '34fbce9d-518c-52f7-a107-84ebda20f71a', 'b2f395bf-5fdd-56d9-a375-bc9701fbaa9a', 2, 18, 'ይህም ስለ እኛ ትጸልዩ ዘንድ ይገባችኋል፤ ለሁሉ መልካም ነገርን እንደምትወዱና እንደምትሹ እናምናለን።'),
  ('6f2876b7-9dba-5837-a0bc-dc571df8e6d2', '34fbce9d-518c-52f7-a107-84ebda20f71a', 'b2f395bf-5fdd-56d9-a375-bc9701fbaa9a', 3, 19, 'ይልቁንም ፈጥኜ እንድመለስላችሁ ይህን ታደርጉ ዘንድ አጥብቄ እለምናችኋለሁ።'),
  ('723cb1f7-2397-5e0d-a23d-c1c6e45f1823', '34fbce9d-518c-52f7-a107-84ebda20f71a', '6a503b26-159e-53b0-a34f-d342a02d1299', 1, 20, 'በዘለዓለም ኪዳን ደም ለበጎች ትልቅ እረኛ የሆነውን ጌታችን ኢየሱስን ከሙታን ያስነሣው፥')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('3f108c11-6a05-5354-a0e1-12219764681c', '34fbce9d-518c-52f7-a107-84ebda20f71a', '6a503b26-159e-53b0-a34f-d342a02d1299', 2, 21, 'የሰላም አምላክ በኢየሱስ ክርስቶስ በኩል በፊቱ ደስ የሚያሰኘውን በእናንተ እያደረገ ፈቃዱን ታደርጉ ዘንድ በመልካም ሥራ ሁሉ ፍጹማን ያድርጋችሁ፤ ለእርሱ እስከ ዘለዓለም ድረስ ክብር ይሁን፤ አሜን።'),
  ('812e7064-e312-5c97-a83e-c4c50bb77ed0', '34fbce9d-518c-52f7-a107-84ebda20f71a', '6a503b26-159e-53b0-a34f-d342a02d1299', 3, 22, 'ወንድሞች ሆይ፥ የምክርን ቃል እንድትቀበሉ እመክራችኋለሁ፤ በጥቂት ቃል ጽፌላችኋለሁና።'),
  ('7306651e-2d0b-5ff7-ae52-4f84e75cb547', '34fbce9d-518c-52f7-a107-84ebda20f71a', '6a503b26-159e-53b0-a34f-d342a02d1299', 4, 23, 'ወንድማችን ጢሞቴዎስ ከእኛ ወደ እናንተ እንደ ተላከ ዕወቁ፤ ፈጥኖ ከመጣ አያችኋለሁ።'),
  ('56194c76-259b-5a42-ad50-ae24583afebb', '34fbce9d-518c-52f7-a107-84ebda20f71a', '6a503b26-159e-53b0-a34f-d342a02d1299', 5, 24, 'መምህሮቻችሁን ሁሉና ቅዱሳንንም ሁሉ ሰላም በሉ፥ በኢጣልያ ያሉ ሁሉ ሰላም ብለዋችኋል።'),
  ('1b503de3-df84-5da6-a505-d7b98b09d44d', '34fbce9d-518c-52f7-a107-84ebda20f71a', '6a503b26-159e-53b0-a34f-d342a02d1299', 6, 25, 'የጌታችን ጸጋዉ ከሁላችሁ ጋር ይሁን፤ አሜን።'),
  ('8d894905-f72e-5f06-af85-db6d6bca943f', 'ba4c1f81-44a8-58fb-ad0e-6aa4f4dad0c6', 'd5c2be51-6e4f-50f7-a5bb-be26e8748433', 1, 1, 'የኢየሱስ ክርስቶስ ሐዋርያ ጴጥሮስ፥ እግዚአብሔር አብ አስቀድሞ እንዳወቃቸው በመንፈስም እንደሚቀደሱ፥ ይታዘዙና በኢየሱስ ክርስቶስ ደም ይረጩ ዘንድ ለተመረጡት በጳንጦስና በገላትያ በቀጰዶቅያም በእስያም በቢታንያም ለተበተኑ መጻተኞች፤ ጸጋና ሰላም ይብዛላችሁ።'),
  ('f4e94f25-9334-5257-a41a-9b508450aa9c', 'ba4c1f81-44a8-58fb-ad0e-6aa4f4dad0c6', '0a52f218-abc2-586b-a253-d8d2c4053f4f', 1, 3, 'ኢየሱስ ክርስቶስ ከሙታን በመነሣቱ ለሕያው ተስፋና ለማይጠፋ፥ እድፈትም ለሌለበት፥ ለማያልፍም ርስት እንደ ምሕረቱ ብዛት ሁለተኛ የወለደን የጌታችን የኢየሱስ ክርስቶስ አባት እግዚአብሔር ይመስገን፤ ይህም ርስት በመጨረሻው ዘመን ይገለጥ ዘንድ ለተዘጋጀ መዳን በእምነት በእግዚአብሔር ኀይል ለተጠበቃችሁ ለእናንተ በሰማይ ቀርቶላችኋል።'),
  ('ff481bab-f61d-5582-a0e5-a94ad11de1a3', 'ba4c1f81-44a8-58fb-ad0e-6aa4f4dad0c6', '0a52f218-abc2-586b-a253-d8d2c4053f4f', 2, 6, 'በዚህም እጅግ ደስ ይላችኋል፤ ነገር ግን በእሳት ምንም ቢፈተን ከሚጠፋው ወርቅ ይልቅ አብልጦ የሚከብር የተፈተነ እምነታችሁ፥ ኢየሱስ ክርስቶስ ሲገለጥ፥ ለምስጋናና ለክብር ለውዳሴም ይገኝ ዘንድ አሁን ለጥቂት ጊዜ ቢያስፈልግ በልዩ ልዩ ፈተና አዝናችኋል።'),
  ('67318261-9283-5196-a0c4-cb356647bf0b', 'ba4c1f81-44a8-58fb-ad0e-6aa4f4dad0c6', '0a52f218-abc2-586b-a253-d8d2c4053f4f', 3, 8, 'እርሱንም ሳታዩት ትወዱታላችሁ፤ አሁንም ምንም ባታዩት በእርሱ አምናችሁ፥ የእምነታችሁን ፍፃሜ እርሱም የነፍሳችሁን መዳን እየተቀበላችሁ፥ በማይነገርና ክብር በሞላበት ሐሤት ደስ ይላችኋል።'),
  ('b9a355c4-67f4-558e-a856-da5aae9955b7', 'ba4c1f81-44a8-58fb-ad0e-6aa4f4dad0c6', '0a52f218-abc2-586b-a253-d8d2c4053f4f', 4, 10, 'ለእናንተም ስለሚሰጠው ጸጋ ትንቢት የተናገሩት ነቢያት ስለዚህ መዳን ተግተው እየፈለጉ መረመሩት፤'),
  ('c13789e1-3cd5-5ce7-abd0-28adae4787ab', 'ba4c1f81-44a8-58fb-ad0e-6aa4f4dad0c6', '0a52f218-abc2-586b-a253-d8d2c4053f4f', 5, 11, 'በእነርሱም የነበረ የክርስቶስ መንፈስ፥ ስለ ክርስቶስ መከራ ከእርሱም በኋላ ስለሚመጣው ክብር አስቀድሞ እየመሰከረ፥ በምን ወይም እንዴት ባለ ዘመን እንዳመለከተ ይመረምሩ ነበር።'),
  ('fb0dc3d9-b732-537c-ad57-c867d0d702a8', 'ba4c1f81-44a8-58fb-ad0e-6aa4f4dad0c6', '0a52f218-abc2-586b-a253-d8d2c4053f4f', 6, 12, 'ለእነርሱም ከሰማይ በተላከ በመንፈስ ቅዱስ ወንጌልን የሰበኩላችሁ ሰዎች አሁን ባወሩላችሁ ነገር እናንተን እንጂ ራሳቸውን እንዳላገለገሉ ተገለጠላቸው፤ ይህንም ነገር መላእክቱ ሊመለከቱ ይመኛሉ።'),
  ('8b9c51b6-d9c0-5493-a88e-45030cc31b6d', 'ba4c1f81-44a8-58fb-ad0e-6aa4f4dad0c6', 'ab7bcd1b-5041-5b40-a543-d1a1a924215b', 1, 13, 'ስለዚህ የልቡናችሁን ወገብ ታጥቃችሁና በመጠን ኖራችሁ፥ ኢየሱስ ክርስቶስ ሲገለጥ የምታገኙትን ጸጋ ፈጽማችሁ ተስፋ አድርጉ።'),
  ('5f283b56-ecf2-5601-ae6c-acdde0c3f47e', 'ba4c1f81-44a8-58fb-ad0e-6aa4f4dad0c6', 'ab7bcd1b-5041-5b40-a543-d1a1a924215b', 2, 14, 'እንደሚታዘዙ ልጆች ባለማወቃችሁ አስቀድሞ የኖራችሁበትን ምኞት አትከተሉ።'),
  ('421a1412-a581-5b47-ae92-8129f4f8de0c', 'ba4c1f81-44a8-58fb-ad0e-6aa4f4dad0c6', 'ab7bcd1b-5041-5b40-a543-d1a1a924215b', 3, 15, 'ዳሩ ግን “እኔ ቅዱስ ነኝና ቅዱሳን ሁኑ፤” ተብሎ ስለ ተጻፈ የጠራችሁ ቅዱስ እንደ ሆነ እናንተ ደግሞ በኑሮአችሁ ሁሉ ቅዱሳን ሁኑ።'),
  ('b0a7e2c6-1080-5ad9-a434-2e57c8edbc10', 'ba4c1f81-44a8-58fb-ad0e-6aa4f4dad0c6', 'ab7bcd1b-5041-5b40-a543-d1a1a924215b', 4, 17, 'ለሰው ፊትም ሳያደላ በእያንዳንዱ ላይ እንደ ሥራው የሚፈርደውን አባት ብላችሁ ብትጠሩ በእንግድነታችሁ ዘመን በፍርሃት ኑሩ።'),
  ('232c5b54-d964-5797-a309-031b65045614', 'ba4c1f81-44a8-58fb-ad0e-6aa4f4dad0c6', 'ab7bcd1b-5041-5b40-a543-d1a1a924215b', 5, 18, 'ከአባቶቻችሁ ከወረሳችሁት ከከንቱ ኑሮአችሁ በሚያልፍ ነገር በብር ወይም በወርቅ ሳይሆን፥ ነውርና እድፍ እንደ ሌለው እንደ በግ ደም በክቡር የክርስቶስ ደም እንደ ተዋጃችሁ ታውቃላችሁ።'),
  ('1c69f803-ec86-50b6-a002-07efb78210d8', 'ba4c1f81-44a8-58fb-ad0e-6aa4f4dad0c6', 'ab7bcd1b-5041-5b40-a543-d1a1a924215b', 6, 20, 'ዓለም ሳይፈጠር እንኳ አስቀድሞ ታወቀ፤ ነገር ግን እምነታችሁና ተስፋችሁ በእግዚአብሔር ይሆን ዘንድ፥ ከሙታን ባስነሣው ክብርንም በሰጠው በእግዚአብሔር በእርሱ ስለምታምኑ ስለ እናንተ በዘመኑ መጨረሻ ተገለጠ።'),
  ('c8f698ec-f445-5269-aaac-ca8b66c52a12', 'ba4c1f81-44a8-58fb-ad0e-6aa4f4dad0c6', 'ab7bcd1b-5041-5b40-a543-d1a1a924215b', 7, 22, 'ለእውነት እየታዘዛችሁ ግብዝነት ለሌለበት ለወንድማማች መዋደድ ነፍሳችሁን አንጽታችሁ እርስ በርሳችሁ ከልባችሁ አጥብቃችሁ ተዋደዱ።'),
  ('6fd5b366-bb3c-5bd9-a06c-c5c82091f680', 'ba4c1f81-44a8-58fb-ad0e-6aa4f4dad0c6', 'ab7bcd1b-5041-5b40-a543-d1a1a924215b', 8, 23, 'ዳግመኛ የተወለዳችሁት ከሚጠፋ ዘር አይደለም፤ በሕያውና ለዘላለም በሚኖር በእግዚአብሔር ቃል ከማይጠፋ ዘር ነው እንጂ።'),
  ('ca6a1065-e746-5af7-af60-7e9ddafee7b1', 'ba4c1f81-44a8-58fb-ad0e-6aa4f4dad0c6', 'ab7bcd1b-5041-5b40-a543-d1a1a924215b', 9, 24, '“ሥጋ ሁሉ እንደ ሣር፥ ክብሩም ሁሉ እንደ ሣር አበባ ነውና፤'),
  ('aed8a47d-116b-5348-ac2b-85b57700fa33', 'ba4c1f81-44a8-58fb-ad0e-6aa4f4dad0c6', 'ab7bcd1b-5041-5b40-a543-d1a1a924215b', 10, 25, 'የጌታ ቃል ግን ለዘላለም ይኖራል።”'),
  ('dbe0c9df-7a87-58ee-a813-ea7ec62d3f85', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', 'd8281cda-db8e-5011-aea2-0a4570bb5548', 1, 1, 'እንግዲህ ክፋትን ሁሉ ተንኰልንም ሁሉ ግብዝነትንም ቅንዓትንም ሐሜትንም ሁሉ አስወግዳችሁ፥'),
  ('9fa663ee-09b6-510d-a73d-175a29745ce1', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', 'd8281cda-db8e-5011-aea2-0a4570bb5548', 2, 2, 'ጌታ ቸር መሆኑን ቀምሳችሁ እንደ ሆነ፥ ለመዳን በእርሱ እንድታድጉ አሁን እንደ ተወለዱ ሕፃናት ተንኰል የሌለበትን የቃልን ወተት ተመኙ።'),
  ('bf3c6343-8384-5705-a806-86c4247b3813', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', 'd8281cda-db8e-5011-aea2-0a4570bb5548', 3, 4, 'በሰውም ወደ ተጣለ በእግዚአብሔር ዘንድ ግን ወደ ተመረጠና ክቡር ወደ ሆነው ወደ ሕያው ድንጋይ ወደ እርሱ እየቀረባችሁ፥'),
  ('bb4eb343-615a-5900-ab67-c1184de2f324', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', 'd8281cda-db8e-5011-aea2-0a4570bb5548', 4, 5, 'እናንተ ደግሞ እንደ ሕያዋን ድንጋዮች ሆናችሁ፥ በኢየሱስ ክርስቶስ ለእግዚአብሔር ደስ የሚያሰኝ መንፈሳዊ መሥዋዕትን ታቀርቡ ዘንድ ቅዱሳን ካህናት እንድትሆኑ መንፈሳዊ ቤት ለመሆን ተሠሩ።'),
  ('e59e5780-3b81-5966-a57d-36f699d827ea', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', 'd8281cda-db8e-5011-aea2-0a4570bb5548', 5, 6, 'በመጽሐፍ'),
  ('cbddace0-5b0a-5e21-a3f7-f3caf2764fb3', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', 'd8281cda-db8e-5011-aea2-0a4570bb5548', 6, 9, 'እናንተ ግን ከጨለማ ወደሚደነቅ ብርሃኑ የጠራችሁን የእርሱን በጎነት እንድትናገሩ የተመረጠ ትውልድ፥ የንጉሥ ካህናት፥ ቅዱስ ሕዝብ፥ ለርስቱ የተለየ ወገን ናችሁ፤'),
  ('fb668439-4504-5ed1-ad92-cf5cf1dd12ef', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', 'd8281cda-db8e-5011-aea2-0a4570bb5548', 7, 10, 'እናንተ ቀድሞ ወገን አልነበራችሁም፤ አሁን ግን የእግዚአብሔር ወገን ናችሁ፤ እናንተ ምሕረት ያገኛችሁ አልነበራችሁም፤ አሁን ግን ምሕረትን አግኝታችኋል።'),
  ('fe9f3a14-c7b0-5d34-acdd-84d581235561', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', '0d445229-3f2b-523c-a095-9b4dd9665c52', 1, 11, 'ወዳጆች ሆይ! ነፍስን ከሚዋጋ ሥጋዊ ምኞት ትርቁ ዘንድ እንግዶችና መጻተኞች እንደ መሆናችሁ እለምናችኋለሁ፤'),
  ('86901b76-049f-5585-a5df-1a8f379f28f0', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', '0d445229-3f2b-523c-a095-9b4dd9665c52', 2, 12, 'ስለሚመለከቱት ስለ መልካም ሥራችሁ፥ ክፉ እንደምታደርጉ በዚያ እናንተን በሚያሙበት ነገር፥ በሚጎበኝበት ቀን እግዚአብሔርን ያከብሩት ዘንድ በአሕዛብ መካከል ኑሮአችሁ መልካም ይሁን።'),
  ('6d000b3f-c537-5683-a97e-8335dfd2cdd8', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', '0d445229-3f2b-523c-a095-9b4dd9665c52', 3, 13, 'ስለ ጌታ ብላችሁ ለሰው ሥርዐት ሁሉ ተገዙ፤ ለንጉሥም ቢሆን፥ ከሁሉ በላይ ነውና፤'),
  ('82379fc2-7f4c-53e2-a408-43dc06d6f29e', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', '0d445229-3f2b-523c-a095-9b4dd9665c52', 4, 14, 'ለመኳንንትም ቢሆን፥ ክፉ የሚያደርጉትን ለመቅጣት በጎም የሚያደርጉትን ለማመስገን ከእርሱ ተልከዋልና ተገዙ።'),
  ('af0dc12f-e271-5256-a79c-672394928b78', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', '0d445229-3f2b-523c-a095-9b4dd9665c52', 5, 15, 'በጎ እያደረጋችሁ፥ የማያውቁትን ሞኞች ዝም ታሰኙ ዘንድ እንዲህ የእግዚአብሔር ፈቃድ ነውና፤'),
  ('315d49e1-0e10-5702-a7ef-9d8c30302762', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', '0d445229-3f2b-523c-a095-9b4dd9665c52', 6, 16, 'አርነት ወጥታችሁ እንደ እግዚአብሔር ባሪያዎች ሁኑ እንጂ ያ አርነት ለክፋት መሸፈኛ እንዲሆን አታድርጉ።'),
  ('a2166bb7-4de8-54d3-a19d-4ef4afd40f65', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', '0d445229-3f2b-523c-a095-9b4dd9665c52', 7, 17, 'ሁሉን አክብሩ፤ ወንድሞችን ውደዱ፤ እግዚአብሔርን ፍሩ፤ ንጉሥን አክብሩ።'),
  ('1bf5cd9b-8e9f-5590-a281-f4be944b6ed2', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', 'bda5f849-2ee9-5adf-a85b-0732c093d542', 1, 18, 'ሎሌዎች ሆይ! ለበጎዎችና ለገሮች ጌቶቻችሁ ብቻ ሳይሆን ለጠማሞች ደግሞ በፍርሃት ሁሉ ተገዙ።'),
  ('1b232690-0efd-57e0-ab69-9d04ce9b6c8f', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', 'bda5f849-2ee9-5adf-a85b-0732c093d542', 2, 19, 'በግፍ መከራን የሚቀበል ሰው እግዚአብሔርን እያሰበ ሐዘንን ቢታገሥ ምስጋና ይገባዋልና።'),
  ('77d68cf5-312d-5ffd-a6b1-568fa816d888', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', 'bda5f849-2ee9-5adf-a85b-0732c093d542', 3, 20, 'ኀጢአት አድርጋችሁ ስትጎሰሙ ብትታገሡ፥ ምን ክብር አለበት? ነገር ግን መልካም አድርጋችሁ መከራን ስትቀበሉ ብትታገሡ፥ ይህ ነገር በእግዚአብሔር ዘንድ ምስጋና ይገባዋል።'),
  ('8e437a12-ae8f-5e73-aa5c-f2fb69d824c1', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', 'bda5f849-2ee9-5adf-a85b-0732c093d542', 4, 21, 'የተጠራችሁለት ለዚህ ነውና፤ ክርስቶስ ደግሞ ፍለጋውን እንድትከተሉ ምሳሌ ትቶላችሁ ስለ እናንተ መከራን ተቀብሎአልና።'),
  ('29eec590-9bef-52ac-afa5-05ee640adfb1', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', 'bda5f849-2ee9-5adf-a85b-0732c093d542', 5, 22, '“እርሱም ኀጢአት አላደረገም፤'),
  ('7a9c2d55-54ef-5ca1-acfc-26613a3e288f', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', 'bda5f849-2ee9-5adf-a85b-0732c093d542', 6, 23, 'ሲሰድቡት መልሶ አልተሳደበም፤ መከራንም ሲቀበል አልዛተም፤ ነገር ግን በጽድቅ ለሚፈርደው ራሱን አሳልፎ ሰጠ፤'),
  ('b107025e-5e52-5c1a-a1f3-31299d1e64ce', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', 'bda5f849-2ee9-5adf-a85b-0732c093d542', 7, 24, 'ለኀጢአት ሞተን ለጽድቅ እንድንኖር፥ እርሱ ራሱ በሥጋው ኀጢአታችንን በእንጨት ላይ ተሸከመ፤ በመገረፉ ቁስል ተፈወሳችሁ።'),
  ('03be09cb-4363-5af1-af54-99e11dfc98d7', '8c8c007b-2f58-5ce6-a827-8703ae321ccd', 'bda5f849-2ee9-5adf-a85b-0732c093d542', 8, 25, 'እንደ በጎች ትቅበዘበዙ ነበርና፥ አሁን ግን ወደ ነፍሳችሁ እረኛና ጠባቂ ተመልሳችኋል።'),
  ('d0ec5bc6-f71a-50ce-a73a-0064a286436c', '58226e07-b571-5abe-a475-856ffb9c4c97', '7923e897-665c-59b0-a35e-832024444808', 1, 1, 'እንዲሁም እናንተ ሚስቶች ሆይ! ከባሎቻችሁ አንዳንዱ ለትምህርት የማይታዘዙ ቢኖሩ፥ በፍርሃት ያለውን ንጹሑን ኑሮአችሁን እየተመለከቱ ያለ ትምህርት በሚስቶቻቸው ኑሮ እንዲገኙ ተገዙላቸው።'),
  ('473fe735-c831-58a0-a42b-206da157d795', '58226e07-b571-5abe-a475-856ffb9c4c97', '7923e897-665c-59b0-a35e-832024444808', 2, 3, 'ለእናንተም ጠጕርን በመሸረብና ወርቅን በማንጠልጠል ወይም ልብስን በመጎናጸፍ በውጭ የሆነ ሽልማት አይሁንላችሁ፤'),
  ('240a8867-f2cd-5677-a3b1-72a14ac4dfd1', '58226e07-b571-5abe-a475-856ffb9c4c97', '7923e897-665c-59b0-a35e-832024444808', 3, 4, 'ነገር ግን በእግዚአብሔር ፊት ዋጋው እጅግ የከበረ የዋህና ዝግተኛ መንፈስ ያለውን የማይጠፋውን ልብስ ለብሶ የተሰወረ የልብ ሰው ይሁንላችሁ።'),
  ('67ac7754-dee8-505c-a203-e2ab08e47f7a', '58226e07-b571-5abe-a475-856ffb9c4c97', '7923e897-665c-59b0-a35e-832024444808', 4, 5, 'እንዲህ በቀድሞ ዘመን በእግዚአብሔር ተስፋ ያደረጉት ቅዱሳት ሴቶች ደግሞ ለባሎቻቸው ሲገዙ ተሸልመው ነበርና፤'),
  ('f7953db9-04ad-53e4-a285-a0a91544e901', '58226e07-b571-5abe-a475-856ffb9c4c97', '7923e897-665c-59b0-a35e-832024444808', 5, 6, 'እንዲሁም ሣራ ለአብርሃም፥ ጌታ ብላ እየጠራችው ታዘዘችለት፤ እናንተም ከሚያስደነግጥ ነገር አንዳች እንኳ ሳትፈሩ መልካም ብታደርጉ ልጆችዋ ናችሁ።'),
  ('19e41f4b-438c-51e9-af5d-3de200714b4f', '58226e07-b571-5abe-a475-856ffb9c4c97', '7923e897-665c-59b0-a35e-832024444808', 6, 7, 'እንዲሁም እናንተ ባሎች ሆይ! ደካማ ፍጥረት ስለ ሆኑ ከሚስቶቻችሁ ጋር በማስተዋል አብራችሁ ኑሩ፤ ጸሎታችሁ እንዳይከለከል አብረው ደግሞ የሕይወትን ጸጋ እንደሚወርሱ አድርጋችሁ አክብሩአቸው።'),
  ('655bfa94-160b-5152-a169-bb8a918d6a4b', '58226e07-b571-5abe-a475-856ffb9c4c97', '9fa95632-a275-55b6-a5ec-7b326ccd32ca', 1, 8, 'በመጨረሻው ሁላችሁ በአንድ ልብ ሁኑ፤ የሌላው መከራ ለእናንተ እንደሚሆን አድርጉ፤ እንደወንድሞች ተዋደዱ፤ ርኅሩኆችና ትሑታን ሁኑ፤'),
  ('de9b4072-d1ea-5a81-aeab-19338f063331', '58226e07-b571-5abe-a475-856ffb9c4c97', '9fa95632-a275-55b6-a5ec-7b326ccd32ca', 2, 9, 'ክፉን በክፉ ፈንታ ወይም ስድብን በስድብ ፈንታ አትመልሱ፤ በዚህ ፈንታ ባርኩ እንጂ፤ በረከትን ልትወርሱ ለዚህ ተጠርታችኋልና።'),
  ('b7d954bf-1647-5ee3-abc9-932d1f663a8f', '58226e07-b571-5abe-a475-856ffb9c4c97', '9fa95632-a275-55b6-a5ec-7b326ccd32ca', 3, 10, '“ሕይወትን ሊወድ መልካሞችንም ቀኖች ሊያይ የሚፈልግ ሰው፥'),
  ('268492b5-06ab-5398-a251-ca7efdfbb93d', '58226e07-b571-5abe-a475-856ffb9c4c97', '9fa95632-a275-55b6-a5ec-7b326ccd32ca', 4, 11, 'ከክፉ ፈቀቅ ይበል፤ መልካምንም ያድርግ፤'),
  ('d727f0e4-d663-5b5a-accf-9fbe9ca62574', '58226e07-b571-5abe-a475-856ffb9c4c97', '9fa95632-a275-55b6-a5ec-7b326ccd32ca', 5, 12, 'የጌታ ዐይኖች ወደ ጻድቃን ናቸውና፤'),
  ('265517eb-5a76-56df-a118-f38434ed94e7', '58226e07-b571-5abe-a475-856ffb9c4c97', '9fa95632-a275-55b6-a5ec-7b326ccd32ca', 6, 13, 'በጎንም ለማድረግ ብትቀኑ የሚያስጨንቃችሁ ማን ነው?'),
  ('32082af8-cc0c-586b-afca-fd0a257b1072', '58226e07-b571-5abe-a475-856ffb9c4c97', '9fa95632-a275-55b6-a5ec-7b326ccd32ca', 7, 14, 'ነገር ግን ስለ ጽድቅ እንኳ መከራን ብትቀበሉ ብፁዓን ናችሁ። ማስፈራራታቸውንም አትፍሩ፤ አትናወጡም፤'),
  ('dfb9dba5-7753-5c61-ac88-842b4b8107ba', '58226e07-b571-5abe-a475-856ffb9c4c97', '9fa95632-a275-55b6-a5ec-7b326ccd32ca', 8, 15, 'ዳሩ ግን ጌታን እርሱም ክርስቶስ በልባችሁ ቀድሱት። በእናንተ ስላለ ተስፋ ምክንያትን ለሚጠይቁዋችሁ ሁሉ መልስ ለመስጠት ዘወትር የተዘጋጃችሁ ሁኑ፤ ነገር ግን በየዋህነትና በፍርሃት ይሁን።'),
  ('fdc40b7a-4814-53e0-a3c9-81793044b539', '58226e07-b571-5abe-a475-856ffb9c4c97', '9fa95632-a275-55b6-a5ec-7b326ccd32ca', 9, 16, 'በክርስቶስ ያለውን መልካሙን ኑሮአችሁን የሚሳደቡ ሰዎች ክፉን እንደምታደርጉ በሚያሙበት ነገር እንዲያፍሩ በጎ ሕሊና ይኑራችሁ።'),
  ('db0c5741-b930-536a-a2f8-e786b918173c', '58226e07-b571-5abe-a475-856ffb9c4c97', '9fa95632-a275-55b6-a5ec-7b326ccd32ca', 10, 17, 'የእግዚአብሔር ፈቃድ እንዲህ ቢሆን፥ ክፉ ስለ ማድረግ ሳይሆን በጎ ስለ ማድረግ መከራን ብትቀበሉ ይሻላችኋልና።'),
  ('178bf540-5554-5f34-a965-b6d41d0db680', '58226e07-b571-5abe-a475-856ffb9c4c97', '9fa95632-a275-55b6-a5ec-7b326ccd32ca', 11, 18, 'ክርስቶስ ደግሞ ወደ እግዚአብሔር እንዲያቀርበን እርሱ ጻድቅ ሆኖ ስለ ዐመፀኞች አንድ ጊዜ በኀጢአት ምክንያት ሞቶአልና፤ በሥጋ ሞተ፤ በመንፈስ ግን ሕያው ሆነ፤'),
  ('3668a88d-4895-5aaf-a502-286c34ac6255', '58226e07-b571-5abe-a475-856ffb9c4c97', '9fa95632-a275-55b6-a5ec-7b326ccd32ca', 12, 19, 'በእርሱም ደግሞ ሄዶ በወኅኒ ለነበሩ ነፍሳት ሰበከላቸው፤'),
  ('b93dea90-6fca-5e69-a00d-1ca3efe63490', '58226e07-b571-5abe-a475-856ffb9c4c97', '9fa95632-a275-55b6-a5ec-7b326ccd32ca', 13, 20, 'ጥቂቶች ማለት ስምንት ነፍስ በውሃ የዳኑበት መርከብ ሲዘጋጅ፥ የእግዚአብሔር ትዕግሥት በኖኅ ዘመን በቈየ ጊዜ ቀድሞ አልታዘዙም።'),
  ('892dba25-5ebe-5fa9-ac0f-6d78ca4a92f0', '58226e07-b571-5abe-a475-856ffb9c4c97', '9fa95632-a275-55b6-a5ec-7b326ccd32ca', 14, 21, 'ይህም ውሃ ደግሞ ማለት ጥምቅት ምሳሌው ሆኖ አሁን ያድነናል፤ የሰውነትን እድፍ ማስወገድ አይደለም፤ ለእግዚአብሔር የበጎ ሕሊና ልመና ነው እንጂ፤ ይህም በኢየሱስ ክርስቶስ ትንሣኤ ነው፤'),
  ('d0d1df30-472d-5238-a646-f3759d3ef34e', '58226e07-b571-5abe-a475-856ffb9c4c97', '9fa95632-a275-55b6-a5ec-7b326ccd32ca', 15, 22, 'እርሱም መላእክትና ሥልጣናት ኀይላትም ከተገዙለት በኋላ ወደ ሰማይ ሄዶ በእግዚአብሔር ቀኝ አለ።'),
  ('36cbffdd-3ca1-5596-ac62-82ddea3f12bd', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '2eceacee-7318-50fe-a076-02c1205b2a64', 1, 1, 'ክርስቶስም በሥጋ ስለ እኛ መከራን ስለተቀበለ፥ ከእንግዲህ ወዲህ በሥጋ ልትኖሩ በቀረላችሁ ዘመን እንደ እግዚአብሔር ፈቃድ እንጂ እንደ ሰው ምኞት እንዳትኖሩ፥ እናንተ ደግሞ ያን አሳብ እንደ ዕቃ ጦር አድርጋችሁ ያዙት፤ በሥጋ መከራን የተቀበለ ኀጢአትን ትቶአልና።'),
  ('8698f0f0-97ff-549f-aa29-d2109aade906', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '2eceacee-7318-50fe-a076-02c1205b2a64', 2, 3, 'የአሕዛብን ፈቃድ ያደረጋችሁበት በመዳራትና በሥጋ ምኞትም በስካርም በዘፈንም ያለ ልክም በመጠጣት ነውርም ባለበት በጣዖት ማምለክ የተመላለሳችሁበት ያለፈው ዘመን ይበቃልና።'),
  ('7f91553e-cb67-5bc0-aacb-87757ff107e4', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '2eceacee-7318-50fe-a076-02c1205b2a64', 3, 4, 'በዚህም ነገር ወደዚያ መዳራት ብዛት ከእነርሱ ጋር ስለማትሮጡ እየተሳደቡ ይደነቃሉ፤'),
  ('80624b5f-e0c3-5b89-a000-73713789ad66', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '2eceacee-7318-50fe-a076-02c1205b2a64', 4, 5, 'ግን እነርሱ በሕያዋንና በሙታን ላይ ሊፈርድ ለተዘጋጀው መልስ ይሰጣሉ።'),
  ('1b1466ed-629a-5aae-ae04-46417d55155e', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '2eceacee-7318-50fe-a076-02c1205b2a64', 5, 6, 'እንደሰዎች በሥጋ እንዲፈረድባችው በመንፈስ ግን እንደ እግዚአብሔር እንዲኖሩ ስለዚህ ምክንያት ወንጌል ለሙታን ደግሞ ተሰብኮላቸው ነበርና።'),
  ('64c338f8-5f82-5753-a8ea-c4612745c854', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '2eceacee-7318-50fe-a076-02c1205b2a64', 6, 7, 'ዳሩ ግን የነገር ሁሉ መጨረሻ ቀርቦአል። እንግዲህ እንደ ባለ አእምሮ አስቡ፤'),
  ('91c25fac-42a3-51f8-afb0-e91da7ced536', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '2eceacee-7318-50fe-a076-02c1205b2a64', 7, 8, 'ትጸልዩም ዘንድ በመጠን ኑሩ፤ ፍቅር የኀጢአትን ብዛት ይሸፍናልና ከሁሉ በፊት እርስ በርሳችሁ አጥብቃችሁ ተዋደዱ።'),
  ('76da76e9-2813-559b-aca7-07701f0a72e2', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '2eceacee-7318-50fe-a076-02c1205b2a64', 8, 9, 'ያለ ማንጐራጐር እርስ በርሳችሁ እንግድነትን ተቀባበሉ፤'),
  ('1761602a-f4b4-54b5-a9a5-b2f82eed592f', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '2eceacee-7318-50fe-a076-02c1205b2a64', 9, 10, 'ልዩ ልዩን የእግዚአብሔርን ጸጋ ደጋግ መጋቢዎች እንደ መሆናችሁ፥ እያንዳንዳችሁ የጸጋን ስጦታ እንደ ተቀበላችሁ መጠን በዚያው ጸጋ እርስ በርሳችሁ አገልግሉ፤'),
  ('1bf03e1c-f7d9-5668-a7d5-51bdb9905a92', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '2eceacee-7318-50fe-a076-02c1205b2a64', 10, 11, 'ማንም ሰው የሚናገር ቢሆን፥ እንደ እግዚአብሔር ቃል ይናገር፤ የሚያገለግልም ቢሆን፥ “እግዚአብሔር በሚሰጠኝ ኀይል ነው” ብሎ ያገልግል፤ ክብርና ሥልጣን እስከ ዘላለም ድረስ ለእርሱ በሚሆነው በኢየሱስ ክርስቶስ በኩል እግዚአብሔር በነገር ሁሉ ይከብር ዘንድ፤ አሜን።'),
  ('af44d542-8136-5a8c-a4e6-7de0569b503a', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '679948c3-f747-5914-a8aa-2f14b592f9e4', 1, 12, 'ወዳጆች ሆይ! በእናንተ መካከል እንደ እሳት ሊፈትናችሁ ስለሚሆነው መከራ ድንቅ ነገር እንደ መጣባችሁ አትደነቁ፤'),
  ('61426e87-5e78-5296-a203-0c8d0bf00df8', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '679948c3-f747-5914-a8aa-2f14b592f9e4', 2, 13, 'ነገር ግን ክብሩ ሲገለጥ ደግሞ ሐሤት እያደረጋችሁ ደስ እንዲላችሁ፥ በክርስቶስ መከራ በምትካፈሉበት ልክ ደስ ይበላችሁ።'),
  ('0c599746-32ae-5e86-a9c3-746892764dc8', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '679948c3-f747-5914-a8aa-2f14b592f9e4', 3, 14, 'ስለ ክርስቶስ ስም ብትነቀፉ የክብር መንፈስ የእግዚአብሔር መንፈስ በእናንተ ላይ ያርፋልና ብፁዓን ናችሁ።'),
  ('558c08f3-992a-5de5-ae5b-2145ac1be1de', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '679948c3-f747-5914-a8aa-2f14b592f9e4', 4, 15, 'ከእናንተ ማንም ነፍሰ ገዳይ ወይም ሌባ ወይም ክፉ አድራጊ እንደሚሆን ወይም በሌሎች ጉዳይ እንደሚገባ ሆኖ መከራን አይቀበል፤'),
  ('3992a3a3-c268-5393-a429-9a7426dbdceb', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '679948c3-f747-5914-a8aa-2f14b592f9e4', 5, 16, 'ክርስቲያን እንደሚሆን ግን መከራን ቢቀበል ስለዚህ ስም እግዚአብሔርን ያመስግን እንጂ አይፈር።'),
  ('76f143a0-5f43-5000-a83a-38f3edb61b53', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '679948c3-f747-5914-a8aa-2f14b592f9e4', 6, 17, 'ፍርድ ከእግዚአብሔር ቤት ተነሥቶ የሚጀመርበት ጊዜ ደርሶአልና፤ አስቀድሞም በእኛ የሚጀመር ከሆነ ለእግዚአብሔር ወንጌል የማይታዘዙ መጨረሻቸው ምን ይሆን?'),
  ('36f1ed93-a07d-5885-a978-8bc13f2bf02e', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '679948c3-f747-5914-a8aa-2f14b592f9e4', 7, 18, 'ጻድቅም በጭንቅ የሚድን ከሆነ ዐመፀኛውና ኀጢአተኛው ወዴት ይታይ ዘንድ አለው?'),
  ('5f209c7a-1e57-5b90-a225-0500b529d1e8', '6bf94c3d-6532-50c2-aeff-768b5cf3913f', '679948c3-f747-5914-a8aa-2f14b592f9e4', 8, 19, 'ስለዚህ ደግሞ እንደ እግዚአብሔር ፈቃድ መከራን የሚቀበሉ፥ መልካምን እያደረጉ ነፍሳቸውን ለታመነ ፈጣሪ አደራ ይስጡ።'),
  ('3a8b6a2e-a0c6-5757-a93d-c17e047724cb', '3715f55d-6e0d-5977-a2a2-31b33dd6ce3c', 'd1092ae0-f8f1-59a9-a356-85e28f9e5aac', 1, 1, 'እንግዲህ እኔ ከእነርሱ ጋር ሽማግሌ የክርስቶስም መከራ ምስክር ደግሞም ሊገለጥ ካለው ክብር ተካፋይ የሆንሁ፥ በመካከላቸው ያሉትን ሽማግሌዎች እመክራቸዋለሁ፤'),
  ('d58cfc80-719f-5be6-a5dd-4ea9b5dc2a51', '3715f55d-6e0d-5977-a2a2-31b33dd6ce3c', 'd1092ae0-f8f1-59a9-a356-85e28f9e5aac', 2, 2, 'በእናንተ ዘንድ ያለውን የእግዚአብሔርን መንጋ ጠብቁ፤ እንደ እግዚአብሔር ፈቃድ በውድ እንጂ በግድ ሳይሆን፥ በበጎ ፈቃድ እንጂ መጥፎውን ረብ በመመኘት ሳይሆን ጐብኙት፤'),
  ('1f1fe1ea-111f-5747-a6b9-baa6e3e76b4c', '3715f55d-6e0d-5977-a2a2-31b33dd6ce3c', 'd1092ae0-f8f1-59a9-a356-85e28f9e5aac', 3, 3, 'ለመንጋው ምሳሌ ሁኑ እንጂ ማኅበሮቻችሁን በኀይል አትግዙ፤'),
  ('2db1c5e8-7031-5cd6-aec4-a720a3627da5', '3715f55d-6e0d-5977-a2a2-31b33dd6ce3c', 'd1092ae0-f8f1-59a9-a356-85e28f9e5aac', 4, 4, 'የእረኞችም አለቃ በሚገለጥበት ጊዜ የማያልፈውን የክብርን አክሊል ትቀበላላችሁ።'),
  ('108755c4-29c8-506b-ae32-090a429ed25d', '3715f55d-6e0d-5977-a2a2-31b33dd6ce3c', 'd1092ae0-f8f1-59a9-a356-85e28f9e5aac', 5, 5, 'እንዲሁም ጐበዞች ሆይ! ለሽማግሌዎች ተገዙ፤ ሁላችሁም እርስ በርሳችሁ እየተዋረዳችሁ ትሕትናን እንደ ልብስ ልበሱ፤ እግዚአብሔር ትዕቢተኞችን ይቃወማልና፤ ለትሑታኑ ግን ጸጋን ይሰጣል።'),
  ('802d8b26-c72e-5f17-a05e-c084c594b60e', '3715f55d-6e0d-5977-a2a2-31b33dd6ce3c', 'd1092ae0-f8f1-59a9-a356-85e28f9e5aac', 6, 6, 'እንግዲህ በጊዜው ከፍ እንዲያደርጋችሁ ከኀይለኛው ከእግዚአብሔር እጅ በታች ራሳችሁን አዋርዱ፤'),
  ('1e877fb8-334d-597f-af95-c8e31afd3fa6', '3715f55d-6e0d-5977-a2a2-31b33dd6ce3c', 'd1092ae0-f8f1-59a9-a356-85e28f9e5aac', 7, 7, 'እርሱ ስለ እናንተ ያስባልና የሚያስጨንቃችሁን ሁሉ በእርሱ ላይ ጣሉት።'),
  ('22f6ff91-a15f-577f-a989-ad59f180b006', '3715f55d-6e0d-5977-a2a2-31b33dd6ce3c', 'd1092ae0-f8f1-59a9-a356-85e28f9e5aac', 8, 8, 'በመጠን ኑሩ፤ ንቁም፤ ባላጋራችሁ ዲያብሎስ የሚውጠውን ፈልጎ እንደሚያገሣ አንበሳ ይዞራልና፤'),
  ('7ab2934a-51bc-559f-ac33-c42a81c1779d', '3715f55d-6e0d-5977-a2a2-31b33dd6ce3c', 'd1092ae0-f8f1-59a9-a356-85e28f9e5aac', 9, 9, 'በዓለም ያሉት ወንድሞቻችሁ ያን መከራ በሙሉ እንዲቀበሉ እያወቃችሁ በእምነት ጸንታችሁ ተቃወሙት።'),
  ('d576919c-c60c-5388-a7f1-43c27fa3c745', '3715f55d-6e0d-5977-a2a2-31b33dd6ce3c', 'd1092ae0-f8f1-59a9-a356-85e28f9e5aac', 10, 10, 'በክርስቶስ ኢየሱስ ወደ ዘላለም ክብሩ የጠራችሁ የጸጋ ሁሉ አምላክ ለጥቂት ጊዜ መከራን ከተቀበላችሁ በኋላ፥ ራሱ ፍጹማን ያደርጋችኋል፤ ያጸናችሁማል፤ ያበረታችሁማል።'),
  ('69999557-717b-577b-a030-9839b7d76adf', '3715f55d-6e0d-5977-a2a2-31b33dd6ce3c', 'd1092ae0-f8f1-59a9-a356-85e28f9e5aac', 11, 11, 'ለእርሱ ክብርና ኀይል እስከዘላለም ድረስ ይሁን፤ አሜን።'),
  ('f422fc35-9614-596e-a21b-fadd365cdfbd', '3715f55d-6e0d-5977-a2a2-31b33dd6ce3c', '7c637147-df4e-50aa-a11f-791b6ceaf58c', 1, 12, 'እየመከርኋችሁና የምትቆሙባት ጸጋ እውነትኛ የእግዚአብሔር ጸጋ እንድትሆን እየመሰከርሁላችሁ፥ የታመነ ወንድም እንደ ሆነ በቈጠርሁት በስልዋኖስ እጅ በአጭሩ ጽፌላችኋለሁ።'),
  ('2a5eb60b-f41c-5c20-a796-8f93b08395ee', '3715f55d-6e0d-5977-a2a2-31b33dd6ce3c', '7c637147-df4e-50aa-a11f-791b6ceaf58c', 2, 13, 'ከእናንተ ጋር ተመርጣ በባቢሎን ያለች ቤተ ክርስቲያን፥ ልጄም ማርቆስ ሰላምታ ያቀርቡላችኋል።'),
  ('d7ba17a5-3f13-5abb-a805-e7482ffa874a', '3715f55d-6e0d-5977-a2a2-31b33dd6ce3c', '7c637147-df4e-50aa-a11f-791b6ceaf58c', 3, 14, 'በፍቅር አሳሳም እርስ በርሳችሁ ሰላምታ ተሰጣጡ። በክርስቶስ ላላችሁ ለሁላችሁ ሰላም ይሁን። አሜን።'),
  ('5489eda8-272f-5948-a36a-d3aea9e9709d', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '12811559-f372-5d4c-a700-040c76db5d4b', 1, 1, 'የኢየሱስ ክርስቶስ ባሪያና ሐዋርያ ከሆነው ከስምዖን ጴጥሮስ፥ በአምላካችንና በመድኃኒታችን በኢየሱስ ክርስቶስ ጽድቅ ካገኘነው ጋር የተካከለ የክብር እምነትን ላገኙ፤'),
  ('74c50513-cf40-5a4a-a964-d5230fe403e9', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '9f2e0a04-5a29-59e1-a5bf-94356ca5bc0d', 1, 2, 'የመለኮቱ ኀይል በገዛ ክብሩና በበጎነቱ የጠራንን በማወቅ፥ ለሕይወትና እግዚአብሔርን ለመምሰል የሚሆነውን ነገር ሁሉ ስለ ሰጠን፥ በእግዚአብሔርና በጌታችን በኢየሱስ እውቀት ጸጋና ሰላም ይብዛላችሁ።'),
  ('c7532d57-1553-5560-a816-cb2b17f2bdd5', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '9f2e0a04-5a29-59e1-a5bf-94356ca5bc0d', 2, 4, 'ስለ ክፉ ምኞት በዓለም ካለው ጥፋት አምልጣችሁ በተስፋው ቃል ከመለኮት ባሕርይ ተካፋዮች እንድትሆኑ፥ በእነዚያ ክብርና በጎነት የተከበረና እጅግ ታላቅ የሆነ ተስፋን ሰጠን።'),
  ('eb005519-3b94-50c2-a54b-ed9e4f4db34f', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '9f2e0a04-5a29-59e1-a5bf-94356ca5bc0d', 3, 5, 'ስለዚህም ምክንያት ትጋትን ሁሉ እያሳያችሁ በእምነታችሁ በጎነትን ጨምሩ፥'),
  ('7583955b-562c-57c5-a1f4-0ce5da3bac7d', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '9f2e0a04-5a29-59e1-a5bf-94356ca5bc0d', 4, 6, 'በበጎነትም እውቀትን፥ በእውቀትም ራስን መግዛት፥ ራስንም በመግዛት መጽናትን፥ በመጽናትም እግዚአብሔርን መምሰል፥'),
  ('a15bbc65-5fee-5fc2-a0e8-24f1b0470be6', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '9f2e0a04-5a29-59e1-a5bf-94356ca5bc0d', 5, 7, 'እግዚአብሔርንም በመምሰል የወንድማማችን መዋደድ፥ በወንድማማችም መዋደድ ፍቅርን ጨምሩ።'),
  ('f590b95c-ba8b-5f00-a4a7-dfba8cfb3338', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '9f2e0a04-5a29-59e1-a5bf-94356ca5bc0d', 6, 8, 'እነዚህ ነገሮች ለእናንተ ሆነው ቢበዙ፥ በጌታችን በኢየሱስ ክርስቶስ እውቀት ሥራ ፈቶችና ፍሬ ቢሶች እንዳትሆኑ ያደርጉአችኋልና፤'),
  ('21395729-1b41-5fdd-a21e-a36bb999b386', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '9f2e0a04-5a29-59e1-a5bf-94356ca5bc0d', 7, 9, 'እነዚህ ነገሮች የሌሉት ዕውር ነውና፤ በቅርብም ያለውን ብቻ ያያል፤ የቀደመውንም ኀጢአቱን መንጻት ረስቶአል።'),
  ('707a145f-4340-57bc-a8a2-0ca1cf223ced', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '9f2e0a04-5a29-59e1-a5bf-94356ca5bc0d', 8, 10, 'ስለዚህ ወንድሞች ሆይ! መጠራታችሁንና መመረጣችሁን ታጸኑ ዘንድ ከፊት ይልቅ ትጉ፤ እነዚህን ብታደርጉ ከቶ አትሰናከሉምና።'),
  ('a0575f0e-86a2-5286-af1f-f382b66e5ef8', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '9f2e0a04-5a29-59e1-a5bf-94356ca5bc0d', 9, 11, 'እንዲሁ ወደ ዘላለሙ ወደ ጌታችንና መድኃኒታችን ወደ ኢየሱስ ክርስቶስ መንግሥት መግባት በሙላት ይሰጣችኋልና።'),
  ('170a97ce-2bee-5c23-aa56-b970d1858620', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '9f2e0a04-5a29-59e1-a5bf-94356ca5bc0d', 10, 12, 'ስለዚህ እነዚህን ነገሮች ምንም ብታውቁ፥ በእናንተም ዘንድ ባለ እውነት ምንም ብትጸኑ፥ ስለ እነዚህ ዘወትር እንዳሳስባችሁ ቸል አልልም።'),
  ('ede00741-b942-5905-aa58-dc8aadc0eaa7', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '9f2e0a04-5a29-59e1-a5bf-94356ca5bc0d', 11, 13, 'ሁልጊዜም በዚህ አካል ሳለሁ በማሳሰቤ ላነቃችሁ የሚገባኝ ይመስለኛል።'),
  ('27f577f4-5ed1-5406-a0a6-51f5a1837fa9', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '9f2e0a04-5a29-59e1-a5bf-94356ca5bc0d', 12, 14, 'ጌታችን ኢየሱስ ክርስቶስ እንዳመለከተኝ ከዚህ አካሌ መለየቴ ፈጥኖ እንዲሆን አውቃለሁና።'),
  ('194f75aa-ddc3-58ce-afef-5fd1342dee89', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '9f2e0a04-5a29-59e1-a5bf-94356ca5bc0d', 13, 15, 'ከመውጣቴም በኋላ እነዚህን ነገሮች እንድታስቡ በየጊዜው ትችሉ ዘንድ እተጋለሁ።'),
  ('f2bf9398-ab63-55e3-a282-fa4ef1ce19dc', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '4b32a8fa-3d6a-5587-a618-66ccef5db148', 1, 16, 'የእርሱን ግርማ አይተን እንጂ በብልሃት የተፈጠረውን ተረት ሳንከተል የጌታችንን የኢየሱስ ክርስቶስን ኀይልና መምጣት አስታወቅናችሁ።'),
  ('a30a00ff-cda3-5f43-af5e-e799d47ffd33', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '4b32a8fa-3d6a-5587-a618-66ccef5db148', 2, 17, 'ከገናናው ክብር “በእርሱ ደስ የሚለኝ የምወደው ልጄ ይህ ነው፤” የሚል ያ ድምፅ በመጣለት ጊዜ ከእግዚአብሔር አብ ክብርንና ምስጋናን ተቀብሎአልና፤'),
  ('cabec751-91bd-54f2-a1ad-4a7d455e622d', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '4b32a8fa-3d6a-5587-a618-66ccef5db148', 3, 18, 'እኛም በቅዱሱ ተራራ ከእርሱ ጋር ሳለን ይህን ድምፅ ከሰማይ ሲወርድ ሰማን።'),
  ('740405de-476e-5fbb-a430-8b6802ca5525', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '4b32a8fa-3d6a-5587-a618-66ccef5db148', 4, 19, 'ከእርሱም ይልቅ እጅግ የጸና የትንቢት ቃል አለን፤ ምድርም እስኪጠባ ድረስ የንጋትም ኮከብ በልባችሁ እስኪወጣ ድረስ፥ ሰው በጨለማ ስፍራ የሚበራን መብራት እንደሚጠነቀቅ ይህን ቃል እየጠነቀቃችሁ መልካም ታደርጋላችሁ።'),
  ('30f8c781-610e-5e15-a40b-cb9b3199e2e7', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '4b32a8fa-3d6a-5587-a618-66ccef5db148', 5, 20, 'ይህን በመጀመሪያ እወቁ፤ በመጽሐፍ ያለውን ትንቢት ሁሉ ማንም ለገዛ ራሱ ሊተረጉም አልተፈቀደም፤'),
  ('74da4e4d-64df-5872-a9f2-45c1c3fdb471', 'bf1aed25-b513-5786-a9b3-ab2b8af48abb', '4b32a8fa-3d6a-5587-a618-66ccef5db148', 6, 21, 'ትንቢት ከቶ በሰው ፈቃድ አልመጣምና፤ ዳሩ ግን በእግዚአብሔር ተልከው ቅዱሳን ሰዎች በመንፈስ ቅዱስ ተነድተው ተናገሩ።'),
  ('3319807e-d765-59ff-aa13-ec07eaa998b2', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 1, 1, 'ነገር ግን ሐሰተኞች ነቢያት ደግሞ በሕዝቡ መካከል ነበሩ፤ እንዲሁም በመካከላችሁ ደግሞ ሐሰተኞች አስተማሪዎች ይሆናሉ፤ እነርሱም የዋጃቸውን ጌታ እንኳ ክደው የሚፈጥንን ጥፋት በራሳቸው ላይ እየሳቡ የሚያጠፋ ኑፋቄን አሹልከው ያገባሉ፤'),
  ('e8c005d5-36dd-5e14-abdd-6cf5031fb7de', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 2, 2, 'ብዙዎችም በመዳራታቸው ይከተሉአቸዋል፤ በእነርሱም ጠንቅ የእውነት መንገድ ይሰደባል።'),
  ('28440b28-8c2c-5cac-ac7a-ff5a843af493', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 3, 3, 'ገንዘብንም በመመኘት በተፈጠረ ነገር ይረቡባችኋል፤ ፍርዳቸውም ከጥንት ጀምሮ አይዘገይም፤ ጥፋታቸውም አያንቀላፋም።'),
  ('9b55ed6e-29c1-5d0e-a3d5-2ad020de85c4', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 4, 4, 'እግዚአብሔር ኀጢአትን ላደረጉ መላእክት ሳይራራላቸው ወደ ገሃነም ጥሎ በጨለማ ጉድጓድ ለፍርድ ሊጠበቁ አሳልፎ ከሰጣቸው፥'),
  ('18c010a0-b89c-5536-a78e-a4383e66f58b', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 5, 5, 'ለቀደመውም ዓለም ሳይራራ ከሌሎች ሰባት ጋር ጽድቅን የሚሰብከውን ኖኅን አድኖ በኀጢአተኞች ዓለም ላይ የጥፋትን ውሃ ካወረደ፥'),
  ('c7d092c2-b4a6-5253-ad9d-d4ab702b5b75', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 6, 6, 'ኀጢአትንም ያደርጉ ዘንድ ላሉት ምሳሌ አድርጎ ከተማዎችን ሰዶምንና ገሞራን አመድ እስኪሆኑ ድረስ አቃጥሎና ገልብጦ ከፈረደባቸው፥'),
  ('72d91157-4502-5b2c-a7b3-07b7eccd8bc1', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 7, 7, 'ጻድቅ ሎጥም በመካከላቸው ሲኖር እያየና እየሰማ ዕለት ዕለት በዐመፀኛ ሥራቸው ጻድቅ ነፍሱን አስጨንቆ ነበርና በዐመፀኞች ሴሰኛ ኑሮ የተገፋውን ያን ጻድቅ ካዳነ፥'),
  ('c963b293-b5e9-5de2-a2c6-7a9f6316293c', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 8, 9, 'ጌታ እግዚአብሔርን የሚያመልኩትን ከፈተና እንዴት እንዲያድን በደለኞችንም ይልቁንም በርኵስ ምኞት የሥጋን ፍትወት እየተከተሉ የሚመላለሱትን ጌትነትንም የሚንቁትን እየቀጣቸው ለፍርድ ቀን እንዴት እንዲጠብቅ ያውቃል። ደፋሮችና ኵሩዎች ሆነው ሥልጣን ያላቸውን ሲሳደቡ አይንቀጠቀጡም፤'),
  ('e950ff78-66c4-53f9-a66f-a89423193a0e', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 9, 11, 'ዳሩ ግን መላእክት በኀይልና በብርታት ከእነርሱ ይልቅ ምንም ቢበልጡ፥ በጌታ ፊት በእነርሱ ላይ የስድብን ፍርድ አያመጡም።'),
  ('dc800c5a-5929-51ca-ab3e-5ee8b48ec0b2', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 10, 12, 'እነዚህ ግን ለመጠመድና ለመጥፋት በፍጥረታቸው እንደ ተወለዱ አእምሮ እንደ ሌላቸው እንስሶች ሆነው፥ በማያውቁት ነገር እየተሳደቡ በጥፋታቸው ይጠፋሉ፤'),
  ('ce3ec891-1619-58ef-a034-daeb9f38240b', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 11, 13, 'የዐመፃቸውን ደመወዝ ይቀበላሉ። በቀን ሲዘፍኑ እንደ ተድላ ይቆጥሩታል፤ ነውረኞችና ርኵሳን ሆነው ከእናንተ ጋር ሲጋበዙ በፍቅር ግብዣ ይዘፍናሉ፤'),
  ('30a44022-9fef-5dee-a795-8002d87bf5bf', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 12, 14, 'ምንዝር የሞላባቸው ኀጢአትንም የማይተዉ ዐይኖች አሉአቸው፤ የማይጸኑትን ነፍሳት ያታልላሉ፤ መመኘትን የለመደ ልብ አላቸው፤ የተረገሙ ናቸው።'),
  ('6a2b48d7-0715-5eba-a0c2-6d597973b584', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 13, 15, 'ቅንን መንገድ ትተው ተሳሳቱ፤ የባሶርን ልጅ የበለዓምን መንገድ ተከተሉ፤ እርሱ የዐመፃን ደመወዝ ወደደ፤'),
  ('c65365bd-d120-54e9-a4ca-be2794a6a7bd', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 14, 16, 'ነገር ግን ስለ መተላለፉ ተዘለፈ፤ ቃል የሌለው አህያ በሰው ቃል ተናግሮ የነቢዩን እብድነት አገደ።'),
  ('443b0a79-32b8-59d5-af24-b4066b31b68f', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 15, 17, 'ድቅድቅ ጨለማ ለዘላለም የተጠበቀላቸው እነዚህ ውሃ የሌለባቸው ምንጮች በዐውሎ ነፋስም የተነዱ ደመናዎች ናቸው።'),
  ('717873ee-6e20-5f30-a517-b8dc721be528', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 16, 18, 'ከንቱና ከመጠን ይልቅ ታላቅ የሆነውን ቃል ይናገራሉና፤ በስሕተትም ከሚኖሩት አሁን የሚያመልጡትን በሥጋ ሴሰኛ ምኞት ያታልላሉ።'),
  ('8d9c60e6-51d6-5328-a379-9e37f0c9a6cf', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 17, 19, 'ራሳቸው የጥፋት ባሪያዎች ሆነው “አርነት ትወጣላችሁ፤” እያሉ ተስፋ ይሰጡአቸዋል፤ ሰው ለተሸነፈበት ለእርሱ ተገዝቶ ባሪያ ነውና።'),
  ('1310d973-7aa6-58fc-a551-290134c0f590', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 18, 20, 'በጌታችንና በመድኃኒታችን በኢየሱስ ክርስቶስ ዕውቀት ከዓለም ርኵሰት ካመለጡ በኋላ ዳግመኛ በእርስዋ ተጠላልፈው የተሸነፉ ቢሆኑ፥ ከፊተኛው ኑሮአቸው ይልቅ የኋለኛው የባሰ ሆኖባቸዋል።'),
  ('76598ef6-001f-509f-acfd-34304e161eb3', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 19, 21, 'ዕውቀዋት ከተሰጣቸው ከቅድስት ትእዛዝ ከሚመለሱ የጽድቅን መንገድ ባላወቋት በተሻላቸው ነበርና።'),
  ('71a965bd-4a9c-5d53-a910-053b3773a855', 'c5c0b7d5-5668-5780-ae0d-ed924b2fabd3', '84cb8fa2-e51a-5a1d-a431-c69393db3649', 20, 22, '“ውሻ ወደ ትፋቱ ይመለሳል፤” ደግሞ “የታጠበች እርያ በጭቃ ለመንከባለል ትመለሳለች፤” እንደሚባል እውነተኞች ምሳሌዎች ሆኖባቸዋል።'),
  ('53f90621-7025-5f0e-a6b6-48e46e3b2afa', '4b534816-709c-55f9-ac52-9c299de58349', 'a471fcae-5f89-5233-a57f-ef9721a80e5a', 1, 1, 'ወዳጆች ሆይ! አሁን የምጽፍላችሁ መልእክት ይህች ሁለተኛይቱ ናት። በቅዱሳን ነቢያትም ቀድሞ የተባለውን ቃል በሐዋርያቶቻችሁም ያገኛችኋትን የጌታችንንና የመድኃኒታችንን ትእዛዝ እንድታስቡ በሁለቱ እያሳሰብኋችሁ ቅን ልቡናችሁን አነቃቃለሁ።'),
  ('0a64520d-b5fd-5375-afde-ea58eb22a054', '4b534816-709c-55f9-ac52-9c299de58349', 'a471fcae-5f89-5233-a57f-ef9721a80e5a', 2, 3, 'በመጨረሻው ዘመን እንደ ራሳቸው ምኞት የሚመላለሱ ዘባቾች በመዘበት እንዲመጡ ይህን በፊት እወቁ፤'),
  ('11731f16-d9d2-55ae-ae17-e688fb5c0521', '4b534816-709c-55f9-ac52-9c299de58349', 'a471fcae-5f89-5233-a57f-ef9721a80e5a', 3, 4, 'እነርሱም “የመምጣቱ የተስፋ ቃል ወዴት ነው? አባቶች ከሞቱባት ጊዜ ከፍጥረት መጀመሪያ ይዞ ሁሉ እንዳለ ይኖራልና፤” ይላሉ።'),
  ('da48d3b1-fc69-527d-a4a5-a2ed51f881aa', '4b534816-709c-55f9-ac52-9c299de58349', 'a471fcae-5f89-5233-a57f-ef9721a80e5a', 4, 5, 'ሰማያት ከጥንት ጀምረው ምድርም በእግዚአብሔር ቃል ከውሃ ተጋጥማ በውሃ መካከል እንደ ነበሩ ወደው አያስተውሉምና፤'),
  ('0d9f3e74-9dd2-5e37-a2e9-7a1a46856222', '4b534816-709c-55f9-ac52-9c299de58349', 'a471fcae-5f89-5233-a57f-ef9721a80e5a', 5, 6, 'በዚህም ምክንያት ያን ጊዜ የነበረ ዓለም በውሃ ሰጥሞ ጠፋ፤'),
  ('ba39e6e9-518d-5a21-ad30-de55e57f3440', '4b534816-709c-55f9-ac52-9c299de58349', 'a471fcae-5f89-5233-a57f-ef9721a80e5a', 6, 7, 'አሁን ያሉ ሰማያትና ምድር ግን እግዚአብሔርን የማያመልኩት ሰዎች እስከሚጠፉበት እስከ ፍርድ ቀን ድረስ ተጠብቀው በዚያ ቃል ለእሳት ቀርተዋል።'),
  ('8af30f94-4eff-5e08-ac9f-86a19837aee1', '4b534816-709c-55f9-ac52-9c299de58349', 'a471fcae-5f89-5233-a57f-ef9721a80e5a', 7, 8, 'እናንተ ግን ወዳጆች ሆይ! በጌታ ዘንድ አንድ ቀን እንደ ሺህ ዓመት፥ ሺህ ዓመትም እንደ አንድ ቀን እንደ ሆነ ይህን አንድ ነገር አትርሱ።'),
  ('b0ca82e2-4eea-5f91-ab96-4ca33a291020', '4b534816-709c-55f9-ac52-9c299de58349', 'a471fcae-5f89-5233-a57f-ef9721a80e5a', 8, 9, 'ለአንዳንዶች የሚዘገይ እንደሚመስላቸው ጌታ ስለ ተስፋ ቃሉ አይዘገይም፤ ነገር ግን ሁሉ ወደ ንስሓ እንዲደርሱ እንጂ ማንም እንዳይጠፋ ወዶ ስለ እናንተ ይታገሣል።'),
  ('30e6543b-5420-5bc7-a0b9-56bed420b160', '4b534816-709c-55f9-ac52-9c299de58349', 'a471fcae-5f89-5233-a57f-ef9721a80e5a', 9, 10, 'የጌታው ቀን ግን እንደ ሌባ ሆኖ ይመጣል፤ በዚያም ቀን ሰማያት በታላቅ ድምፅ ያልፋሉ፤ የሰማይም ፍጥረት በትልቅ ትኵሳት ይቀልጣል፤ ምድርም በእርስዋም ላይ የተደረገው ሁሉ ይቃጠላል።'),
  ('e4550335-08ca-599e-ae9e-2fabd523397d', '4b534816-709c-55f9-ac52-9c299de58349', 'a471fcae-5f89-5233-a57f-ef9721a80e5a', 10, 11, 'ይህ ሁሉ እንዲህ የሚቀልጥ ከሆነ፥ የእግዚአብሔርን ቀን መምጣት እየጠበቃችሁና እያስቸኰላችሁ በቅዱስ ኑሮ እግዚአብሔርንም በመምሰል እንደ ምን ልትሆኑ ይገባችኋል? ስለዚያ ቀን ሰማያት ተቃጥለው ይቀልጣሉ፤ የሰማይም ፍጥረት በትልቅ ትኵሳት ይፈታል፤'),
  ('da4adedb-81b7-5125-aa49-eab47c1598b4', '4b534816-709c-55f9-ac52-9c299de58349', 'a471fcae-5f89-5233-a57f-ef9721a80e5a', 11, 13, 'ነገር ግን ጽድቅ የሚኖርባትን አዲስ ሰማይና አዲስ ምድር እንደ ተስፋ ቃሉ እንጠብቃለን።'),
  ('7165cd77-96ac-55f1-a86b-fde241baf7e7', '4b534816-709c-55f9-ac52-9c299de58349', 'a471fcae-5f89-5233-a57f-ef9721a80e5a', 12, 14, 'ስለዚህ ወዳጆች ሆይ! ይህን እየጠበቃችሁ ያለ ነውርና ያለ ነቀፋ ሆናችሁ በሰላም በእርሱ እንድትገኙ ትጉ፤'),
  ('01e846d3-950b-561d-a200-cca3e4192748', '4b534816-709c-55f9-ac52-9c299de58349', 'a471fcae-5f89-5233-a57f-ef9721a80e5a', 13, 15, 'የጌታችንም ትዕግሥት መዳናችሁ እንደ ሆነ ቍጠሩ። እንዲህም የተወደደው ወንድማችን ጳውሎስ ደግሞ እንደ ተሰጠው ጥበብ መጠን ጻፈላችሁ፤'),
  ('934bc504-53ce-5678-a930-e74bcfb86ae4', '4b534816-709c-55f9-ac52-9c299de58349', 'a471fcae-5f89-5233-a57f-ef9721a80e5a', 14, 16, 'በመልእክቱም ሁሉ ደግሞ እንደ ነገረ ስለዚህ ነገር ተናገረ። በእነዚያ ዘንድ ለማስተዋል የሚያስቸግር ነገር አለ፤ ያልተማሩትና የማይጸኑትም ሰዎች ሌሎችን መጻሕፍት እንደሚያጣምሙ እነዚህን ደግሞ ለገዛ ጥፋታቸው ያጣምማሉ።'),
  ('2e677d00-8015-55d0-a6f1-1cdead3820f2', '4b534816-709c-55f9-ac52-9c299de58349', 'a471fcae-5f89-5233-a57f-ef9721a80e5a', 15, 17, 'እንግዲህ እናንተ ወዳጆች ሆይ! ይህን አስቀድማችሁ ስለምታውቁ፥ በዐመፀኞቹ ስሕተት ተስባችሁ ከራሳችሁ ጽናት እንዳትወድቁ ተጠንቀቁ፤'),
  ('cb6ebedd-b746-5f97-a195-04b15f4b9e6b', '4b534816-709c-55f9-ac52-9c299de58349', 'a471fcae-5f89-5233-a57f-ef9721a80e5a', 16, 18, 'ነገር ግን በጌታችንና በመድኃኒታችን በኢየሱስ ክርስቶስ ጸጋና እውቀት እደጉ። ለእርሱ አሁንም እስከ ዘላለምም ቀን ድረስ ክብር ይሁን፤ አሜን።'),
  ('e6fe3723-387e-54b0-a07e-e9bba4b9e7ee', 'ea7f3588-bfa4-5912-a877-308210e03e74', '6398bc22-7e33-5111-ac62-d15216327f0d', 1, 1, 'ስለ ሕይወት ቃል ከመጀመሪያው የነበረውንና የሰማነውን በዓይኖቻችንም ያየነውን የተመለከትነውንም እጆቻችንም የዳሰሱትን እናወራለን፤'),
  ('1f3707cb-bbd6-5ab3-afd1-ffe6896a166a', 'ea7f3588-bfa4-5912-a877-308210e03e74', '6398bc22-7e33-5111-ac62-d15216327f0d', 2, 2, 'ሕይወትም ተገለጠ አይተንማል እንመሰክርማለን፥ ከአብ ዘንድ የነበረውንም ለእኛም የተገለጠውን የዘላለምን ሕይወት እናወራላችኋለን፤'),
  ('0075a12b-8bc9-5219-ad2f-86cd8c10cee8', 'ea7f3588-bfa4-5912-a877-308210e03e74', '6398bc22-7e33-5111-ac62-d15216327f0d', 3, 3, 'እናንተ ደግሞ ከእኛ ጋር ኅብረት እንዲኖራችሁ ያየነውንና የሰማነውን ለእናንተ ደግሞ እናወራላችኋለን። ኅብረታችንም ከአባት ጋር ከልጁም ከኢየሱስ ክርስቶስ ጋር ነው።'),
  ('b83b3a8f-f879-5dba-a1d8-ccb2be2ca317', 'ea7f3588-bfa4-5912-a877-308210e03e74', '6398bc22-7e33-5111-ac62-d15216327f0d', 4, 4, 'ደስታችሁም እንዲፈጸም ይህን እንጽፍላችኋለን።'),
  ('eda5aed6-a3f9-569f-ad1b-c889643674fa', 'ea7f3588-bfa4-5912-a877-308210e03e74', '6398bc22-7e33-5111-ac62-d15216327f0d', 5, 5, 'ከእርሱም የሰማናት ለእናንተም የምናወራላችሁ መልእክት፦ እግዚአብሔር ብርሃን ነው ጨለማም በእርሱ ዘንድ ከቶ የለም የምትል ይህች ናት።'),
  ('29b4837f-a189-5347-aea2-b26c5f1e6c81', 'ea7f3588-bfa4-5912-a877-308210e03e74', '6398bc22-7e33-5111-ac62-d15216327f0d', 6, 6, 'ከእርሱ ጋር ኅብረት አለን ብንል በጨለማም ብንመላለስ እንዋሻለን እውነትንም አናደርግም፤'),
  ('8177dbd3-2eec-5ba9-a848-bfbca23ce8bf', 'ea7f3588-bfa4-5912-a877-308210e03e74', '6398bc22-7e33-5111-ac62-d15216327f0d', 7, 7, 'ነገር ግን እርሱ በብርሃን እንዳለ በብርሃን ብንመላለስ ለእያንዳንዳችን ኅብረት አለን፥ የልጁም የኢየሱስ ክርስቶስ ደም ከኃጢአት ሁሉ ያነጻናል።'),
  ('a5c3099e-c0ea-5e2f-a019-d907be9e147e', 'ea7f3588-bfa4-5912-a877-308210e03e74', '6398bc22-7e33-5111-ac62-d15216327f0d', 8, 8, 'ኃጢአት የለብንም ብንል ራሳችንን እናስታለን፥ እውነትም በእኛ ውስጥ የለም።'),
  ('e11f7ff8-c150-5521-a69c-dfe35efc9f8b', 'ea7f3588-bfa4-5912-a877-308210e03e74', '6398bc22-7e33-5111-ac62-d15216327f0d', 9, 9, 'በኃጢአታችን ብንናዘዝ ኃጢአታችንን ይቅር ሊለን ከዓመፃም ሁሉ ሊያነጻን የታመነና ጻድቅ ነው።'),
  ('d052d749-68e8-50ae-a04d-4f00ddd5ab8d', 'ea7f3588-bfa4-5912-a877-308210e03e74', '6398bc22-7e33-5111-ac62-d15216327f0d', 10, 10, 'ኃጢአትን አላደረግንም ብንል ሐሰተኛ እናደርገዋለን ቃሉም በእኛ ውስጥ የለም።'),
  ('2fa74430-1d86-532b-a838-b02572433ce0', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 1, 1, 'ልጆቼ ሆይ፥ ኃጢአትን እንዳታደርጉ ይህን እጽፍላችኋለሁ። ማንም ኃጢአትን ቢያደርግ ከአብ ዘንድ ጠበቃ አለን እርሱም ጻድቅ የሆነ ኢየሱስ ክርስቶስ ነው።'),
  ('cd712007-ced0-5ede-a677-36ad097c6b3f', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 2, 2, 'እርሱም የኃጢአታችን ማስተስሪያ ነው፥ ለኃጢአታችንም ብቻ አይደለም፥ ነገር ግን ለዓለሙ ሁሉ ኃጢአት እንጂ።'),
  ('88f4e127-cf79-55e5-a565-3f6137e377d5', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 3, 3, 'ትእዛዛቱንም ብንጠብቅ በዚህ እንዳወቅነው እናውቃለን።'),
  ('c86a5ae4-ead6-5010-aa68-62fc19f953fb', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 4, 4, 'አውቄዋለሁ የሚል ትእዛዛቱንም የማይጠብቅ ውሸተኛ ነው እውነትም በእርሱ ውስጥ የለም።'),
  ('d9ba3977-af86-57aa-a60f-fde3cd6a9982', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 5, 5, 'ቃሉን ግን የሚጠብቅ ሁሉ በእርሱ የእግዚአብሔር ፍቅር በእውነት ተፈጽሞአል። በእርሱ እንዳለን በዚህ እናውቃለን፤'),
  ('8ca61534-4c26-559e-a733-eaaa8cc9e883', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 6, 6, 'በእርሱ እኖራለሁ የሚል እርሱ እንደ ተመላለሰ ራሱ ደግሞ ሊመላለስ ይገባዋል።'),
  ('4820ef57-d602-5c03-a44b-84f1e097cb56', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 7, 7, 'ወንድሞች ሆይ፥ ከመጀመሪያ የነበረቻችሁ አሮጌ ትእዛዝ እንጂ የምጽፍላችሁ አዲስ ትእዛዝ አይደለችም፤ አሮጌይቱ ትእዛዝ የሰማችኋት ቃል ናት።'),
  ('e0cc5bd4-b41e-59ef-aaf0-b433ccd9a4c1', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 8, 8, 'ዳግመኛ አዲስ ትእዛዝን እጽፍላችኋለሁ፥ ይህም ነገር በእርሱ በእናንተም እውነተኛ ነው፤ ጨለማው ያልፋልና እውነተኛውም ብርሃን አሁን ይበራል።'),
  ('e2e853f9-baea-503d-a4f0-5fec27715dbf', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 9, 9, 'በብርሃን አለሁ የሚል ወንድሙንም የሚጠላ እስከ አሁን በጨለማ አለ።'),
  ('c6fc1853-3770-55f9-a122-7b857fab5f2e', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 10, 10, 'ወንድሙንም የሚወድ በብርሃን ይኖራል ማሰናከያም የለበትም፤'),
  ('5a6a99f1-a00d-50d9-a19a-842d324bdcd6', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 11, 11, 'ወንድሙን የሚጠላ ግን በጨለማ አለ፥ በጨለማም ይመላለሳል፥ የሚሄድበትንም አያውቅም፥ ጨለማው ዓይኖቹን አሳውሮታልና።'),
  ('a4cadc88-b419-54d5-a0b3-a9c0869d7508', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 12, 12, 'ልጆች ሆይ፥ ኃጢአታችሁ ስለ ስሙ ተሰርዮላችኋልና እጽፍላችኋለሁ።'),
  ('2743b52f-f501-5b0d-aded-f28fa35db507', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 13, 13, 'አባቶች ሆይ፥ ከመጀመሪያ የነበረውን አውቃችኋልና እጽፍላችኋለሁ። ጎበዞች ሆይ፥ ክፉውን አሸንፋችኋልና እጽፍላችኋለሁ። ልጆች ሆይ፥ አብን አውቃችኋልና እጽፍላችኋለሁ።'),
  ('5253ea2d-2973-5305-ab17-324d4662f105', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 14, 14, 'አባቶች ሆይ፥ ከመጀመሪያ የነበረውን አውቃችኋልና እጽፍላችኋለሁ። ጐበዞች ሆይ፥ ብርቱዎች ስለ ሆናችሁ የእግዚአብሔርም ቃል በእናንተ ስለሚኖር ክፉውንም ስለ አሸነፋችሁ እጽፍላችኋለሁ።'),
  ('290618bd-075f-5665-a6d3-7f7ed18ab3be', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 15, 15, 'ዓለምን ወይም በዓለም ያሉትን አትውደዱ፤ በዓለም ያለው ሁሉ እርሱም የሥጋ ምኞትና የዓይን አምሮት ስለ ገንዘብም መመካት ከዓለም ስለ ሆነ እንጂ ከአባት ስላልሆነ፥ ማንም ዓለምን ቢወድ የአባት ፍቅር በእርሱ ውስጥ የለም።'),
  ('28f7b567-3883-5663-a3a0-1e4aecc1098e', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 16, 17, 'ዓለሙም ምኞቱም ያልፋሉ፤ የእግዚአብሔርን ፈቃድ የሚያደርግ ግን ለዘላለም ይኖራል።'),
  ('72d88db8-81c4-5ebb-a041-96b440e2c923', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 17, 18, 'ልጆች ሆይ፥ መጨረሻው ሰዓት ነው፥ የክርስቶስም ተቃዋሚ ይመጣ ዘንድ እንደ ሰማችሁ አሁን እንኳ ብዙዎች የክርስቶስ ተቃዋሚዎች ተነሥተዋል፤ ስለዚህም መጨረሻው ሰዓት እንደ ሆነ እናውቃለን።'),
  ('9d1804cf-fe60-520c-ae5f-672afd9473ea', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 18, 19, 'ከእኛ ዘንድ ወጡ፥ ዳሩ ግን ከእኛ ወገን አልነበሩም፤ ከእኛ ወገንስ ቢሆኑ ከእኛ ጋር ጸንተው በኖሩ ነበር፤ ነገር ግን ሁሉ ከእኛ ወገን እንዳልሆኑ ይገለጡ ዘንድ ወጡ።'),
  ('76ca8379-313a-5916-ae6b-45c3133e2ff1', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 19, 20, 'እናንተም ከቅዱሱ ቅባት ተቀብላችኋል፥ ሁሉንም ታውቃላችሁ።'),
  ('f8251943-d3ac-592a-a8d8-9336427c3e0a', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 20, 21, 'እውነትን የምታውቁ ስለ ሆናችሁ፥ ውሸትም ሁሉ ከእውነት እንዳልሆነ ስለምታውቁ እንጂ እውነትን ስለማታውቁ አልጽፍላችሁም።'),
  ('82d145ea-03d2-5bf7-ad4a-30e162e1bd2c', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 21, 22, 'ክርስቶስ አይደለም ብሎ ኢየሱስን ከሚክድ በቀር ውሸተኛው ማን ነው? አብንና ወልድን የሚክድ ይህ የክርስቶስ ተቃዋሚ ነው።'),
  ('007e95c6-c5fd-57af-a0b8-54975dcd5f46', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 22, 23, 'ወልድን የሚክድ ሁሉ አብ እንኳ የለውም፤ በወልድ የሚታመን አብ ደግሞ አለው።'),
  ('28211bb2-aa5a-529b-a9ab-ee3d68b7c944', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 23, 24, 'እናንተስ ከመጀመሪያ የሰማችሁት በእናንተ ጸንቶ ይኑር። ከመጀመሪያ የሰማችሁት በእናንተ ቢኖር፥ እናንተ ደግሞ በወልድና በአብ ትኖራላችሁ።'),
  ('ab1a95e2-b630-5c9d-a6d5-7b014b2bd1c3', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 24, 25, 'እርሱም የሰጠን ተስፋ ይህ የዘላለም ሕይወት ነው።'),
  ('ba4624b6-192e-57d4-a858-547c0503e6f6', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 25, 26, 'ስለሚያስቱአችሁ ሰዎች ይህን ጽፌላችኋለሁ።'),
  ('d6cc0153-ded3-5c7f-a08a-f47bab4613d2', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 26, 27, 'እናንተስ ከእርሱ የተቀበላችሁት ቅባት በእናንተ ይኖራል፥ ማንም ሊያስተምራችሁ አያስፈልጋችሁም፤ ነገር ግን የእርሱ ቅባት ስለ ሁሉ እንደሚያስተምራችሁ፥ እውነተኛም እንደ ሆነ ውሸትም እንዳልሆነ፥ እናንተንም እንዳስተማራችሁ፥ በእርሱ ኑሩ።'),
  ('913eb52a-1b16-5225-a8c2-f13b432f16c3', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 27, 28, 'አሁንም፥ ልጆች ሆይ፥ በሚገለጥበት ጊዜ እምነት እንዲሆንልን በመምጣቱም በእርሱ ፊት እንዳናፍር በእርሱ ኑሩ።'),
  ('04390b5f-24fb-5011-ac09-adb1d4bc00e5', '11fd47c6-2c3c-5137-a97c-a1d93e6b06ac', '0ea2993f-4afa-57b2-a1a8-d640cefac35f', 28, 29, 'ጻድቅ እንደ ሆነ ካወቃችሁ ጽድቅን የሚያደርግ ሁሉ ከእርሱ እንደ ተወለደ እወቁ።'),
  ('fff652fe-3cb3-5de3-a606-9943d13cf735', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 1, 1, 'የእግዚአብሔር ልጆች ተብለን ልንጠራ አብ እንዴት ያለውን ፍቅር እንደ ሰጠን እዩ፥ እንዲሁም ነን። ስለዚህ ምክንያት ዓለም እርሱን ስላላወቀው እኛን አያውቀንም።'),
  ('24db6638-70c6-5b2b-af42-61744be4ddac', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 2, 2, 'ወዳጆች ሆይ፥ አሁን የእግዚአብሔር ልጆች ነን፥ ምንም እንደምንሆን ገና አልተገለጠም። ዳሩ ግን ቢገለጥ እርሱ እንዳለ እናየዋለንና እርሱን እንድንመስል እናውቃለን።'),
  ('3108dbcc-fd10-515f-ae9c-7bf55c4783e3', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 3, 3, 'በእርሱም ይህን ተስፋ የሚያደርግ ሁሉ እርሱ ንጹሕ እንደ ሆነ ራሱን ያነጻል።'),
  ('1adf9319-1e65-5094-a206-83453108b2ec', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 4, 4, 'ኃጢአትን የሚያደርግ ሁሉ ዓመፅን ደግሞ ያደርጋል፥ ኃጢአትም ዓመፅ ነው።'),
  ('9a1a7f56-5fe3-5b1e-ac53-5e87460af43c', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 5, 5, 'እርሱም ኃጢአትን ሊያስወግድ እንደ ተገለጠ ታውቃላችሁ፥ በእርሱም ኃጢአት የለም።'),
  ('475653e2-0424-5995-aa2a-689699479418', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 6, 6, 'በእርሱ የሚኖር ሁሉ ኃጢአትን አያደርግም፤ ኃጢአትን የሚያደርግ ሁሉ አላየውም አላወቀውምም።'),
  ('93a1c877-57b0-5b7f-a081-378fc2bdbcbf', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 7, 7, 'ልጆች ሆይ፥ ማንም አያስታችሁ፥ እርሱ ጻድቅ እንደ ሆነ ጽድቅን የሚያደርግ ጻድቅ ነው።'),
  ('f7c109fc-b44c-5194-a51e-698bef6690ff', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 8, 8, 'ኃጢአትን የሚያደርግ ከዲያብሎስ ነው፥ ዲያብሎስ ከመጀመሪያ ኃጢአትን ያደርጋልና።'),
  ('0cc69244-6011-5ba6-a6d2-fb17bdbe93b1', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 9, 9, 'ስለዚህ የዲያብሎስን ሥራ እንዲያፈርስ የግዚአብሔር ልጅ ተገለጠ። ከእግዚአብሔር የተወለደ ሁሉ ኃጢአትን አያደርግም፥ ዘሩ በእርሱ ይኖራልና፤ ከእግዚአብሔርም ተወልዶአልና ኃጢአትን ሊያደርግ አይችልም።'),
  ('2918380b-c607-5696-a318-b099b8239fee', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 10, 10, 'የእግዚአብሔር ልጆችና የዲያብሎስ ልጆች በዚህ የተገለጡ ናቸው፤ ጽድቅን የማያደርግና ወንድሙን የማይወድ ሁሉ ከእግዚአብሔር አይደለም።'),
  ('5fb780f5-d655-5142-aeae-ba3b0f065cbb', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 11, 11, 'ከመጀመሪያ የሰማችኋት መልእክት፦ እርስ በርሳችን እንዋደድ የምትል ይህች ናትና፤'),
  ('ba55b49f-9e23-5522-ab85-544100329690', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 12, 12, 'ከክፉው እንደ ነበረ ወንድሙንም እንደ ገደለ እንደ ቃየል አይደለም፤ ስለ ምንስ ገደለው? የገዛ ሥራው ክፉ፥ የወንድሙም ሥራ ጽድቅ ስለ ነበረ ነው።'),
  ('c4c52a8e-65f7-5204-aaf8-c44d561175a8', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 13, 13, 'ወንድሞች ሆይ፥ ዓለም ቢጠላችሁ አትደነቁ።'),
  ('986c9ae4-2532-55d0-afb1-ae17b555db9d', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 14, 14, 'እኛ ወንድሞችን የምንወድ ስለ ሆንን ከሞት ወደ ሕይወት እንደ ተሻገርን እናውቃለን፤ ወንድሙን የማይወድ በሞት ይኖራል።'),
  ('26b4cf94-6edc-5337-a408-78f79f5724c5', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 15, 15, 'ወንድሙን የሚጠላ ሁሉ ነፍሰ ገዳይ ነው፥ ነፍሰ ገዳይም የሆነ ሁሉ የዘላለም ሕይወት በእርሱ እንዳይኖር ታውቃላችሁ።'),
  ('644fdb11-f16c-5d82-a223-0a4aa99ce67c', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 16, 16, 'እርሱ ስለ እኛ ነፍሱን አሳልፎ ሰጥቶአልና በዚህ ፍቅርን አውቀናል፤ እኛም ስለ ወንድሞቻችን ነፍሳችንን አሳልፈን እንድንሰጥ ይገባናል።'),
  ('8fcace49-0906-5a14-a7db-9329586d22eb', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 17, 17, 'ነገር ግን የዚህ ዓለም ገንዘብ ያለው፥ ወንድሙም የሚያስፈልገው ሲያጣ አይቶ ያልራራለት ማንም ቢሆን፥ የእግዚአብሔር ፍቅር በእርሱ እንዴት ይኖራል?'),
  ('4612c7b2-bfa9-5007-a7bc-fe9488c096cb', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 18, 18, 'ልጆቼ ሆይ፥ በሥራና በእውነት እንጂ በቃልና በአንደበት አንዋደድ።'),
  ('ce23cd7e-c774-5faa-a223-d37ace2d5707', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 19, 19, 'ልባችንም በእኛ ላይ በሚፈርድበት ሁሉ፥ ከእውነት እንደ ሆንን በዚህ እናውቃለን በፊቱም ልባችንን እናሳርፋለን፥ እግዚአብሔር ከልባችን ይልቅ ታላቅ ነውና ሁሉንም ያውቃል።'),
  ('c00fa007-f245-56fa-a322-d250dd349cbf', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 20, 21, 'ወዳጆች ሆይ፥ ልባችንስ ባይፈርድብን በእግዚአብሔር ዘንድ ድፍረት አለን፥'),
  ('d07f29ef-87c9-5d29-a653-5108aac79ea0', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 21, 22, 'ትእዛዙንም የምንጠብቅና በፊቱ ደስ የሚያሰኘውን የምናደርግ ስለሆንን የምንለምነውን ሁሉ ከእርሱ እናገኛለን።'),
  ('2dd24705-5523-5ece-a5ad-fac4696a2db5', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 22, 23, 'ትእዛዚቱም ይህች ናት፥ በልጁ በኢየሱስ ክርስቶስ ስም እናምን ዘንድ፥ ትእዛዝንም እንደ ሰጠን እርስ በርሳችን እንዋደድ ዘንድ።'),
  ('b2e1c7dc-d592-5f99-a4ad-6e18874d9697', 'b14338fb-8621-592e-ac97-0cb4350f7e88', '8ede4d88-e7ad-56a3-a86f-67950c00d802', 23, 24, 'ትእዛዙንም የሚጠብቅ በእርሱ ይኖራል እርሱም ይኖርበታል፤ በዚህም በእኛ እንዲኖር ከሰጠን ከመንፈሱ እናውቃለን።'),
  ('5411b897-bd4a-57e0-a887-9ec36b505eb5', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 1, 1, 'ወዳጆች ሆይ፥ መንፈስን ሁሉ አትመኑ፥ ነገር ግን መናፍስት ከእግዚአብሔር ሆነው እንደ ሆነ መርምሩ፤ ብዙዎች ሐሰተኞች ነቢያት ወደ ዓለም ወጥተዋልና።'),
  ('d6d668f0-eab5-505a-a3bb-9e932570124b', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 2, 2, 'የእግዚአብሔርን መንፈስ በዚህ ታውቃላችሁ፤ ኢየሱስ ክርስቶስ በሥጋ እንደ መጣ የሚታመን መንፈስ ሁሉ ከእግዚአብሔር ነው፥'),
  ('72c41973-7743-58ea-a301-a1e824e51472', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 3, 3, 'ኢየሱስ ክርስቶስም በሥጋ እንደ መጣ የማይታመን መንፈስ ሁሉ ከእግዚአብሔር አይደለም፤ ይህም የክርስቶስ ተቃዋሚው መንፈስ ነው፤ ይህም እንዲመጣ ሰምታችኋል፥ አሁንም እንኳ በዓለም አለ።'),
  ('90e65db4-5b44-518d-ae27-f68f376bc3b6', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 4, 4, 'ልጆች ሆይ፥ እናንተ ከእግዚአብሔር ናችሁ አሸንፋችኋቸውማል፥ በዓለም ካለው ይልቅ በእናንተ ያለው ታላቅ ነውና።'),
  ('a8f37099-5ad0-5a65-ac5a-31434c3cd7c7', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 5, 5, 'እነርሱ ከዓለም ናቸው፤ ስለዚህ ከዓለም የሆነውን ይናገራሉ ዓለሙም ይሰማቸዋል።'),
  ('869b5dba-e68f-56a6-a536-6ec4b3d49f1d', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 6, 6, 'እኛ ከእግዚአብሔር ነን፤ እግዚአብሔርን የሚያውቅ ይሰማናል፤ ከእግዚአብሔር ያልሆነ አይሰማንም። የእውነትን መንፈስና የስሕተትን መንፈስ በዚህ እናውቃለን።'),
  ('ebb30b5d-f4a6-5fa1-a3fd-9bbeda7e25af', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 7, 7, 'ወዳጆች ሆይ፥ ፍቅር ከእግዚአብሔር ስለ ሆነ፥ የሚወደውም ሁሉ ከእግዚአብሔር ስለ ተወለደ እግዚአብሔርንም ስለሚያውቅ፥ እርስ በርሳችን እንዋደድ።'),
  ('c688dd2f-c307-5403-a5c6-06884ce8fedc', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 8, 8, 'ፍቅር የሌለው እግዚአብሔርን አያውቅም፥ እግዚአብሔር ፍቅር ነውና።'),
  ('09551375-a256-5f6f-a48f-499eeb9cb1a2', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 9, 9, 'በዚህ የእግዚአብሔር ፍቅር በእኛ ዘንድ ተገለጠ፥ በእርሱ በኩል በሕይወት እንኖር ዘንድ እግዚአብሔር አንድ ልጁን ወደ ዓለም ልኮታልና።'),
  ('2a3e7003-6df4-5c2f-ab70-a8ab1ca76c4c', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 10, 10, 'ፍቅርም እንደዚህ ነው። እግዚአብሔር እርሱ ራሱ እንደ ወደደን ስለ ኃጢአታችንም ማስተስሪያ ይሆን ዘንድ ልጁን እንደ ላከ እንጂ እኛ እግዚአብሔርን እንደ ወደድነው አይደለም።'),
  ('2f2ac41b-671a-55c8-a650-a1d3a75100ca', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 11, 11, 'ወዳጆች ሆይ፥ እግዚአብሔር እንዲህ አድርጎ ከወደደን እኛ ደግሞ እርስ በርሳችን ልንዋደድ ይገባናል።'),
  ('85230826-dc8b-5945-ae8b-37f523acbfae', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 12, 12, 'እግዚአብሔርን ማንም ከቶ አላየውም፤ እርስ በርሳችን ብንዋደድ እግዚአብሔር በእኛ ይኖራል ፍቅሩም በእኛ ፍጹም ሆኖአል።'),
  ('8fcc0b87-418e-58ce-a325-325806561364', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 13, 13, 'ከመንፈሱ ስለ ሰጠን፥ በእርሱ እንድንኖር እሱም በእኛ እንዲኖር በዚህ እናውቃለን።'),
  ('58092708-3711-54fc-ada7-854725a2fe3c', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 14, 14, 'እኛም አይተናል አባትም ልጁን የዓለም መድኃኒት ሊሆን እንደ ላከው እንመሰክራለን።'),
  ('0e9346c7-a1df-55bb-ac68-44f02b53adf9', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 15, 15, 'ኢየሱስ የእግዚአብሔር ልጅ እንደ ሆነ በሚታመን ሁሉ እግዚአብሔር በእርሱ ይኖራል እርሱም በእግዚአብሔር ይኖራል።'),
  ('99da0b6a-b09b-5f73-a0f6-e0d4982b5335', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 16, 16, 'እኛም እግዚአብሔር ለእኛ ያለውን ፍቅር አውቀናል አምነንማል። እግዚአብሔር ፍቅር ነው፥ በፍቅርም የሚኖር በእግዚአብሔር ይኖራል እግዚአብሔርም በእርሱ ይኖራል።'),
  ('6913d8f8-eb0c-56e0-af71-9a17db4d45c9', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 17, 17, 'በፍርድ ቀን ድፍረት ይሆንልን ዘንድ ፍቅር በዚህ ከእኛ ጋር ተፈጽሞአል፤ እርሱ እንዳለ እኛ ደግሞ እንዲሁ በዚህ ዓለም ነንና።'),
  ('878ec2ae-bb07-5da3-adfb-6a38ccb2df41', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 18, 18, 'ፍጹም ፍቅር ፍርሃትን አውጥቶ ይጥላል እንጂ በፍቅር ፍርሃት የለም፥ ፍርሃት ቅጣት አለውና፤ የሚፈራም ሰው ፍቅሩ ፍጹም አይደለም።'),
  ('25b55c65-a590-5c28-a255-9961d8814836', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 19, 19, 'እርሱ አስቀድሞ ወዶናልና እኛ እንወደዋለን።'),
  ('fcd5dbc2-f2c2-5084-a18d-f410868a313b', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 20, 20, 'ማንም፦ እግዚአብሔርን እወዳለሁ እያለ ወንድሙን ቢጠላ ሐሰተኛ ነው፤ ያየውን ወንድሙን የማይወድ ያላየውን እግዚአብሔርን ሊወደው እንዴት ይችላል?'),
  ('033cbed9-e86b-5942-aedd-514edc50d1ee', 'ead4ec9d-a714-5b92-a85e-60f1c08e1b0e', '9cee25b7-c36f-574a-a8c1-e55fd4a7584f', 21, 21, 'እግዚአብሔርንም የሚወድ ወንድሙን ደግሞ እንዲወድ ይህች ትእዛዝ ከእርሱ አለችን።'),
  ('29141dc8-d7a0-56ee-a937-14492d17d87f', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 1, 1, 'ክርስቶስ ነው ብሎ በኢየሱስ የሚያምን ሁሉ ከእግዚአብሔር ተወልዶአል፥ ወላጁንም የሚወድ ሁሉ ከእርሱ የተወለደውን ደግሞ ይወዳል።'),
  ('a4241785-e540-58c2-aa5e-98c05a119a1d', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 2, 2, 'እግዚአብሔርን ስንወድ ትእዛዛቱንም ስናደርግ የእግዚአብሔርን ልጆች እንድንወድ በዚህ እናውቃለን።'),
  ('c6ca2d72-a655-5a4a-a050-ec66e202385c', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 3, 3, 'ትእዛዛቱን ልንጠብቅ የእግዚአብሔር ፍቅር ይህ ነውና፤ ትእዛዛቱም ከባዶች አይደሉም።'),
  ('6d1cbc62-ef25-5edc-ad15-c823846582aa', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 4, 4, 'ከእግዚአብሔር የተወለደ ሁሉ ዓለምን ያሸንፋልና፤ ዓለምንም የሚያሸንፈው እምነታችን ነው።'),
  ('628745da-9050-5487-aab3-7515c9fa4bd4', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 5, 5, 'ኢየሱስም የእግዚአብሔር ልጅ እንደ ሆነ ከሚያምን በቀር ዓለምን የሚያሸንፍ ማን ነው?'),
  ('c993eb80-1485-5171-a015-0ed6962416c6', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 6, 6, 'በውኃና በደም የመጣ ይህ ነው እርሱም ኢየሱስ ክርስቶስ በውኃውና በደሙ እንጂ በውኃው ብቻ አይደለም።'),
  ('66bb9f80-9da0-5f1d-a38b-0c6c8e9bc3ea', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 7, 7, 'መንፈስም እውነት ነውና የሚመሰክረው መንፈስ ነው።'),
  ('767aaaac-84da-503c-a2f4-4b8d200d7dc9', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 8, 8, 'የሚመሰክሩት መንፈሱና ውኃው ደሙም ሦስት ናቸውና፤ ሦስቱም በአንድ ይስማማሉ።'),
  ('4db280b9-4cd4-50ad-ad0b-fd346db4ce55', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 9, 9, 'የሰውን ምስክር ብንቀበል የእግዚአብሔር ምስክር ከእርሱ ይልቅ ይበልጣል፤ ስለ ልጁ የመሰከረው የእግዚአብሔር ምስክር ይህ ነውና።'),
  ('da25a327-165b-5a9a-a45a-74e60bf80f63', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 10, 10, 'በእግዚአብሔር ልጅ የሚያምን በነፍሱ ምስክር አለው፤ በእግዚአብሔር የማያምን እግዚአብሔር ስለ ልጁ የመሰከረውን ምስክር ስላላመነ ሐሰተኛ አድርጎታል።'),
  ('9433fc7d-6e36-5e85-a9a6-29606212acc8', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 11, 11, 'እግዚአብሔርም የዘላለምን ሕይወት እንደ ሰጠን ይህም ሕይወት በልጁ እንዳለ ምስክሩ ይህ ነው።'),
  ('da02c2a0-451d-58f3-a810-a97ed80f6c74', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 12, 12, 'ልጁ ያለው ሕይወት አለው፤ የእግዚአብሔር ልጅ የሌለው ሕይወት የለውም።'),
  ('f9627b65-9d7b-5852-aa79-6e1a067d92a6', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 13, 13, 'የዘላለም ሕይወት እንዳላችሁ ታውቁ ዘንድ በእግዚአብሔር ልጅ ስም ለምታምኑ ይህን ጽፌላችኋለሁ።'),
  ('9afdaa01-1a0f-5897-ad53-72a567254239', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 14, 14, 'በእርሱ ዘንድ ያለን ድፍረት ይህ ነው፤ እንደ ፈቃዱ አንዳች ብንለምን ይሰማናል።'),
  ('2b17e420-da2a-59fb-a746-93a4c6ae0f0d', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 15, 15, 'የምንለምነውንም ሁሉ እንዲሰማልን ብናውቅ ከእርሱ የለመነውን ልመና እንደ ተቀበልን እናውቃለን።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('a80b67be-26f3-5c90-abe0-853d39f978ee', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 16, 16, 'ማንም ወንድሙን ሞት የማይገባውን ኃጢአት ሲያደርግ ቢያየው ይለምን፥ ሞትም የማይገባውን ኃጢአት ላደረጉት ሕይወት ይሰጥለታል። ሞት የሚገባው ኃጢአት አለ፤ ስለዚያ እንዲጠይቅ አልልም።'),
  ('ed3e01e9-e596-52ac-ab78-a9353671a2c3', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 17, 17, 'ዓመፃ ሁሉ ኃጢአት ነው፥ ሞትም የማይገባው ኃጢአት አለ።'),
  ('8cdb6ad9-387c-523c-adb3-01bd78311b0e', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 18, 18, 'ከእግዚአብሔር የተወለደ ሁሉ ኃጢአትን እንዳያደርግ፥ ነገር ግን ከእግዚአብሔር የተወለደው ራሱን እንዲጠብቅ ክፉውም እንዳይነካው እናውቃለን።'),
  ('2c46f5f4-9390-5adf-adb2-69a2da747c3c', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 19, 19, 'ከእግዚአብሔር እንደ ሆንን ዓለምም በሞላው በክፉው እንደ ተያዘ እናውቃለን።'),
  ('1fd12ab1-3890-501b-ac0e-eb49c6b02581', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 20, 20, 'የእግዚአብሔርም ልጅ እንደ መጣ፥ እውነተኛም የሆነውን እናውቅ ዘንድ ልቡናን እንደ ሰጠን እናውቃለን፤ እውነተኛም በሆነው በእርሱ አለን፥ እርሱም ልጁ ኢየሱስ ክርስቶስ ነው። እርሱ እውነተኛ አምላክና የዘላለም ሕይወት ነው።'),
  ('756fa86d-d1cc-5606-a45e-80ed6df455c5', 'd0a965f0-066f-56fa-a59c-5fa362b6e3c5', 'db88d7ae-3d1d-5ec2-a0f7-ed49274d393c', 21, 21, 'ልጆች ሆይ፥ ከጣዖታት ራሳችሁን ጠብቁ።'),
  ('a27d9afe-48ae-56e9-aec6-a96d0a66ee98', '15fe7ce3-1745-5d6a-a72b-7f321dfe8ced', '6d893962-c168-5576-ad11-ec3a66dfa898', 1, 1, 'በእኛ ስለሚኖርና ከእኛ ጋር ለዘላለም ስለሚሆን እውነት፥ እኔ ሽማግሌው በእውነት ለምወዳቸውና እኔ ብቻ ሳልሆን እውነትን የሚያውቁ ሁሉ ደግሞ ለሚወዱአቸው ለተመረጠች እመቤትና ለልጆችዋ፤'),
  ('4edcb48b-5a13-58d8-a02d-5f3318a4cd16', '15fe7ce3-1745-5d6a-a72b-7f321dfe8ced', '6d893962-c168-5576-ad11-ec3a66dfa898', 2, 3, 'ከእግዚአብሔር አብና ከአብ ልጅ ከኢየሱስ ክርስቶስ ጸጋና ምሕረት ሰላምም በእውነትና በፍቅር ከእኛ ጋር ይሆናሉ።'),
  ('37d65630-6193-51b6-aee2-f62f1351883b', '15fe7ce3-1745-5d6a-a72b-7f321dfe8ced', '4ffc402a-e3d8-5e84-a765-d9307154bbdc', 1, 4, 'ትእዛዝን ከአብ እንደ ተቀበልን ከልጆችሽ በእውነት የሚሄዱ አንዳንዶችን ስለ አገኘኋቸው እጅግ ደስ ብሎኛል።'),
  ('b66a925a-d8ac-5a84-ae0d-2833d18fe0bb', '15fe7ce3-1745-5d6a-a72b-7f321dfe8ced', '4ffc402a-e3d8-5e84-a765-d9307154bbdc', 2, 5, 'አሁንም እመቤት ሆይ! እርስ በርሳችን እንድንዋደድ እለምንሻለሁ፤ ይህች ከመጀመሪያ በእኛ ዘንድ የነበረች ትእዛዝ ናት እንጂ አዲስ ትእዛዝን እንደምጽፍልሽ አይደለም።'),
  ('ccbac8d7-84b4-520a-a9b0-9ab451c59b71', '15fe7ce3-1745-5d6a-a72b-7f321dfe8ced', '4ffc402a-e3d8-5e84-a765-d9307154bbdc', 3, 6, 'እንደ ትእዛዛቱም እንሄድ ዘንድ ይህ ፍቅር ነው፤ ከመጀመሪያ እንደ ሰማችሁ፥ በእርስዋ ትሄዱ ዘንድ ትእዛዙ ይህች ናት።'),
  ('9eaa21be-c204-5b3c-a8d4-52bd439bee93', '15fe7ce3-1745-5d6a-a72b-7f321dfe8ced', '4ffc402a-e3d8-5e84-a765-d9307154bbdc', 4, 7, 'ብዙ አሳቾች ወደ ዓለም ገብተዋልና፤ እነርሱም ኢየሱስ ክርስቶስ በሥጋ እንደ መጣ የማያምኑ ናቸው፤ ይህ አሳቹና የክርስቶስ ተቃዋሚው ነው።'),
  ('29ea6b5c-6131-52ab-aa47-07383c04622e', '15fe7ce3-1745-5d6a-a72b-7f321dfe8ced', '4ffc402a-e3d8-5e84-a765-d9307154bbdc', 5, 8, 'ሙሉ ደመወዝን እንድትቀበሉ እንጂ የሠራችሁትን እንዳታጠፉ ለራሳችሁ ተጠንቀቁ።'),
  ('a88f4854-4016-51f9-a629-c22d97787dcd', '15fe7ce3-1745-5d6a-a72b-7f321dfe8ced', '4ffc402a-e3d8-5e84-a765-d9307154bbdc', 6, 9, 'ለሚወጣ ሁሉ በክርስቶስም ትምህርት ለማይኖር ሰው አምላክ የለውም፤ በክርስቶስ ትምህርት ለሚኖር አብና ወልድ አሉት።'),
  ('ccedb793-60bf-56da-abfc-198e5a16aef2', '15fe7ce3-1745-5d6a-a72b-7f321dfe8ced', '4ffc402a-e3d8-5e84-a765-d9307154bbdc', 7, 10, 'ማንም ወደ እናንተ ቢመጣ ይህንም ትምህርት ባያመጣ በቤታችሁ አትቀበሉት፤ ሰላምም አትበሉት፤'),
  ('f7672608-19e2-5b31-a178-f3cf9bd89847', '15fe7ce3-1745-5d6a-a72b-7f321dfe8ced', '4ffc402a-e3d8-5e84-a765-d9307154bbdc', 8, 11, 'ሰላም የሚለው ሰው በክፉ ሥራው ይካፈላልና።'),
  ('6fd82070-71af-588a-a46e-a7f98a406402', '15fe7ce3-1745-5d6a-a72b-7f321dfe8ced', 'bd4e0ff2-c9aa-5f3e-afdd-87410f24caf1', 1, 12, 'እንድጽፍላችሁ የምፈልገው ብዙ ነገር ሳለኝ በወረቀትና በቀለም ልጽፈው አልወድም፤ ዳሩ ግን ደስታችሁ ፍጹም እንዲሆን ወደ እናንተ ልመጣ አፍ ለአፍም ልናገራችሁ ተስፋ አደርጋለሁ።'),
  ('4a4a1216-156c-5443-a150-3f294f5ceb43', '15fe7ce3-1745-5d6a-a72b-7f321dfe8ced', 'bd4e0ff2-c9aa-5f3e-afdd-87410f24caf1', 2, 13, 'የተመረጠችው የእኅትሽ ልጆች ሰላምታ ያቀርቡልሻል።'),
  ('f6d244c5-6889-5482-ae39-e69fcb8199a1', 'ff83e5a3-46d2-571b-a75d-5605a45b359e', '4c702541-2b4c-51ed-a747-2b85ebf690a6', 1, 1, 'ሽማግሌው በእውነት እኔ ለምወደው ለተወደደው ለጋይዮስ።'),
  ('86a02c2d-12ad-5887-a1c8-54eb2ce8db5a', 'ff83e5a3-46d2-571b-a75d-5605a45b359e', '4c702541-2b4c-51ed-a747-2b85ebf690a6', 2, 2, 'ወዳጅ ሆይ! ነፍስህ እንደሚከናወን፥ በነገር ሁሉ እንዲከናወንልህና ጤና እንዲኖርህ እጸልያለሁ።'),
  ('a86d3525-4512-5f66-aca8-87938898e84a', 'ff83e5a3-46d2-571b-a75d-5605a45b359e', '4c702541-2b4c-51ed-a747-2b85ebf690a6', 3, 3, 'ወንድሞች መጥተው አንተ በእውነት እንደምትሄድ ስለ እውነትህ ሲመሰክሩ እጅግ ደስ ብሎኛልና።'),
  ('1c9e748b-b761-5918-ab7a-668b9a7e0ece', 'ff83e5a3-46d2-571b-a75d-5605a45b359e', '4c702541-2b4c-51ed-a747-2b85ebf690a6', 4, 4, 'ልጆቼ በእውነት እንዲሄዱ ከመስማት ይልቅ የሚበልጥ ደስታ የለኝም።'),
  ('a3b6acf3-34d7-52cd-aac5-ed2e77faa4f0', 'ff83e5a3-46d2-571b-a75d-5605a45b359e', 'd697f7c4-3602-54c3-acec-27ecf3d42fea', 1, 5, 'ወዳጅ ሆይ! ምንም እንግዶች ቢሆኑ፥ ለወንድሞች በምታደርገው ሁሉ የታመነ ሥራ ትሠራለህ፤'),
  ('6c2c9563-d418-59b4-ade8-cff2e485f0f7', 'ff83e5a3-46d2-571b-a75d-5605a45b359e', 'd697f7c4-3602-54c3-acec-27ecf3d42fea', 2, 6, 'እነርሱም በማኅበር ፊት ስለ ፍቅርህ መስክረዋል፤ ለእግዚአብሔር እንደሚገባ አድርገህ በጉዞአቸው ብትረዳ መልካም ታደርጋለህ፤'),
  ('efb731cf-4d00-57bc-ac3d-86594e179523', 'ff83e5a3-46d2-571b-a75d-5605a45b359e', 'd697f7c4-3602-54c3-acec-27ecf3d42fea', 3, 7, 'ከአሕዛብ አንዳች ሳይቀበሉ ስለ ስሙ ወጥተዋልና።'),
  ('73a4d9f0-493f-5a8e-a202-c4e9ea2b60bf', 'ff83e5a3-46d2-571b-a75d-5605a45b359e', 'd697f7c4-3602-54c3-acec-27ecf3d42fea', 4, 8, 'እንግዲህ ከእውነት ጋር አብረን እንድንሠራ እኛ እንዲህ ያሉትን በእንግድነት ልንቀበል ይገባናል።'),
  ('97540dfc-c904-57f4-a13d-5d1d5e3384c6', 'ff83e5a3-46d2-571b-a75d-5605a45b359e', '0c7cbb14-39cf-5c72-ac9b-d68ba06a6da9', 1, 9, 'ወደ ቤተ ክርስቲያን ጻፍሁ፤ ዳሩ ግን ዋናቸው ሊሆን የሚወድ ዲዮጥራፊስ አይቀበለንም።'),
  ('370c0322-05f0-5014-aeb4-d73516551589', 'ff83e5a3-46d2-571b-a75d-5605a45b359e', '0c7cbb14-39cf-5c72-ac9b-d68ba06a6da9', 2, 10, 'ስለዚህ እኔ ብመጣ፥ በእኛ ላይ በክፉ ቃል እየለፈለፈ የሚያደርገውን ሥራውን አሳስባለሁ፤ ይህም ሳይበቃው እርሱ ራሱ ወንድሞችን አይቀበልም፤ ሊቀበሉአቸውም የሚወዱትን ከልክሎ ከቤተ ክርስቲያን ያወጣቸዋል።'),
  ('a4d88408-beb7-5370-a1a0-3336c1d3dfe8', 'ff83e5a3-46d2-571b-a75d-5605a45b359e', '0c7cbb14-39cf-5c72-ac9b-d68ba06a6da9', 3, 11, 'ወዳጅ ሆይ! በጎ የሆነውን እንጂ ክፉን አትምሰል። በጎ የሚያደርግ ከእግዚአብሔር ነው፤ ክፉን የሚያደርግ ግን እግዚአብሔርን አላየውም።'),
  ('a31e4a11-93fb-53da-aea3-f30a7914ca4f', 'ff83e5a3-46d2-571b-a75d-5605a45b359e', '0c7cbb14-39cf-5c72-ac9b-d68ba06a6da9', 4, 12, 'ለድሜጥሮስ ሁሉ ይመሰክሩለታል፤ እውነት ራስዋም ትመሰክርለታለች፤ እኛም ደግሞ እንመሰክርለታለን፤ ምስክርነታችንም እውነት እንደ ሆነ ታውቃላችሁ።'),
  ('bf815684-3269-542f-ae3e-10e2565838b5', 'ff83e5a3-46d2-571b-a75d-5605a45b359e', '8e08d17a-dc3f-54b9-a951-c7ae747a4b95', 1, 13, 'ልጽፍልህ የምፈልገው ብዙ ነገር ነበረኝ፤ ዳሩ ግን በቀለምና በብርዕ ልጽፍልህ አልወድም፤'),
  ('ba2ed155-3c27-5f91-a164-9c3b7dcacf9f', 'ff83e5a3-46d2-571b-a75d-5605a45b359e', '8e08d17a-dc3f-54b9-a951-c7ae747a4b95', 2, 14, 'ነገር ግን ወዲያው ላይህ ተስፋ አደርጋለሁ፤ አፍ ለአፍም እንነጋገራለን።'),
  ('9eb51ece-8970-53cd-ad29-60520d82a1b4', 'ff83e5a3-46d2-571b-a75d-5605a45b359e', '8e08d17a-dc3f-54b9-a951-c7ae747a4b95', 3, 15, 'ሰላም ለአንተ ይሁን። ወዳጆች ሰላምታ ያቀርቡልሃል። ወዳጆችን በየስማቸው እየጠራህ ሰላምታ አቅርብልኝ።'),
  ('85b9e14f-2112-56ec-a00d-2ec0e1565f3d', '3b85e86f-88d7-5d92-af25-61ad5e985995', '7c186323-3c0b-5682-a459-1b356c780cad', 1, 1, 'የእግዚአብሔርና የጌታ የኢየሱስ ክርስቶስ ባሪያ ያዕቆብ ለተበተኑ ለዐሥራ ሁለቱ ወገኖች፤ ሰላም ለእናንተ ይሁን።'),
  ('6ecbde9f-7e65-514e-afd8-536f8b97cd82', '3b85e86f-88d7-5d92-af25-61ad5e985995', 'e134c6ee-ebc2-5b05-a440-dfb559df1fc1', 1, 2, 'ወንድሞቼ ሆይ! የእምነታችሁ መፈተን ትዕግሥትን እንዲያደርግላችሁ አውቃችሁ፥ ልዩ ልዩ ፈተና ሲደርስባችሁ እንደ ሙሉ ደስታ ቍጠሩት፤'),
  ('0bf8b89c-2620-56b5-aa73-7557ac570512', '3b85e86f-88d7-5d92-af25-61ad5e985995', 'e134c6ee-ebc2-5b05-a440-dfb559df1fc1', 2, 4, 'ትዕግሥትም ምንም የሚጎድላችሁ ሳይኖር ፍጹማንና ምሉዓን ትሆኑ ዘንድ ሥራውን ይፈጽም።'),
  ('20c295d0-a49a-5914-abfe-b20ede35fc31', '3b85e86f-88d7-5d92-af25-61ad5e985995', 'e134c6ee-ebc2-5b05-a440-dfb559df1fc1', 3, 5, 'ከእናንተ ግን ማንም ጥበብ ቢጎድለው፥ ሳይነቅፍ በልግስና ለሁሉ የሚሰጠውን እግዚአብሔርን ይለምን፤ ለእርሱም ይሰጠዋል።'),
  ('e7d95caa-3a63-59d8-a45a-b20d570732b8', '3b85e86f-88d7-5d92-af25-61ad5e985995', 'e134c6ee-ebc2-5b05-a440-dfb559df1fc1', 4, 6, 'ነገር ግን በምንም ሳይጠራጠር በእምነት ይለምን፤ የሚጠራጠር ሰው በነፋስ የተገፋና የተነቃነቀ የባሕርን ማዕበል ይመስላልና።'),
  ('ee22df6a-4327-5e4a-a9b8-d66e39e35948', '3b85e86f-88d7-5d92-af25-61ad5e985995', 'e134c6ee-ebc2-5b05-a440-dfb559df1fc1', 5, 7, 'ሁለት አሳብ ላለው በመንገዱም ሁሉ ለሚወላውል ለዚያ ሰው ከጌታ ዘንድ አንዳች እንዲያገኝ አይምሰለው።'),
  ('d2f5c592-b158-5993-a7e8-ed473c17452e', '3b85e86f-88d7-5d92-af25-61ad5e985995', 'b3abdc07-5ede-516e-a523-941da33fabf4', 1, 9, 'የተዋረደው ወንድም ግን በከፍታው፥ ባለ ጠጋም በውርደቱ ይመካ፤ እንደ ሣር አበባ ያልፋልና።'),
  ('f645cff4-c845-5c47-aa9a-48e5538879c0', '3b85e86f-88d7-5d92-af25-61ad5e985995', 'b3abdc07-5ede-516e-a523-941da33fabf4', 2, 11, 'ፀሐይ ከትኵሳት ጋር ይወጣልና፥ ሣርንም ያጠወልጋልና፥ አበባውም ይረግፋልና፥ የመልኩም ውበት ይጠፋልና፤ እንዲሁ ደግሞ ባለ ጠጋው በመንገዱ ይዝላል።'),
  ('3f2ff867-9980-5879-a080-e925801ecbe4', '3b85e86f-88d7-5d92-af25-61ad5e985995', '90d9efd0-b095-5cfa-afbc-67999266a9b9', 1, 12, 'በፈተና የሚጸና ሰው የተባረከ ነው፤ ከተፈተነ በኋላ ለሚወዱት ተስፋ ስለ እርሱ የሰጣቸውን የሕይወትን አክሊል ይቀበላልና።'),
  ('17285cf8-4837-55ec-a422-261750334470', '3b85e86f-88d7-5d92-af25-61ad5e985995', '90d9efd0-b095-5cfa-afbc-67999266a9b9', 2, 13, 'ማንም ሲፈተን “በእግዚአብሔር እፈተናለሁ፤” አይበል፤ እግዚአብሔር በክፉ አይፈተንምና፤ እርሱ ራሱስ ማንንም አይፈትንም።'),
  ('0e4ccdd6-7351-5513-afcd-af6c97473801', '3b85e86f-88d7-5d92-af25-61ad5e985995', '90d9efd0-b095-5cfa-afbc-67999266a9b9', 3, 14, 'ነገር ግን እያንዳንዱ በራሱ ምኞት ሲሳብና ሲታለል ይፈተናል።'),
  ('50604265-6a6d-5ce0-ad57-e043d5d4c3f7', '3b85e86f-88d7-5d92-af25-61ad5e985995', '90d9efd0-b095-5cfa-afbc-67999266a9b9', 4, 15, 'ከዚህ በኋላ ምኞት ፀንሳ ኀጢአትን ትወልዳለች፤ ኀጢአትም ካደገች በኋላ ሞትን ትወልዳለች።'),
  ('8c9b7b54-ee06-57a1-a092-00ec209861a3', '3b85e86f-88d7-5d92-af25-61ad5e985995', '90d9efd0-b095-5cfa-afbc-67999266a9b9', 5, 16, 'የተወደዳችሁ ወንድሞቼ ሆይ! አትሳቱ።'),
  ('f1efe03a-d098-5cff-a9be-c69804a4e6e3', '3b85e86f-88d7-5d92-af25-61ad5e985995', '90d9efd0-b095-5cfa-afbc-67999266a9b9', 6, 17, 'በጎ ስጦታ ሁሉ ፍጹምም በረከት ሁሉ ከላይ ናቸው፤ መለወጥም በእርሱ ዘንድ ከሌለ በመዞርም የተደረገ ጥላ በእርሱ ዘንድ ከሌለ ከብርሃናት አባት ይወርዳሉ።'),
  ('62af9b80-df61-5fd7-aa2e-a6164e3e6fa0', '3b85e86f-88d7-5d92-af25-61ad5e985995', '90d9efd0-b095-5cfa-afbc-67999266a9b9', 7, 18, 'ለፍጥረቱ የበኵራት ዐይነት እንድንሆን በእውነት ቃል አስቦ ወለደን።'),
  ('6cf1f45c-768f-5e78-a34c-8e612db2f859', '3b85e86f-88d7-5d92-af25-61ad5e985995', '5896e042-97ed-5fd8-a80f-b10b5ed58367', 1, 19, 'ስለዚህ የተወደዳችሁ ወንድሞቼ ሆይ! ሰው ሁሉ ለመስማት የፈጠነ ለመናገርም የዘገየ ለቍጣም የዘገየ ይሁን፤'),
  ('6f1160cd-4ddf-5c88-abd6-803809c40b08', '3b85e86f-88d7-5d92-af25-61ad5e985995', '5896e042-97ed-5fd8-a80f-b10b5ed58367', 2, 20, 'የሰው ቍጣ የእግዚአብሔርን ጽድቅ አይሠራምና።'),
  ('ec3c54ba-4ea3-5a66-a383-599a90f1ca18', '3b85e86f-88d7-5d92-af25-61ad5e985995', '5896e042-97ed-5fd8-a80f-b10b5ed58367', 3, 21, 'ስለዚህ ርኵሰትን ሁሉ የክፋትንም ትርፍ አስወግዳችሁ፥ ነፍሳችሁን ማዳን የሚችለውን በውስጣችሁም የተተከለውን ቃል በየዋህነት ተቀበሉ።'),
  ('51d443f6-582f-5782-adc7-6f7107cc3c68', '3b85e86f-88d7-5d92-af25-61ad5e985995', '5896e042-97ed-5fd8-a80f-b10b5ed58367', 4, 22, 'ቃሉን የምታደርጉ ሁኑ እንጂ ራሳችሁን እያሳታችሁ የምትሰሙ ብቻ አትሁኑ።'),
  ('96c8572c-fec0-5f12-abda-4573a856b1f0', '3b85e86f-88d7-5d92-af25-61ad5e985995', '5896e042-97ed-5fd8-a80f-b10b5ed58367', 5, 23, 'ቃሉን የሚሰማ የማያደርገውም ቢኖር የተፈጥሮ ፊቱን በመስተዋት የሚያይን ሰው ይመስላል፤'),
  ('5a42f000-f877-54de-a154-95ea0fd1ef3f', '3b85e86f-88d7-5d92-af25-61ad5e985995', '5896e042-97ed-5fd8-a80f-b10b5ed58367', 6, 24, 'ራሱን አይቶ ይሄዳልና፤ ወዲያውም እንደ ምን እንደ ሆነ ይረሳል።'),
  ('d28e5ad2-bfef-5585-a776-7e6911ee0931', '3b85e86f-88d7-5d92-af25-61ad5e985995', '5896e042-97ed-5fd8-a80f-b10b5ed58367', 7, 25, 'ነገር ግን ነጻ የሚያወጣውን ፍጹሙን ሕግ ተመልክቶ የሚጸናበት፥ ሥራንም የሚሠራ እንጂ ሰምቶ የሚረሳ ያልሆነው፥ በሥራው የተባረከ ይሆናል።'),
  ('3cdab8ef-f5b9-53c5-a94d-0bd75c277f1e', '3b85e86f-88d7-5d92-af25-61ad5e985995', '5896e042-97ed-5fd8-a80f-b10b5ed58367', 8, 26, 'አንደበቱን ሳይገታ ልቡን እያሳተ እግዚአብሔርን የሚያመልክ የሚመስለው ማንም ቢኖር የእርሱ አምልኮ ከንቱ ነው።'),
  ('2465aab1-af79-5379-a627-818af87d59bd', '3b85e86f-88d7-5d92-af25-61ad5e985995', '5896e042-97ed-5fd8-a80f-b10b5ed58367', 9, 27, 'ንጹሕ የሆነ ነውርም የሌለበት አምልኮ በእግዚአብሔር አብ ዘንድ ይህ ነው፤ ወላጆች የሌላቸውን ልጆች ባልቴቶችንም በመከራቸው መጠየቅ፥ በዓለምም ከሚገኝ እድፍ ሰውነቱን መጠበቅ ነው።'),
  ('242a304d-3c25-5002-aa9c-bbd957af0557', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', '4e0b5bb6-b1c8-5bce-aeb9-956ec0b6a591', 1, 1, 'ወንድሞቼ ሆይ! በክብር ጌታ በጌታችን በኢየሱስ ክርስቶስ ያለውን እምነት ለሰው ፊት በማድላት አትያዙ።'),
  ('929e2be5-08b2-58c7-aae6-1d3b6d568a6d', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', '4e0b5bb6-b1c8-5bce-aeb9-956ec0b6a591', 2, 2, 'የወርቅ ቀለበት ያደረገና የጌጥ ልብስ የለበሰ ሰው ወደ ጉባኤአችሁ ቢገባ፥ እድፍ ልብስም የለበሰ ድኻ ሰው ደግሞ ቢገባ፥'),
  ('e7a6d130-966c-5eaf-acc7-c46ae3aee3c2', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', '4e0b5bb6-b1c8-5bce-aeb9-956ec0b6a591', 3, 3, 'የጌጥ ልብስም የለበሰውን ተመልክታችሁ “አንተስ በዚህ በመልካም ስፍራ ተቀመጥ፤” ብትሉት፥ ድኻውንም “አንተስ ወደዚያ ቁም” ወይም “ከእግሬ መረገጫ በታች ተቀመጥ፤” ብትሉት፥ ራሳችሁን መለያየታችሁ አይደለምን?'),
  ('8ecade5a-54c5-543f-a37c-b6335f2a6671', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', '4e0b5bb6-b1c8-5bce-aeb9-956ec0b6a591', 4, 4, 'ክፉ አሳብ ያላቸውም ዳኞች መሆናችሁ አይደለምን?'),
  ('c44e378e-ee41-513b-af3d-801b1f313c85', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', '4e0b5bb6-b1c8-5bce-aeb9-956ec0b6a591', 5, 5, 'የተወደዳችሁ ወንድሞቼ ሆይ! ስሙ፤ እግዚአብሔር በእምነት ባለ ጠጎች እንዲሆኑ ለሚወዱትም ተስፋ ስለ እርሱ የሰጣቸውን መንግሥት እንዲወርሱ የዚህን ዓለም ድኾች አልመረጠምን?'),
  ('a0847f14-3d7a-53c4-aaa9-04b4eaa9067b', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', '4e0b5bb6-b1c8-5bce-aeb9-956ec0b6a591', 6, 6, 'እናንተ ግን ድኾችን አዋረዳችሁ። ባለ ጠጎቹ የሚያስጨንቁአችሁ አይደሉምን? ወደ ፍርድ ቤትም የሚጎትቱአችሁ እነርሱ አይደሉምን?'),
  ('32781a5e-c1b2-5559-a5a3-4d9ce39ec8d9', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', '4e0b5bb6-b1c8-5bce-aeb9-956ec0b6a591', 7, 7, 'የተጠራችሁበትን መልካሙን ስም የሚሰድቡ እነርሱ አይደሉምን?'),
  ('4ebafa05-bdc8-5c0e-af8e-4691371f2f2c', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', '4e0b5bb6-b1c8-5bce-aeb9-956ec0b6a591', 8, 8, 'ነገር ግን መጽሐፍ “ባልንጀራህን እንደ ራስህ ውደድ፤” እንደሚል የንጉሥን ሕግ ብትፈጽሙ መልካም ታደርጋላችሁ፤'),
  ('9ecfd18c-b805-5d80-ae00-ac3461ba6e2f', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', '4e0b5bb6-b1c8-5bce-aeb9-956ec0b6a591', 9, 9, 'ለሰው ፊት ግን ብታደሉ ኀጢአትን ትሠራላችሁ፤ ሕግም እንደ ተላላፊዎች ይወቅሳችኋል።'),
  ('f10c873a-c1a1-5020-a892-6fdf483005b9', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', '4e0b5bb6-b1c8-5bce-aeb9-956ec0b6a591', 10, 10, 'ሕግን ሁሉ የሚጠብቅ፥ ነገር ግን በአንዱ የሚሰናከል ማንም ቢኖር በሁሉ በደለኛ ይሆናል፤ “አታመንዝር” ያለው ደግሞ “አትግደል” ብሎአልና፤'),
  ('566a1d04-0084-5cf6-a804-ad1ae23db754', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', '4e0b5bb6-b1c8-5bce-aeb9-956ec0b6a591', 11, 11, 'ባታመነዝርም፥ ነገር ግን ብትገድል፥ ሕግን ተላላፊ ሆነሃል።'),
  ('88e3fdca-e95f-54eb-a8a5-7d29df95e774', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', '4e0b5bb6-b1c8-5bce-aeb9-956ec0b6a591', 12, 12, 'በነጻነት ሕግ ፍርድን ይቀበሉ ዘንድ እንዳላቸው ሰዎች እንዲህ ተናገሩ፤ እንዲህም አድርጉ።'),
  ('b313962b-c513-5c7e-abbd-8d5aa8f9e6c2', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', '4e0b5bb6-b1c8-5bce-aeb9-956ec0b6a591', 13, 13, 'ምሕረትን ለማያደርግ ምሕረት የሌለበት ፍርድ ይሆናልና፤ ምሕረትም በፍርድ ላይ ይመካል።'),
  ('d441828d-f057-58a9-a4b2-34cbcd319991', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', 'c22f7f35-9825-5a92-a399-05ae338ce640', 1, 14, 'ወንድሞቼ ሆይ! እምነት አለኝ የሚል ሥራ ግን የሌለው ሰው ቢኖር ምን ይጠቅመዋል? እምነቱስ ሊያድነው ይችላልን?'),
  ('6e822ee8-9c79-5853-a465-678b1ce9f231', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', 'c22f7f35-9825-5a92-a399-05ae338ce640', 2, 15, 'ወንድም ወይም እኅት ራቁታቸውን ቢሆኑ የዕለት ምግብንም ቢያጡ፥'),
  ('127e69aa-f4a8-52cb-a1c6-5dba87c221fa', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', 'c22f7f35-9825-5a92-a399-05ae338ce640', 3, 16, 'ከእናንተ አንዱም “በደኅና ሂዱ፤ እሳት ሙቁ፤ ጥገቡም፤” ቢላቸው ለሰውነት ግን የሚያስፈልጉትን ባትሰጡአቸው ምን ይጠቅማቸዋል?'),
  ('b306c97e-5edd-513b-aabf-43034b59f29d', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', 'c22f7f35-9825-5a92-a399-05ae338ce640', 4, 17, 'እንደዚሁም ሥራ የሌለው እምነት ቢኖር በራሱ የሞተ ነው።'),
  ('3dffcc0c-a080-5077-a160-4cf39c0eea15', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', 'c22f7f35-9825-5a92-a399-05ae338ce640', 5, 18, 'ነገር ግን አንድ ሰው “አንተ እምነት አለህ እኔም ሥራ አለኝ፤ እምነትህን ከሥራህ ለይተህ አሳየኝ፤ እኔም እምነቴን በሥራዬ አሳይሃለሁ፤” ይላል።'),
  ('195294e5-d351-514f-a749-e4918e548f1c', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', 'c22f7f35-9825-5a92-a399-05ae338ce640', 6, 19, 'እግዚአብሔር አንድ እንደ ሆነ አንተ ታምናለህ፤ መልካም ታደርጋለህ፤ አጋንንት ደግሞ ያምናሉ፤ ይንቀጠቀጡማል።'),
  ('3da509b5-32e4-50f7-a392-d0312207392b', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', 'c22f7f35-9825-5a92-a399-05ae338ce640', 7, 20, 'አንተ ከንቱ ሰው! እምነት ከሥራ ተለይቶ የሞተ መሆኑን ልታውቅ ትወዳለህን?'),
  ('df4cd413-c2ec-5cd7-a8c7-21b225278cb5', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', 'c22f7f35-9825-5a92-a399-05ae338ce640', 8, 21, 'አባታችን አብርሃም ልጁን ይስሐቅን በመሠዊያው ባቀረበ ጊዜ በሥራ የጸደቀ አልነበረምን?'),
  ('f4ae854d-03a7-58ed-af71-3638aa8682f8', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', 'c22f7f35-9825-5a92-a399-05ae338ce640', 9, 22, 'እምነት ከሥራው ጋር አብሮ ያደርግ እንደ ነበረ፥ በሥራም እምነት እንደ ተፈጸመ ትመለከታለህን?'),
  ('51ce2b07-54fb-5d55-ac26-0f343d11b1bb', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', 'c22f7f35-9825-5a92-a399-05ae338ce640', 10, 23, 'መጽሐፍም “አብርሃምም እግዚአብሔርን አመነ፤ ጽድቅም ሆኖ ተቈጠረለት፤” ያለው ተፈጸመ፤ የእግዚአብሔርም ወዳጅ ተባለ።'),
  ('eb031a30-844d-50e5-a39f-1081089b8c85', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', 'c22f7f35-9825-5a92-a399-05ae338ce640', 11, 24, 'ሰው በእምነት ብቻ ሳይሆን በሥራ እንዲጸድቅ ታያላችሁ።'),
  ('44dd4a60-50f4-5b60-a0dc-8d6a1ee74f1d', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', 'c22f7f35-9825-5a92-a399-05ae338ce640', 12, 25, 'እንደዚሁም ጋለሞታይቱ ረዓብ ደግሞ መልእክተኞቹን ተቀብላ በሌላ መንገድ በሰደደቻቸው ጊዜ በሥራ አልጸደቀችምን?'),
  ('6e2b09a4-ce8a-5ed4-a8c9-b177541363a4', '6ae2a6c9-e200-5481-ac61-139f4b3e7af9', 'c22f7f35-9825-5a92-a399-05ae338ce640', 13, 26, 'ከነፍስ የተለየ ሥጋ የሞተ እንደ ሆነ እንዲሁ ደግሞ ከሥራ የተለየ እምነት የሞተ ነው።'),
  ('43773b2f-cbd3-57cb-a1e1-86e9f487b691', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'ccb664ce-5ff4-5389-ab3a-dbe07ce1ea3d', 1, 1, 'ወንድሞቼ ሆይ! ከእናንተ ብዙዎቹ አስተማሪዎች አይሁኑ፤ የባሰውን ፍርድ እንድንቀበል ታውቃላችሁና።'),
  ('c606a1bc-8e77-5342-aebd-ece06e45ab8a', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'ccb664ce-5ff4-5389-ab3a-dbe07ce1ea3d', 2, 2, 'ሁላችን በብዙ ነገር እንሰናከላለንና፤ በቃል የማይሰናከል ማንም ቢኖር እርሱ ሥጋውን ሁሉ ደግሞ ሊገታ የሚችል ፍጹም ሰው ነው።'),
  ('00c62c68-c899-535a-aefc-c7bd22094f14', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'ccb664ce-5ff4-5389-ab3a-dbe07ce1ea3d', 3, 3, 'እነሆ ፈረሶች ይታዘዙልን ዘንድ ልጓም በአፋቸው ውስጥ እናገባለን፤ ሥጋቸውንም ሁሉ እንመራለን።'),
  ('29429286-c6da-5d66-a195-1e61f9aeaa68', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'ccb664ce-5ff4-5389-ab3a-dbe07ce1ea3d', 4, 4, 'እነሆ መርከቦች ደግሞ ይህን ያህል ታላቅ ቢሆኑ በዐውሎ ነፋስም ቢነዱ፥ የመሪ ፈቃድ ወደሚወደው ስፍራ እጅግ ታናሽ በሆነ መቅዘፊያ ይመራሉ።'),
  ('754dafb9-a143-540e-a64e-b49b7c69355a', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'ccb664ce-5ff4-5389-ab3a-dbe07ce1ea3d', 5, 5, 'እንዲሁም አንደበት ደግሞ ትንሽ የአካል ክፍል ሆኖ በታላላቅ ነገር ይመካል። እነሆ ትንሽ እሳት እንዴት ያለ ትልቅ ጫካ ያቃጥላል።'),
  ('d46598f9-2882-59a6-a59d-6391aaa9f071', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'ccb664ce-5ff4-5389-ab3a-dbe07ce1ea3d', 6, 6, 'አንደበትም እሳት ነው። አንደበት በሰውነታችን ክፍሎች መካከል ዐመፀኛ ዓለም ሆኖአል፤ ሥጋን ሁሉ ያሳድፋልና፤ የፍጥረትንም ሩጫ ያቃጥላል፤ በገሃነምም ይቃጠላል።'),
  ('e2816b93-de9b-52e9-a8b4-00c22ed1111c', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'ccb664ce-5ff4-5389-ab3a-dbe07ce1ea3d', 7, 7, 'የአራዊትና የወፎች የተንቀሳቃሾችና በባሕር ያለ የፍጥረት ወገን ሁሉ በሰው ይገራል፤ ደግሞ ተገርቶአል፤'),
  ('6f082c38-f78d-5cf7-a337-8fe7a6451b89', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'ccb664ce-5ff4-5389-ab3a-dbe07ce1ea3d', 8, 8, 'ነገር ግን አንደበትን ሊገራ ማንም ሰው አይችልም፤ የሚገድል መርዝ የሞላበት ወላዋይ ክፋት ነው።'),
  ('b08388b4-dbda-5f67-a852-4eecd28947b9', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'ccb664ce-5ff4-5389-ab3a-dbe07ce1ea3d', 9, 9, 'በእርሱ ጌታንና አብን እናመሰግናለን፤ በእርሱም እንደ እግዚአብሔር ምሳሌ የተፈጠሩትን ሰዎች እንረግማለን፤'),
  ('f13c3423-4be6-5383-a36f-ab8ac87d8349', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'ccb664ce-5ff4-5389-ab3a-dbe07ce1ea3d', 10, 10, 'ከአንድ አፍ በረከትና መርገም ይወጣሉ። ወንድሞቼ ሆይ! ይህ እንዲህ ሊሆን አይገባም።'),
  ('4bba4915-5c05-5e01-aea2-6ae2bbb46d79', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'ccb664ce-5ff4-5389-ab3a-dbe07ce1ea3d', 11, 11, 'ምንጭስ ከአንድ አፍ የሚጣፍጥንና የሚመርን ውሃ ያመነጫልን?'),
  ('33bea2c6-f7ed-5c5f-ae32-3f1e16f779ee', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'ccb664ce-5ff4-5389-ab3a-dbe07ce1ea3d', 12, 12, 'ወንድሞቼ ሆይ! በለስ ወይራን ወይስ ወይን በለስን ልታፈራ ትችላለችን? ከጨው ውሃም ጣፋጭ ውሃ አይወጣም።'),
  ('0ea13bcc-9221-5ab0-accd-c481f8356480', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'faa941f3-f95c-52ae-a762-25770cac251c', 1, 13, 'ከእናንተ ጥበበኛና አስተዋይ ማን ነው? በመልካም አንዋዋሩ ሥራውን በጥበብ የዋህነት ያሳይ።'),
  ('153a14eb-e3e0-5149-a4ec-ba5498eddba4', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'faa941f3-f95c-52ae-a762-25770cac251c', 2, 14, 'ነገር ግን መራራ ቅንዓትና አድመኛነት በልባችሁ ቢኖርባችሁ፥ አትመኩ፤ በእውነትም ላይ አትዋሹ።'),
  ('0ffc447f-34cb-547d-a2ef-c646203440dc', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'faa941f3-f95c-52ae-a762-25770cac251c', 3, 15, 'ይህ ጥበብ ከላይ የሚወርድ አይደለም፤ ነገር ግን የምድር ነው፤ የሥጋም ነው፤ የአጋንንትም ነው፤'),
  ('66824259-b6b4-57f2-a3b4-26cc93d566f8', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'faa941f3-f95c-52ae-a762-25770cac251c', 4, 16, 'ቅንዓትና አድመኛነት ባሉበት ስፍራ በዚያ ሁከትና ክፉ ሥራ ሁሉ አሉና።'),
  ('be6497eb-c973-5b6e-a3b0-ed469fd88501', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'faa941f3-f95c-52ae-a762-25770cac251c', 5, 17, 'ላይኛይቱ ጥበብ ግን በመጀመሪያ ንጽሕት ናት፤ በኋላም ታራቂ፥ ገር፥ እሺ ባይ፥ ምሕረትና በጎ ፍሬ የሞላባት፥ ጥርጥርና ግብዝነት የሌለባት ናት።'),
  ('1b2e7973-adf7-5f46-a6e7-9976fc8e8ced', 'b4fe6882-b515-5d5d-a4bf-8fa5a20b1e4a', 'faa941f3-f95c-52ae-a762-25770cac251c', 6, 18, 'የጽድቅም ፍሬ ሰላምን ለሚያደርጉት ሰዎች በሰላም ይዘራል።'),
  ('ce5fd18e-78c2-5f81-a3d1-90bab613c07e', '75ac7e69-ac5f-5a8b-a24d-4dbda386ffa9', '8766abb1-5a1b-5eff-a84b-5fbe1c574f9d', 1, 1, 'በእናንተ ዘንድ ጦርና ጠብ ከወዴት ይመጣሉ? በአካላችሁ ክፍሎች ውስጥ ከሚዋጉ ከእነዚህ ከምቾቶቻችሁ አይደሉምን?'),
  ('4f189734-3815-545b-a78f-6d673452647d', '75ac7e69-ac5f-5a8b-a24d-4dbda386ffa9', '8766abb1-5a1b-5eff-a84b-5fbe1c574f9d', 2, 2, 'ትመኛላችሁ ለእናንተም አይሆንም፤ ትገድላላችሁ በብርቱም ትፈልጋላችሁ፥ ልታገኙም አትችሉም፤ ትጣላላችሁ ትዋጉማላችሁ ነገር ግን አትለምኑምና ለእናንተ አይሆንም፤'),
  ('bd07e40f-acb5-5087-a770-f79c6f78d8c6', '75ac7e69-ac5f-5a8b-a24d-4dbda386ffa9', '8766abb1-5a1b-5eff-a84b-5fbe1c574f9d', 3, 3, 'ትለምናላችሁ፥ በምቾቶቻችሁም ትከፍሉ ዘንድ በክፉ ትለምናላችሁና አትቀበሉም።'),
  ('3b4c4a82-6d64-51c9-ae3d-8c2e55170b26', '75ac7e69-ac5f-5a8b-a24d-4dbda386ffa9', '8766abb1-5a1b-5eff-a84b-5fbe1c574f9d', 4, 4, 'አመንዝሮች ሆይ! ዓለምን መውደድ ከእግዚአብሔር ጋር መጣላት እንዲሆን አታውቁምን? እንግዲህ የዓለም ወዳጅ ሊሆን የሚፈቅድ ሁሉ የእግዚአብሔር ጠላት ሆኖአል።'),
  ('0f1211ea-38a3-54eb-af59-6079223810d8', '75ac7e69-ac5f-5a8b-a24d-4dbda386ffa9', '8766abb1-5a1b-5eff-a84b-5fbe1c574f9d', 5, 5, 'ወይስ መጽሐፍ “በእኛ ዘንድ ያሳደረው መንፈስ በቅንዓት ይመኛል፤” ያለው በከንቱ እንደ ተናገረ ይመስላችኋልን?'),
  ('0e0d7817-e4cb-5733-a23d-c558fe055e20', '75ac7e69-ac5f-5a8b-a24d-4dbda386ffa9', '8766abb1-5a1b-5eff-a84b-5fbe1c574f9d', 6, 6, 'ነገር ግን ጸጋን አብልጦ ይሰጣል፤ ስለዚህ “እግዚአብሔር ትዕቢተኞችን ይቃወማል፤ ለትሑታን ግን ጸጋን ይሰጣል፤” ይላል።'),
  ('aa3c9480-690b-5c05-a4d7-3b9558d33905', '75ac7e69-ac5f-5a8b-a24d-4dbda386ffa9', '8766abb1-5a1b-5eff-a84b-5fbe1c574f9d', 7, 7, 'እንግዲህ ለእግዚአብሔር ተገዙ፤ ዲያብሎስን ግን ተቃወሙ ከእናንተም ይሸሻል፤'),
  ('d757c67a-d619-5d93-a5ef-fef1e825022b', '75ac7e69-ac5f-5a8b-a24d-4dbda386ffa9', '8766abb1-5a1b-5eff-a84b-5fbe1c574f9d', 8, 8, 'ወደ እግዚአብሔር ቅረቡ ወደ እናንተም ይቀርባል። እናንተ ኀጢአተኞች! እጆቻችሁን አንጹ፤ ሁለት አሳብም ያላችሁ እናንተ! ልባችሁን አጥሩ።'),
  ('ff2a7928-29e2-52c5-a2f1-e07d31e29853', '75ac7e69-ac5f-5a8b-a24d-4dbda386ffa9', '8766abb1-5a1b-5eff-a84b-5fbe1c574f9d', 9, 9, 'ተጨነቁና እዘኑ፤ አልቅሱም፤ ሳቃችሁ ወደ ሐዘን ደስታችሁም ወደ ትካዜ ይለወጥ።'),
  ('6d7d605b-53f9-5a5e-a38c-9137165c8c88', '75ac7e69-ac5f-5a8b-a24d-4dbda386ffa9', '8766abb1-5a1b-5eff-a84b-5fbe1c574f9d', 10, 10, 'በጌታ ፊት ራሳችሁን አዋርዱ፤ ከፍ ከፍም ያደርጋችኋል።'),
  ('49a00152-0504-59cc-ae37-bf6255235d52', '75ac7e69-ac5f-5a8b-a24d-4dbda386ffa9', 'c559d8c9-1995-52e1-aba0-909ae5ef8b8f', 1, 11, 'ወንድሞች ሆይ! እርስ በርሳችሁ አትተማሙ። ወንድሙን የሚያማ በወንድሙም የሚፈርድ ሕግን ያማል፤ በሕግም ይፈርዳል፤ በሕግም ብትፈርድ ፈራጅ ነህ እንጂ ሕግን አድራጊ አይደለህም።'),
  ('2e95efc7-3f0a-58f2-a309-def3c1610c2a', '75ac7e69-ac5f-5a8b-a24d-4dbda386ffa9', 'c559d8c9-1995-52e1-aba0-909ae5ef8b8f', 2, 12, 'ሕግን የሚሰጥና የሚፈርድ አንድ ነው፤ እርሱም ሊያድን ሊያጠፋም የሚችል ነው፤ በሌላው ግን የምትፈርድ አንተ ማን ነህ?'),
  ('3727c8db-fe37-56fb-a376-fb66c6c59f25', '75ac7e69-ac5f-5a8b-a24d-4dbda386ffa9', '6f5c0e8d-a900-5f67-af1e-ae4c46b02fc2', 1, 13, 'አሁንም “ዛሬ ወይም ነገ ወደዚህ ከተማ እንሄዳለን፤ በዚያም ዓመት እንኖራለን፤ እንነግድማለን፤ እናተርፍማለን፤” የምትሉ እናንተ! ተመልከቱ፤ ነገ የሚሆነውን አታውቁምና።'),
  ('eb25e40b-50b1-59d6-a14c-549b86a95f4c', '75ac7e69-ac5f-5a8b-a24d-4dbda386ffa9', '6f5c0e8d-a900-5f67-af1e-ae4c46b02fc2', 2, 14, 'ሕይወታችሁ ምንድር ነው? ጥቂት ጊዜ ታይቶ ኋላ እንደሚጠፋ እንፍዋለት ናችሁና።'),
  ('556e9900-27f7-5bda-a4e3-e8827d6eb8b5', '75ac7e69-ac5f-5a8b-a24d-4dbda386ffa9', '6f5c0e8d-a900-5f67-af1e-ae4c46b02fc2', 3, 15, 'በዚህ ፈንታ “ጌታ ቢፈቅድ፥ ብንኖርም ይህን ወይም ያን እናደርጋለን፤” ማለት ይገባችኋል።'),
  ('38b6f126-ec2a-5aa1-a9d5-1c8edb1d304d', '75ac7e69-ac5f-5a8b-a24d-4dbda386ffa9', '6f5c0e8d-a900-5f67-af1e-ae4c46b02fc2', 4, 16, 'አሁን ግን በትዕቢታችሁ ትመካላችሁ፤ እንደዚህ ያለ ትምክህት ሁሉ ክፉ ነው።'),
  ('17e67680-3fda-54dd-aa84-32c7d401ffda', '75ac7e69-ac5f-5a8b-a24d-4dbda386ffa9', '6f5c0e8d-a900-5f67-af1e-ae4c46b02fc2', 5, 17, 'እንግዲህ በጎ ለማድረግ አውቆ ለማይሠራው ኀጢአት ነው።'),
  ('64569076-863a-5892-a457-b1dee6472991', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', '7eb99c9c-c14d-58f5-a7c0-6174bfc0b9c9', 1, 1, 'አሁንም እናንተ ባለጠጎች! ስለሚደርስባችሁ ጭንቅ ዋይ ዋይ እያላችሁ አልቅሱ።'),
  ('9263adc8-305a-5e16-aa08-64040ffacb71', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', '7eb99c9c-c14d-58f5-a7c0-6174bfc0b9c9', 2, 2, 'ሀብታችሁ ተበላሽቶአል፤ ልብሳችሁም በብል ተበልቶአል።'),
  ('32ea6f51-8eba-578c-a2c4-4c4b736afa50', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', '7eb99c9c-c14d-58f5-a7c0-6174bfc0b9c9', 3, 3, 'ወርቃችሁም ብራችሁም ዝጎአል፤ ዝገቱም ምስክር ይሆንባችኋል፤ ሥጋችሁንም እንደ እሳት ይበላል። ለኋለኛው ቀን መዝገብን አከማችታችኋል።'),
  ('8cb3a552-6d6a-504e-ab22-de052b9bcbfb', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', '7eb99c9c-c14d-58f5-a7c0-6174bfc0b9c9', 4, 4, 'እነሆ እርሻችሁን ያጨዱት የሠራተኞች ደመወዝ በእናንተ ተቀምቶ ይጮኻል፤ የአጫጆችም ድምፅ ወደ ጌታ ጸባዖት ጆሮ ገብቶአል።'),
  ('df538cde-5aad-5835-a560-a04d1f26e27a', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', '7eb99c9c-c14d-58f5-a7c0-6174bfc0b9c9', 5, 5, 'በምድር ላይ ተቀማጥላችኋል፤ በሴሰኝነትም ኖራችኋል፤ ለእርድ ቀን እንደሚያወፍር ልባችሁን አወፍራችኋል።'),
  ('9f3a41e3-993a-5ae3-adda-3f27015af58e', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', '7eb99c9c-c14d-58f5-a7c0-6174bfc0b9c9', 6, 6, 'ጻድቁን ኰንናችሁታል፤ ገድላችሁትማል፤ እናንተን አይቃወምም።'),
  ('ea6669e5-a889-5573-a1c4-db1f241f9249', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', 'd76e9f18-fadf-55b1-ab4e-fb6b48ed8a2b', 1, 7, 'እንግዲህ ወንድሞች ሆይ! ጌታ እስኪመጣ ድረስ ታገሡ። እነሆ ገበሬው የፊተኛውንና የኋለኛውን ዝናብ እስኪቀበል ድረስ እርሱን እየታገሠ የከበረውን የመሬት ፍሬ ይጠብቃል።'),
  ('731c54ce-c3c7-5979-aec8-e19da911b77f', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', 'd76e9f18-fadf-55b1-ab4e-fb6b48ed8a2b', 2, 8, 'እናንተ ደግሞ ታገሡ፤ ልባችሁንም አጽኑ፤ የጌታ መምጣት ቀርቦአልና።'),
  ('7f6cb99f-f493-5a4a-a52f-7e85e29f61c0', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', 'd76e9f18-fadf-55b1-ab4e-fb6b48ed8a2b', 3, 9, 'ወንድሞች ሆይ! እንዳይፈረድባችሁ እርስ በርሳችሁ አታጉረምርሙ፤ እነሆ ፈራጅ በደጅ ፊት ቆሞአል።'),
  ('21268c44-d6a8-586f-aa34-b28871b5681a', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', 'd76e9f18-fadf-55b1-ab4e-fb6b48ed8a2b', 4, 10, 'ወንድሞች ሆይ! የመከራና የትዕግሥት ምሳሌ የሆኑትን በጌታ ስም የተናገሩትን ነቢያትን ተመልከቱ።'),
  ('67e41a31-4cce-5855-af25-a474d9333351', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', 'd76e9f18-fadf-55b1-ab4e-fb6b48ed8a2b', 5, 11, 'እነሆ በትዕግሥት የጸኑትን ብፁዓን እንላቸዋለን፤ ኢዮብ እንደ ታገሠ ሰምታችኋል፤ ጌታም እንደ ፈጸመለት አይታችኋል፤ ጌታ እጅግ የሚምር የሚራራም ነውና።'),
  ('1ac7d998-a889-58a3-a989-116dc4b6f4a8', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', 'd76e9f18-fadf-55b1-ab4e-fb6b48ed8a2b', 6, 12, 'ከሁሉም በፊት ወንድሞቼ ሆይ! በሰማይም ቢሆን በምድርም ቢሆን በሌላ መሐላም ቢሆን በምንም አትማሉ፤ ነገር ግን ከፍርድ በታች እንዳትወድቁ ነገራችሁ አዎን ቢሆን አዎን ይሁን፤ አይደለምም ቢሆን አይደለም ይሁን።'),
  ('868b7df6-8446-5fb7-aed9-2c9037066496', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', 'd76e9f18-fadf-55b1-ab4e-fb6b48ed8a2b', 7, 13, 'ከእናንተ መከራን የሚቀበል ማንም ቢኖር እርሱ ይጸልይ፤ ደስ የሚለውም ማንም ቢኖር እርሱ ይዘምር።'),
  ('e0497de8-9ff9-505a-addb-0c92750ffa9d', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', 'd76e9f18-fadf-55b1-ab4e-fb6b48ed8a2b', 8, 14, 'ከእናንተ የታመመ ማንም ቢኖር የቤተ ክርስቲያንን ሽምግሌዎች ወደ እርሱ ይጥራ፤ በጌታም ስም እርሱን ዘይት ቀብተው ይጸልዩለት።'),
  ('b31309e5-33c7-508b-a18c-8d6e9c52631f', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', 'd76e9f18-fadf-55b1-ab4e-fb6b48ed8a2b', 9, 15, 'የእምነትም ጸሎት ድውዩን ያድናል፤ ጌታም ያስነሣዋል፤ ኀጢአትንም ሠርቶ እንደ ሆነ ይሰረይለታል።'),
  ('0c3e42e4-25d4-5999-a2b3-81d37e38df17', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', 'd76e9f18-fadf-55b1-ab4e-fb6b48ed8a2b', 10, 16, 'እርስ በርሳችሁ በኀጢአታችሁ ተናዘዙ። ትፈወሱም ዘንድ እያንዳንዱ ስለ ሌላው ይጸልይ፤ የጻድቅ ሰው ጸሎት በሥራዋ እጅግ ኀይል ታደርጋለች።'),
  ('fef2b3f8-3145-571a-a74d-03000f6cf7c3', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', 'd76e9f18-fadf-55b1-ab4e-fb6b48ed8a2b', 11, 17, 'ኤልያስ እንደ እኛ የሆነ ሰው ነበረ፤ ዝናብም እንዳይዘንብ አጥብቆ ጸለየ፤ በምድርም ላይ ሦስት ዓመት ከስድስት ወር አልዘነበም፤'),
  ('bb21af48-18f9-5e03-af65-fcda32a3313c', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', 'd76e9f18-fadf-55b1-ab4e-fb6b48ed8a2b', 12, 18, 'ሁለተኛም ጸለየ፤ ሰማዩም ዝናብን ሰጠ፤ ምድሪቱም ፍሬዋን አበቀለች።'),
  ('1675c908-d232-5e4b-a4de-1541934e9464', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', 'd76e9f18-fadf-55b1-ab4e-fb6b48ed8a2b', 13, 19, 'ወንድሞች ሆይ! ከእናንተ ማንም ከእውነት ቢስት አንዱም ቢመልሰው፥'),
  ('061751b3-f711-5b58-ab28-76ccfa85454a', '8fb4b0fe-6f04-5ad1-a714-cca1e3ff7e60', 'd76e9f18-fadf-55b1-ab4e-fb6b48ed8a2b', 14, 20, 'ኀጢአተኛን ከተሳሳተበት መንገድ የሚመልሰው ነፍሱን ከሞት እንዲያድን፥ የኀጢአትንም ብዛት እንዲሸፍን ይወቅ።'),
  ('64f2f279-65cd-5540-aa46-f806ecf49103', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', 'c20af30f-9be1-5cd8-aeb3-2fc6ca506a7f', 1, 1, 'የኢየሱስ ክርስቶስ ባሪያ የያዕቆብም ወንድም የሆነ ይሁዳ፥ በእግዚአብሔር አብ ተወደው ለኢየሱስ ክርስቶስም ተጠብቀው ለተጠሩ፤'),
  ('82324bfb-b4b6-579a-aa9c-7d7ae2304fa2', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', 'c20af30f-9be1-5cd8-aeb3-2fc6ca506a7f', 2, 2, 'ምሕረትና ሰላም ፍቅርም ይብዛላችሁ።'),
  ('5b6d0f13-41fd-508c-a04c-27ebeb3ad355', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', 'a265384a-f15e-5726-ac16-1805d8b6b67d', 1, 3, 'ወዳጆች ሆይ! ስለምንካፈለው ስለ መዳናችን ልጽፍላችሁ እጅግ ተግቼ ሳለሁ፥ ለቅዱሳን አንድ ጊዜ ፈጽሞ ስለ ተሰጠ ሃይማኖት እንድትጋደሉ እየመከርኋችሁ እጽፍላችሁ ዘንድ ግድ ሆነብኝ።'),
  ('399c9c8d-9b56-52d0-a725-9ba101a56c79', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', 'a265384a-f15e-5726-ac16-1805d8b6b67d', 2, 4, 'ከብዙ ጊዜ በፊት ለዚህ ፍርድ የተጻፉ አንዳንዶች ሰዎች ሾልከው ገብተዋልና፤ ኀጢአተኞች ሆነው የአምላካችንን ጸጋ በሴሰኝነት ይለውጣሉ፤ ብቻውን ንጉሣችንንና ጌታችንንም የሆነውን ኢየሱስ ክርስቶስን ይክዳሉ።'),
  ('85abdc61-b716-5494-a791-8299bc6e29bf', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', 'a265384a-f15e-5726-ac16-1805d8b6b67d', 3, 5, 'ዳሩ ግን ሁሉን አንድ ጊዜ ፈጽሞ ምንም የተማራችሁ ብትሆኑ ጌታ ከግብጽ አገር ሕዝቡን አድኖ የማያምኑትን በኋላ እንዳጠፋቸው ላሳስባችሁ እወዳለሁ።'),
  ('5e906cf9-38c2-5b9e-a90b-453e83610e20', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', 'a265384a-f15e-5726-ac16-1805d8b6b67d', 4, 6, 'መኖሪያቸውንም የተዉትን እንጂ የራሳቸውን አለቅነት ያልጠበቁትን መላእክት በዘላለም እስራት ከጨለማ በታች እስከ ታላቁ ቀን ፍርድ ድረስ ጠብቆአቸዋል።'),
  ('42f27965-2d31-508f-ad99-947ba19c0efe', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', 'a265384a-f15e-5726-ac16-1805d8b6b67d', 5, 7, 'እንዲሁም እንደ እነርሱ ዝሙትን ያደረጉና ሌላን ሥጋ የተከተሉ ሰዶምና ገሞራ በዙሪያቸውም የነበሩ ከተማዎች በዘላለም እሳት እየተቀጡ ምሳሌ ሆነዋል።'),
  ('852cc166-362f-56cf-a064-12cf6a81107a', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', 'a265384a-f15e-5726-ac16-1805d8b6b67d', 6, 8, 'እንዲሁም እነዚህ ሰዎች ደግሞ እያለሙ ሥጋቸውን ያረክሳሉ፤ ጌትነትንም ይጥላሉ፤ ሥልጣን ያላቸውንም ይሳደባሉ።'),
  ('f03ef24d-d49d-547e-a07c-ee0e25974ea1', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', 'a265384a-f15e-5726-ac16-1805d8b6b67d', 7, 9, 'የመላእክት አለቃ ሚካኤል ግን ከዲያብሎስ ጋር በተከራከረ ጊዜ ስለ ሙሴ ሥጋ ሲነጋገር “ጌታ ይገሥጽህ!” አለው እንጂ የስድብን ፍርድ ሊናገረው አልደፈረም።'),
  ('67f4f2da-3773-5ff0-a060-d8d4f8ec7211', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', 'a265384a-f15e-5726-ac16-1805d8b6b67d', 8, 10, 'እነዚህ ግን የማያውቁትን ሁሉ ይሳደባሉ፤ አእምሮም እንደሌላቸው እንስሶች በፍጥረታቸው በሚያውቁት ሁሉ በእርሱ ይጠፋሉ።'),
  ('6ebea647-2194-5e8d-a07a-ff1230478675', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', 'a265384a-f15e-5726-ac16-1805d8b6b67d', 9, 11, 'ወዮላቸው! በቃየል መንገድ ሄደዋልና፤ ስለ ደመወዝም ለበለዓም ስሕተት ራሳቸውን አሳልፈው ሰጥተዋል፤ በቆሬም መቃወም ጠፍተዋል።'),
  ('a4039a94-2dfc-595a-ae67-02aa815c2e88', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', 'a265384a-f15e-5726-ac16-1805d8b6b67d', 10, 12, 'እነዚህ ከእናንተ ጋር ሲጋበዙ በፍቅር ግብዣችሁ እንደ እድፍ ናቸው፤ እንደ እረኞች ያለ ፍርሃት ራሳቸውን ይጠብቃሉ፤ በነፋስ የተወሰዱ ውሃ የሌለባቸው ደመናዎች፥ ፍሬ የማያፈሩ ሁለት ጊዜ የሞቱ ከነሥራቸው የተነቀሉ በበጋ የደረቁ ዛፎች፥'),
  ('d8a14233-65f3-5d35-abc2-e277c96f5fc8', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', 'a265384a-f15e-5726-ac16-1805d8b6b67d', 11, 13, 'የገዛ ነውራቸውን አረፋ እየደፈቁ ጨካኝ የባሕር ማዕበል፥ ድቅድቅ ጨለማ ለዘላለም የተጠበቀላቸው የሚንከራተቱ ከዋክብት ናቸው።'),
  ('682f9d8d-31b0-5c31-a96b-ed7b47ddb883', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', 'a265384a-f15e-5726-ac16-1805d8b6b67d', 12, 14, 'ከአዳም ጀምሮ ሰባተኛ የሆነ ሄኖክ “እነሆ ጌታ በሁሉ ላይ እንዲፈርድ፥ በኀጢአተኝነትም ስላደረጉት ስለ ኀጢአተኛ ሥራቸው ሁሉ ዐመፀኞችም ኀጢአተኞች በእርሱ ላይ ስለ ተናገሩ ስለ ጭከና ነገር ሁሉ ኀጢአተኞችን ሁሉ እንዲወቅስ ከአእላፋት ቅዱሳኑ ጋር መጥቶአል፤” ብሎ ለእነዚህ ደግሞ ትንቢት ተናገረ።'),
  ('269adcb9-7ea2-54ca-a260-ada263c656ce', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', 'a265384a-f15e-5726-ac16-1805d8b6b67d', 13, 16, 'እነዚህ እንደ ምኞታቸው እየሄዱ የሚያንጎራጉሩና ስለ ዕድላቸው የሚያጕረመርሙ ናቸው፤ እንዲረባቸውም ለሰው ፊት እያደሉ አፋቸው ከመጠን ይልቅ ታላቅ ቃል ይናገራል።'),
  ('a675267e-4a94-5a72-a2f9-a5964f623ab2', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', '5621bb24-e4a1-505f-aa4d-bd7e82fc76f1', 1, 17, 'እናንተ ግን ወዳጆች ሆይ! በጌታችን በኢየሱስ ክርስቶስ ሐዋርያት ቀድሞ የተነገረውን ቃል አስቡ፤'),
  ('216c3566-8bae-59e0-ac8e-373bc70e886d', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', '5621bb24-e4a1-505f-aa4d-bd7e82fc76f1', 2, 18, 'እነርሱ “በመጨረሻው ዘመን በኀጢአተኝነት እንደ ገዛ ምኞታቸው እየሄዱ ዘባቾች ይሆናሉ፤” ብለዋችኋልና።'),
  ('14a13054-16c5-55d2-a546-b857cdaf90be', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', '5621bb24-e4a1-505f-aa4d-bd7e82fc76f1', 3, 19, 'እነዚህ የሚያለያዩ ሥጋውያንም የሆኑ መንፈስም የሌላቸው ሰዎች ናቸው።'),
  ('03595f65-691e-598d-ae76-2d9bfed2fb7b', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', '5621bb24-e4a1-505f-aa4d-bd7e82fc76f1', 4, 20, 'እናንተ ግን ወዳጆች ሆይ! ከሁሉ ይልቅ በተቀደሰ ሃይማኖታችሁ ራሳችሁን ለማነጽ እየተጋችሁ በመንፈስ ቅዱስም እየጸለያችሁ፥'),
  ('56231879-4a17-51e0-aacb-5c02879a9039', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', '5621bb24-e4a1-505f-aa4d-bd7e82fc76f1', 5, 21, 'ወደ ዘላለም ሕይወት የሚወስደውን የጌታችንን የኢየሱስ ክርስቶስን ምሕረት ስትጠባበቁ በእግዚአብሔር ፍቅር ራሳችሁን ጠብቁ።'),
  ('c2a7d5f3-ae98-5172-a178-9e950b25c47b', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', '5621bb24-e4a1-505f-aa4d-bd7e82fc76f1', 6, 22, 'አንዳንዶች ተከራካሪዎችንም ውቀሱ፤ አንዳንዶችንም ከእሳት ነጥቃችሁ አድኑ፤'),
  ('4b5e5b31-a975-552f-ae78-87b7eca2c3fd', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', '5621bb24-e4a1-505f-aa4d-bd7e82fc76f1', 7, 23, 'አንዳንዶችንም በሥጋ የረከሰውን ልብስ እንኳ እየጠላችሁ በፍርሃት ማሩ።'),
  ('e667b58f-a447-5073-ab49-bc9ec491ff0b', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', '5621bb24-e4a1-505f-aa4d-bd7e82fc76f1', 8, 24, 'ሳትሰናከሉም እንዲጠብቃችሁ፥ በክብሩም ፊት በደስታ ነውር የሌላችሁ አድርጎ እንዲያቆማችሁ ለሚችለው፤'),
  ('f263b5dd-b57f-5b8f-aa3d-58dff4740fe1', '20e6ba78-1b3b-547d-a97f-8efbdce0fc47', '5621bb24-e4a1-505f-aa4d-bd7e82fc76f1', 9, 25, 'ብቻውን ለሆነ አምላክና መድኃኒታችን ከዘመን ሁሉ በፊት አሁንም እስከ ዘላለምም ድረስ በጌታችን በኢየሱስ ክርስቶስ ክብርና ግርማ ኀይልም ሥልጣንም ይሁን፤ አሜን።'),
  ('424cceaf-c030-5016-aadb-59ebf96b4504', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '2b25ca69-ff1d-5031-a9d3-a9e71b924cff', 1, 1, 'ቶሎ ይሆን ዘንድ የሚገባውን ነገር ለባሪያዎቹ ያሳይ ዘንድ እግዚአብሔር ለኢየሱስ ክርስቶስ የሰጠው በእርሱም የተገለጠው ይህ ነው፤ ኢየሱስም በመልአኩ ልኮ ለባሪያው ለዮሐንስ አመለከተ፤'),
  ('9bf2a035-e31e-5713-ab67-fdffdb25b515', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '2b25ca69-ff1d-5031-a9d3-a9e71b924cff', 2, 2, 'እርሱም ለእግዚአብሔር ቃልና ለኢየሱስ ክርስቶስ ምስክር ላየውም ሁሉ መሰከረ።'),
  ('4d31f37d-8e27-5899-a728-43dcd3fd99e7', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '2b25ca69-ff1d-5031-a9d3-a9e71b924cff', 3, 3, 'ዘመኑ ቀርቦአልና የሚያነበው፥ የትንቢቱን ቃል የሚሰሙትና በውስጡ የተጻፈውን የሚጠብቁት ብፁዓን ናቸው።'),
  ('9d0da193-8160-578f-a8d4-4d24b20a6cf1', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '2b25ca69-ff1d-5031-a9d3-a9e71b924cff', 4, 4, 'ዮሐንስ በእስያ ላሉት ለሰባቱ አብያተ ክርስቲያናት፤ ካለውና ከነበረው፥ ከሚመጣውም፥ በዙፋኑም ፊት ካሉት ከሰባቱ መናፍስት፥ ከታመነውም ምስክር፥ ከሙታንም በኵር፥ የምድርም ነገሥታት ገዥ ከሆነ ከኢየሱስ ክርስቶስ ጸጋና ሰላም ለእናንተ ይሁን። ለወደደን፥ ከኀጢአታችንም በደሙ ላጠበን፥'),
  ('cc3d3ad5-5916-5152-abb2-6717e15a77c6', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '2b25ca69-ff1d-5031-a9d3-a9e71b924cff', 5, 6, 'መንግሥትም፥ ለአባቱም ለእግዚአብሔር ካህናት እንድንሆን ላደረገ፥ ለእርሱ ከዘላለም እስከ ዘላለም ድረስ ክብርና ኀይል ይሁን፤ አሜን።'),
  ('d4dc59a9-1f80-5054-a712-bba310b2a98d', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '2b25ca69-ff1d-5031-a9d3-a9e71b924cff', 6, 7, 'እነሆ ከደመና ጋር ይመጣል፤ ዐይንም ሁሉ የወጉትም ያዩታል፤ የምድርም ወገኖች ሁሉ ስለ እርሱ ዋይ ዋይ ይላሉ። አዎን፤ አሜን።'),
  ('b2cf2e5a-df01-5862-acae-99ecb06225d0', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '2b25ca69-ff1d-5031-a9d3-a9e71b924cff', 7, 8, 'ያለውና የነበረው የሚመጣውም ሁሉንም የሚገዛ ጌታ አምላክ “አልፋና ዖሜጋ እኔ ነኝ፤” ይላል።'),
  ('fb708099-3589-54d0-a4de-9367dbb692c8', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '4058df4c-e0e1-5df6-a19b-3492293f2522', 1, 9, 'እኔ ወንድማችሁ የሆንሁ ከእናንተም ጋር አብሬ መከራውንና መንግሥቱን የኢየሱስ ክርስቶስንም ትዕግሥት የምካፈል ዮሐንስ፥ ስለ እግዚአብሔር ቃልና ስለ ኢየሱስ ምስክር ፍጥሞ በምትባል ደሴት ነበርሁ።'),
  ('83112351-5028-5bfa-a930-bea395ff2722', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '4058df4c-e0e1-5df6-a19b-3492293f2522', 2, 10, 'በጌታ ቀን በመንፈስ ነበርሁ፤ በኋላዬም የመለከትን ድምፅ የሚመስል ታላቅ ድምፅ ሰማሁ፤'),
  ('c85f68f0-4eae-5756-ab88-43c0f05ffb94', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '4058df4c-e0e1-5df6-a19b-3492293f2522', 3, 11, 'እንዲሁም “የምታየውን በመጽሐፍ ጽፈህ ወደ ኤፌሶንና ወደ ሰምርኔስ ወደ ጴርጋሞንም ወደ ትያጥሮንም ወደ ሰርዴስም ወደ ፊላደልፊያም ወደ ሎዲቅያም በእስያ ወዳሉት ወደ ሰባቱ አብያተ ክርስቲያናት ላክ፤” አለኝ።'),
  ('a11b144b-17e9-598d-a36c-50bf5b5b917a', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '4058df4c-e0e1-5df6-a19b-3492293f2522', 4, 12, 'የሚናገረኝንም ድምፅ ለማየት ዘወር አልሁ፤ ዘወርም ብዬ ሰባት የወርቅ መቅረዞች አየሁ፤'),
  ('b9df3393-d0a4-5e0e-ac35-c1472c368c79', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '4058df4c-e0e1-5df6-a19b-3492293f2522', 5, 13, 'በመቅረዞቹም መካከል የሰው ልጅ የሚመስለውን አየሁ፤ እርሱም እስከ እግሩ ድረስ ልብስ የለበሰ ደረቱንም በወርቅ መታጠቂያ የታጠቀ ነበር።'),
  ('344e9a57-3842-5fdc-a43c-5dbf337cde4c', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '4058df4c-e0e1-5df6-a19b-3492293f2522', 6, 14, 'ራሱና የራሱ ጠጕርም እንደ ነጭ የበግ ጠጕር እንደ በረዶም ነጭ ነበሩ፤ ዐይኖቹም እንደ እሳት ነበልባል ነበሩ፤'),
  ('95842473-be79-57cb-ab32-b79bc8be3602', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '4058df4c-e0e1-5df6-a19b-3492293f2522', 7, 15, 'እግሮቹም በእቶን የነጠረ የጋለ ናስ ይመስሉ ነበር፤ ድምፁም እንደ ብዙ ውሃዎች ድምፅ ነበረ።'),
  ('aea8efc8-d5b9-53b1-ab24-24c279dbd3cc', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '4058df4c-e0e1-5df6-a19b-3492293f2522', 8, 16, 'በቀኝ እጁም ሰባት ከዋክብት ነበሩት፤ ከአፉም በሁለት ወገን የተሳለ ስለታም ሰይፍ ወጣ፤ ፊቱም በኀይል እንደሚበራ እንደ ፀሐይ ነበረ።'),
  ('a35c0ca1-b40c-50b4-acb1-319da75e91f9', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '4058df4c-e0e1-5df6-a19b-3492293f2522', 9, 17, 'ባየሁትም ጊዜ እንደ ሞተ ሰው ሆኜ ከእግሩ በታች ወደቅሁ። ቀኝ እጁንም ጫነብኝ፤ እንዲህም አለኝ “አትፍራ፤ ፊተኛውና መጨረሻው እኔ ነኝ፤'),
  ('eab58f46-83ae-51d7-a21b-de3a9c2bc300', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '4058df4c-e0e1-5df6-a19b-3492293f2522', 10, 18, 'ሕያውም እኔ ነኝ፤ ሞቼም ነበርሁ፤ እነሆም ከዘላለም እስከ ዘላለም ድረስ ሕያው ነኝ፤ የሞትና የሲኦልም መክፈቻ አለኝ።'),
  ('612c49fb-c302-5423-af1a-5b3c4a3b938d', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '4058df4c-e0e1-5df6-a19b-3492293f2522', 11, 19, 'እንግዲህ ያየኸውን አሁንም ያለውን ከዚህም በኋላ ይሆን ዘንድ ያለውን ጻፍ።'),
  ('418de27f-afcb-53db-a9c0-6bb3953d2382', '60c0d219-21db-581b-a1a7-a45d01e7cec0', '4058df4c-e0e1-5df6-a19b-3492293f2522', 12, 20, 'በቀኝ እጄ ያየሃቸው የሰባቱ ከዋክብትና የሰባቱ የወርቅ መቅረዞች ምሥጢር ይህ ነው፤ ሰባቱ ከዋክብት የሰባቱ አብያተ ክርስቲያናት መላእክት ናቸው፤ ሰባቱም መቅረዞች ሰባቱ አብያተ ክርስቲያናት ናቸው።'),
  ('0ba04f8d-fe61-5777-af3d-4b4e8f6b1c36', '1a75346f-6ce3-58b3-af24-7173df066753', '4304a12e-8211-5607-aadd-be23c9cf9736', 1, 1, '“በኤፌሶን ወዳለው ወደ ቤተ ክርስቲያን መልአክ እንዲህ ብለህ ጻፍ፡ በቀኝ እጁ ሰባቱን ከዋክብት የያዘው በሰባቱም የወርቅ መቅረዞች መካከል የሚሄደው እንዲህ ይላል፦'),
  ('52e8c923-fb79-5512-a884-89f5fa5f1116', '1a75346f-6ce3-58b3-af24-7173df066753', '4304a12e-8211-5607-aadd-be23c9cf9736', 2, 2, '“ሥራህንና ድካምህን ትዕግሥትህንም አውቃለሁ፤ ክፉዎችንም ልትታገሥ እንዳትችል፥ እንዲሁም ሳይሆኑ ‘ሐዋርያት ነን’ የሚሉቱን መርምረህ ሐሰተኞች ሆነው እንዳገኘሃቸው አውቃለሁ፤'),
  ('b34af74e-ed7b-574f-a68e-c28d4f3821fc', '1a75346f-6ce3-58b3-af24-7173df066753', '4304a12e-8211-5607-aadd-be23c9cf9736', 3, 3, 'ታግሠህማል፤ ስለ ስሜም ብለህ ጸንተህ አልደከምህም።'),
  ('806cf806-b816-5703-ae86-487f5cfb992b', '1a75346f-6ce3-58b3-af24-7173df066753', '4304a12e-8211-5607-aadd-be23c9cf9736', 4, 4, 'ዳሩ ግን የምነቅፍብህ ነገር አለኝ፤ የቀደመውን ፍቅርህን ትተሃልና።'),
  ('c56f01d2-5d8d-5a54-a0e1-df6d922d3c1f', '1a75346f-6ce3-58b3-af24-7173df066753', '4304a12e-8211-5607-aadd-be23c9cf9736', 5, 5, 'እንግዲህ ከወዴት እንደ ወደቅህ አስብ፤ ንስሓም ግባ የቀደመውንም ሥራህን አድርግ፤ አለዚያ እመጣብሃለሁ ንስሓም ባትገባ መቅረዝህን ከስፍራው እወስዳለሁ።'),
  ('774fee4e-405c-5c3f-a8af-193489fe368a', '1a75346f-6ce3-58b3-af24-7173df066753', '4304a12e-8211-5607-aadd-be23c9cf9736', 6, 6, 'ነገር ግን ይህ አለህ፤ እኔ ደግሞ የምጠላውን የኒቆላውያንን ሥራ ጠልተሃልና።'),
  ('8d700ba7-6b25-5614-ad7a-d0933db63967', '1a75346f-6ce3-58b3-af24-7173df066753', '4304a12e-8211-5607-aadd-be23c9cf9736', 7, 7, 'መንፈስ ለአብያተ ክርስቲያናት የሚለውን ጆሮ ያለው ይስማ። ድል ለነሣው በእግዚአብሔር ገነት ካለው ከሕይወት ዛፍ እንዲበላ እሰጠዋለሁ።'),
  ('f2af2cd0-68e4-5966-a291-ca869ef37211', '1a75346f-6ce3-58b3-af24-7173df066753', '567516f5-fb09-5b7c-a1f7-e00b05f77270', 1, 8, '“በሰምርኔስም ወዳለው ወደ ቤተ ክርስቲያን መልአክ እንዲህ ብለህ ጻፍ፡ ሞቶ የነበረው ሕያውም የሆነው ፊተኛውና መጨረሻው እንዲህ ይላል፦'),
  ('0221ac59-83d7-517b-a123-04a63050a6f4', '1a75346f-6ce3-58b3-af24-7173df066753', '567516f5-fb09-5b7c-a1f7-e00b05f77270', 2, 9, '“መከራህንና ድህነትህን አውቃለሁ፤ ነገር ግን ባለ ጠጋ ነህ፤ የሰይጣንም ማኅበር ናቸው እንጂ አይሁድ ሳይሆኑ ‘አይሁድ ነን’ የሚሉት የሚሳደቡትን ስድብ አውቃለሁ።'),
  ('922df6a7-4f07-51ce-a243-fb4d2ccbf104', '1a75346f-6ce3-58b3-af24-7173df066753', '567516f5-fb09-5b7c-a1f7-e00b05f77270', 3, 10, 'ልትቀበለው ያለህን መከራ አትፍራ። እነሆ እንድፈተኑ ዲያብሎስ ከእናንተ አንዳንዶቻችሁን በወኅኒ ሊያገባችሁ አለው፤ ዐሥር ቀንም መከራን ትቀበላላችሁ። እስከሞት ድረስ የታመንህ ሁን የሕይወትንም አክሊል እሰጥሃለሁ።'),
  ('f9b190f8-c0e4-5253-a02c-0382e1909759', '1a75346f-6ce3-58b3-af24-7173df066753', '567516f5-fb09-5b7c-a1f7-e00b05f77270', 4, 11, 'መንፈስ ለአብያተ ክርስቲያናት የሚለውን ጆሮ ያለው ይስማ። ድል የነሣው በሁለተኛው ሞት አይጐዳም።'),
  ('ccff26a4-5000-5bed-abc8-c4b61f4bb7c9', '1a75346f-6ce3-58b3-af24-7173df066753', '4c8b71d8-74e6-5e4e-a0e2-de8b977a6613', 1, 12, '“በጴርጋሞንም ወዳለው ወደ ቤተ ክርስቲያን መልአክ እንዲህ ብለህ ጻፍ፡ በሁለት ወገን የተሳለ ስለታም ሰይፍ ያለው እንዲህ ይላል፦'),
  ('e0d5693a-d3d4-5520-afbd-251a4c84d442', '1a75346f-6ce3-58b3-af24-7173df066753', '4c8b71d8-74e6-5e4e-a0e2-de8b977a6613', 2, 13, '“የሰይጣን ዙፋን ባለበት የምትኖርበትን አውቃለሁ፤ ስሜንም ትጠብቃለህ፤ ሰይጣንም በሚኖርበት፥ በእናንተ ዘንድ የተገደለው የታመነው ምስክሬ አንቲጳስ በነበረበት ዘመን እንኳ ሃይማኖቴን አልካድህም።'),
  ('ca0eaf31-c716-5247-a483-c6a8edef538a', '1a75346f-6ce3-58b3-af24-7173df066753', '4c8b71d8-74e6-5e4e-a0e2-de8b977a6613', 3, 14, 'ዳሩ ግን ለጣዖት የታረደውን እንዲበሉና እንዲሴስኑ በእስራኤል ልጆች ፊት ማሰናከያን ሊያኖርባቸው ባላቅን ያስተማረ የበልዓምን ትምህርት የሚጠብቁ በዚያ ከአንተ ጋር ስላሉ፥ የምነቅፍብህ ጥቂት ነገር አለኝ።'),
  ('6d0bac1a-c28b-5e1e-a5be-4191a6019de9', '1a75346f-6ce3-58b3-af24-7173df066753', '4c8b71d8-74e6-5e4e-a0e2-de8b977a6613', 4, 15, 'እንዲሁ የኒቆላውያንን ትምህርት እንደ እነዚህ የሚጠብቁ ሰዎች ከአንተ ጋር ደግሞ አሉ።'),
  ('7671ffd3-6b1c-5c56-a295-6a9c4c2080c7', '1a75346f-6ce3-58b3-af24-7173df066753', '4c8b71d8-74e6-5e4e-a0e2-de8b977a6613', 5, 16, 'እንግዲህ ንስሓ ግባ፤ አለዚያ ፈጥኜ እመጣብሃለሁ፤ በአፌም ሰይፍ እዋጋቸዋለሁ።'),
  ('c37174e4-73f4-524b-acb7-3b71060502bd', '1a75346f-6ce3-58b3-af24-7173df066753', '4c8b71d8-74e6-5e4e-a0e2-de8b977a6613', 6, 17, 'መንፈስ ለአብያተ ክርስቲያናት የሚለውን ጆሮ ያለው ይስማ። ድል ለነሣው ከተሰወረ መና እሰጠዋለሁ፤ ነጭ ድንጋይንም እሰጠዋለሁ፤ በድንጋዩም ላይ ከተቀበለው በቀር አንድ ስንኳ የሚያውቀው የሌለ አዲስ ስም ተጽፎአል።'),
  ('35c4e8ca-92e0-51eb-afbd-dddb3686a916', '1a75346f-6ce3-58b3-af24-7173df066753', '140b2704-4e37-59a5-af46-af4e95cbae92', 1, 18, '“በትያጥሮንም ወዳለው ወደ ቤተ ክርስቲያን መልአክ እንዲህ ብለህ ጻፍ፡ እንደ እሳት ነበልባል የሆኑ ዐይኖች ያሉት በእቶንም የነጠረ የጋለ ናስ የሚመስሉ እግሮች ያሉት የእግዚአብሔር ልጅ እንዲህ ይላል፦'),
  ('95431548-0324-5dc5-aba3-e3b9b665472f', '1a75346f-6ce3-58b3-af24-7173df066753', '140b2704-4e37-59a5-af46-af4e95cbae92', 2, 19, '“ሥራህንና ፍቅርህን እምነትህንም አገልግሎትህንም ትዕግሥትህንም ከፊተኛውም ሥራህ ይልቅ የኋለኛው እንዲበዛ አውቃለሁ።'),
  ('ec9e7291-e353-5018-a19f-c05b33140d27', '1a75346f-6ce3-58b3-af24-7173df066753', '140b2704-4e37-59a5-af46-af4e95cbae92', 3, 20, 'ዳሩ ግን ‘ነቢይ ነኝ’ የምትለውን ባሪያዎቼንም እንዲሴስኑና ለጣዖት የታረደውን እንዲበሉ የምታስተምረውንና የምታስተውን ያችን ሴት ኤልዛቤልን ስለምትተዋት የምነቅፍብህ ነገር አለኝ፤'),
  ('f23cf3f1-c6df-56ac-a8d0-990eea0159e7', '1a75346f-6ce3-58b3-af24-7173df066753', '140b2704-4e37-59a5-af46-af4e95cbae92', 4, 21, 'ንስሓም እንድትገባ ጊዜ ሰጠኋት ከዝሙትዋም ንስሓ እንድትገባ አልወደደችም።'),
  ('f0b7f5a4-c830-5643-a730-a10afdc14bec', '1a75346f-6ce3-58b3-af24-7173df066753', '140b2704-4e37-59a5-af46-af4e95cbae92', 5, 22, 'እነሆ በአልጋ ላይ እጥላታለሁ፤ ከእርስዋም ጋር የሚያመነዝሩትን ከሥራዋ ንስሓ ባይገቡ በታላቅ መከራ እጥላቸዋለሁ፤'),
  ('11dbfc66-fc34-502b-a6e8-1ea844e4ce2e', '1a75346f-6ce3-58b3-af24-7173df066753', '140b2704-4e37-59a5-af46-af4e95cbae92', 6, 23, 'ልጆችዋንም በሞት እገድላቸዋለሁ፤ አብያተ ክርስቲያናትም ሁሉ ኵላሊትንና ልብን የምመረምር እኔ እንደ ሆንሁ ያውቃሉ፤ ለእያንዳንዳችሁም እንደ ሥራችሁ እሰጣችኋለሁ።'),
  ('122ab033-97dc-5e5c-aca7-6be59f8183f8', '1a75346f-6ce3-58b3-af24-7173df066753', '140b2704-4e37-59a5-af46-af4e95cbae92', 7, 24, 'ዳሩ ግን ይህን ትምህርት ለማትይዙ ሁሉ የሰይጣንንም ጥልቅ ነገር እነርሱ እንደሚሉት ለማታውቁ ለእናንተ በትያጥሮን ለቀራችሁት እላለሁ፤ ሌላ ሸክም አልጭንባችሁም፤'),
  ('ec6fed11-994d-59d8-a5a2-db7b4dc13925', '1a75346f-6ce3-58b3-af24-7173df066753', '140b2704-4e37-59a5-af46-af4e95cbae92', 8, 25, 'ነገር ግን እስክመጣ ድረስ ያላችሁን ጠብቁ።'),
  ('bd2df8ac-71f0-5f4a-aaca-e48df14e3dd1', '1a75346f-6ce3-58b3-af24-7173df066753', '140b2704-4e37-59a5-af46-af4e95cbae92', 9, 26, 'ድል ለነሣውና እስከ መጨረሻም ሥራዬን ለጠበቀው እኔ ደግሞ ከአባቴ እንደ ተቀበልሁ በአሕዛብ ላይ ሥልጣንን እሰጠዋለሁ፤ በብረትም በትር ይገዛቸዋል፤ እንደ ሸክላ ዕቃም ይቀጠቀጣሉ፤'),
  ('d00f9343-efe3-5af4-ad3d-20735f0b9243', '1a75346f-6ce3-58b3-af24-7173df066753', '140b2704-4e37-59a5-af46-af4e95cbae92', 10, 28, 'የንጋትንም ኮከብ እሰጠዋለሁ።'),
  ('e9012772-2391-5f60-ada5-1c30dc541228', '1a75346f-6ce3-58b3-af24-7173df066753', '140b2704-4e37-59a5-af46-af4e95cbae92', 11, 29, 'መንፈስ ለአብያተ ክርስቲያናት የሚለውን ጆሮ ያለው ይስማ።'),
  ('cc5abb6e-f0ef-5e5e-a2e7-afef2cd03f5e', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', '50397107-cd15-5925-a88a-dfedccd7114a', 1, 1, '“በሰርዴስም ወዳለው ወደ ቤተ ክርስቲያን መልአክ እንዲህ ብለህ ጻፍ፡ ሰባቱ የእግዚአብሔር መናፍስትና ሰባቱ ከዋክብት ያሉት እንዲህ ይላል “ሥራህን አውቃለሁ፤ ሕያው እንደ መሆንህ ስም አለህ፤ ሞተህማል።'),
  ('91ad9681-1ff7-5161-adbb-563e0f81a647', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', '50397107-cd15-5925-a88a-dfedccd7114a', 2, 2, 'ሥራህን በአምላኬ ፊት ፍጹም ሆኖ አላገኘሁትምና የነቃህ ሁን፤ ሊሞቱም ያላቸውን የቀሩትን ነገሮች አጽና።'),
  ('99a85e5d-69df-5298-aa28-ebb3e50d279e', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', '50397107-cd15-5925-a88a-dfedccd7114a', 3, 3, 'እንግዲህ እንዴት እንደ ተቀበልህና እንደ ሰማህ አስብ፤ ጠብቀውም፤ ንስሓም ግባ። እንግዲያስ ባትነቃ እንደ ሌባ እመጣብሃለሁ፤ በማናቸውም ሰዓት እንድመጣብህ ከቶ አታውቅም።'),
  ('bfe9b238-6b37-582c-a4bb-fc73ca3559e9', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', '50397107-cd15-5925-a88a-dfedccd7114a', 4, 4, 'ነገር ግን ልብሳቸውን ያላረከሱ በሰርዴስ ጥቂት ሰዎች ከአንተ ጋር አሉ፤ የተገባቸውም ስለ ሆኑ ነጭ ልብስ ለብሰው ከእኔ ጋር ይሄዳሉ።'),
  ('061eeaa3-358a-56aa-accf-4667e895746b', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', '50397107-cd15-5925-a88a-dfedccd7114a', 5, 5, 'ድል የነሣው እንዲሁ በነጭ ልብስ ይጐናጸፋል፤ ስሙንም ከሕይወት መጽሐፍ አልደመስስም፤ በአባቴና በመላእክቱም ፊት ለስሙ እመሰክርለታለሁ።'),
  ('847dea71-3816-5c61-aa5d-805a957e7ae1', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', '50397107-cd15-5925-a88a-dfedccd7114a', 6, 6, 'መንፈስ ለአብያተ ክርስቲያናት የሚለውን ጆሮ ያለው ይስማ።'),
  ('0225e1b0-e694-55d2-aea7-f20f07db0600', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', 'c822a1ce-5a43-5042-aba0-b7ec08510887', 1, 7, '“በፊላደልፊያም ወዳለው ወደ ቤተ ክርስቲያን መልአክ እንዲህ ብለህ ጻፍ፡ የዳዊት መክፈቻ ያለው፥ የሚከፍት፥ የሚዘጋም የሌለ፤ የሚዘጋ፥ የሚከፍትም የሌለ፤ ቅዱስና እውነተኛ የሆነው እርሱ እንዲህ ይላል፦'),
  ('e11b9e4c-651d-51ec-aec6-b6254307de3e', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', 'c822a1ce-5a43-5042-aba0-b7ec08510887', 2, 8, '“ሥራህን አውቃለሁ፤ እነሆ በአንተ ፊት የተከፈተ በር ሰጥቼአለሁ፤ ማንም ሊዘጋውም አይችልም፤ ኀይልህ ምንም ትንሽ ቢሆን ቃሌን ጠብቀሃልና፤ ስሜንም አልካድህምና።'),
  ('47abafd0-3232-5802-a879-47e60ecf7ea1', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', 'c822a1ce-5a43-5042-aba0-b7ec08510887', 3, 9, 'እነሆ አይሁድ ሳይሆኑ ‘አይሁድ ነን’ ከሚሉ ነገር ግን ከሚዋሹ ከሰይጣን ማኅበር አንዳንዶችን እሰጥሃለሁ፤ እነሆ መጥተው በእግሮችህ ፊት ይሰግዱ ዘንድ እኔም እንደ ወደድሁህ ያውቁ ዘንድ አደርጋቸዋለሁ።'),
  ('377492e7-b70c-5ea5-afcb-f3da94008ce5', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', 'c822a1ce-5a43-5042-aba0-b7ec08510887', 4, 10, 'የትዕግሥቴን ቃል ስለ ጠበቅህ እኔ ደግሞ በምድር የሚኖሩትን ይፈትናቸው ዘንድ በዓለም ሁሉ ላይ ሊመጣ ካለው ከፈተናው ሰዓት እጠብቅሃለሁ።'),
  ('d4efbe5d-967d-5832-a708-ebda2f42d004', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', 'c822a1ce-5a43-5042-aba0-b7ec08510887', 5, 11, 'እነሆ ቶሎ ብዬ እመጣለሁ፤ ማንም አክሊልህን እንዳይወስድብህ ያለህን አጽንተህ ያዝ።'),
  ('e2e0ef5a-9f33-5510-ae75-348d4022cfa5', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', 'c822a1ce-5a43-5042-aba0-b7ec08510887', 6, 12, 'ድል የነሣው በአምላኬ መቅደስ ዓምድ እንዲሆን አደርገዋለሁ፤ ወደ ፊትም ከዚያ ከቶ አይወጣም፤ የአምላኬን ስምና የአምላኬን ከተማ ስም፥ ማለት ከሰማይ ከአምላኬ ዘንድ የምትወርደውን አዲሲቱን ኢየሩሳሌምን፥ አዲሱንም ስሜን በእርሱ ላይ እጽፋለሁ።'),
  ('795ba4c2-3f39-5a0c-ae75-1b509a1c7ed0', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', 'c822a1ce-5a43-5042-aba0-b7ec08510887', 7, 13, 'መንፈስ ለአብያተ ክርስቲያናት የሚለውን ጆሮ ያለው ይስማ።'),
  ('af175ad4-4a4e-5198-a670-7fd3dc776821', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', '2d873884-8095-5926-a8c3-f783d5aec210', 1, 14, '“በሎዲቅያም ወዳለው ወደ ቤተ ክርስቲያን መልአክ እንዲህ ብለህ ጻፍ፡ አሜን የሆነው፥ የታመነውና እውነተኛው ምስክር፥ በእግዚአብሔርም ፍጥረት መጀመሪያ የነበረው እንዲህ ይላል፦'),
  ('d1dc2c43-72d7-5440-a744-4999fa47533d', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', '2d873884-8095-5926-a8c3-f783d5aec210', 2, 15, '“በራድ ወይም ትኩስ እንዳይደለህ ሥራህን አውቃለሁ። በራድ ወይም ትኩስ ብትሆንስ መልካም በሆነ ነበር።'),
  ('d96e1b32-a9d0-5167-abc0-21631b0b438f', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', '2d873884-8095-5926-a8c3-f783d5aec210', 3, 16, 'እንዲሁ ለብ ስላልህ በራድም ወይም ትኩስ ስላልሆንህ ከአፌ ልተፋህ ነው።'),
  ('007c3ee1-155d-5458-a4a4-9ff09e01cd40', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', '2d873884-8095-5926-a8c3-f783d5aec210', 4, 17, '‘ሀብታም ነኝና ባለጠጋ ሆኜአለሁ፤ አንድም ስንኳ አያስፈልገኝም፤’ የምትል ስለ ሆንህ፥ ጐስቋላና ምስኪንም ድሀም ዕውርም የተራቆትህም መሆንህን ስለማታውቅ፥'),
  ('cd838de9-451d-5069-a90d-ed774ab3ad64', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', '2d873884-8095-5926-a8c3-f783d5aec210', 5, 18, 'ባለ ጠጋ እንድትሆን በእሳት የነጠረውን ወርቅ፥ ተጐናጽፈህም የራቁትነትህ ኃፍረት እንዳይገለጥ ነጭ ልብስን፥ እንድታይም ዐይኖችህን የምትኳለውን ኵል ከእኔ ትገዛ ዘንድ እመክርሃለሁ።'),
  ('dc9e49bb-bb62-55f5-aaf6-a0eebba307b1', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', '2d873884-8095-5926-a8c3-f783d5aec210', 6, 19, 'እኔ የምወዳቸውን ሁሉ እገሥጻቸዋለሁ፤ እቀጣቸውማለሁ፤ እንግዲህ ቅና፤ ንስሓም ግባ።'),
  ('a8937b6f-e8fa-5378-aaae-0fc747045649', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', '2d873884-8095-5926-a8c3-f783d5aec210', 7, 20, 'እነሆ በደጅ ቆሜ አንኳኳለሁ፤ ማንም ድምፄን ቢሰማ ደጁንም ቢከፍትልኝ፥ ወደ እርሱ እገባለሁ፤ ከእርሱም ጋር እራት እበላለሁ፤ እርሱም ከእኔ ጋር ይበላል።'),
  ('e9222226-3deb-5435-aeae-8b0c4d3ff8cc', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', '2d873884-8095-5926-a8c3-f783d5aec210', 8, 21, 'እኔ ደግሞ ድል እንደ ነሣሁ ከአባቴም ጋር በዙፋኑ ላይ እንደተቀመጥሁ፥ ድል ለነሣው ከእኔ ጋር በዙፋኔ ላይ ይቀመጥ ዘንድ እሰጠዋለሁ።'),
  ('bc87432a-e18d-5e0c-a0d6-af11b3af2630', '95b2f5e1-f58d-5a16-ae8c-4455a0f11a42', '2d873884-8095-5926-a8c3-f783d5aec210', 9, 22, 'መንፈስ ለአብያተ ክርስቲያናት የሚለውን ጆሮ ያለው ይስማ።”'),
  ('8ffd3ce3-7808-5dcf-a6d2-c94bbd935fec', 'a2f7a87a-8993-58e6-aaab-e68f35ddec9a', 'd5a9ab61-70c7-58c4-a229-0a892965d81d', 1, 1, 'ከዚያ በኋላም አየሁ፤ እነሆም በሰማይ የተከፈተ ደጅ፥ እንደ መለከትም ሆኖ ሲናገረኝ የሰማሁት ፊተኛው ድምፅ “ወደዚህ ውጣና ከዚህ በኋላ ሊሆን የሚያስፈልገውን ነገር አሳይሃለሁ፤” አለ።'),
  ('a74ce861-5daf-5f17-acbd-657ba9bca46d', 'a2f7a87a-8993-58e6-aaab-e68f35ddec9a', 'd5a9ab61-70c7-58c4-a229-0a892965d81d', 2, 2, 'ወዲያው በመንፈስ ነበርሁ፤ እነሆም ዙፋን በሰማይ ቆሞአል፤ በዙፋኑም ላይ ተቀማጭ ነበረ፤'),
  ('b19e396c-bc9b-591e-a04b-324b0f7f6f70', 'a2f7a87a-8993-58e6-aaab-e68f35ddec9a', 'd5a9ab61-70c7-58c4-a229-0a892965d81d', 3, 3, 'ተቀምጦም የነበረው በመልኩ የኢያስጲድንና የሰርዲኖን ዕንቍ ይመስል ነበር። በመልኩም መረግድን የመሰለ ቀስተ ደመና በዙፋኑ ዙሪያ ነበረ።'),
  ('a87d362a-4353-57ff-a183-42a5d1706efa', 'a2f7a87a-8993-58e6-aaab-e68f35ddec9a', 'd5a9ab61-70c7-58c4-a229-0a892965d81d', 4, 4, 'በዙፋኑ ዙሪያም ሃያ አራት ዙፋኖች ነበሩ፤ በዙፋኖቹም ላይ ነጭ ልብስ ለብሰው በራሳቸውም የወርቅ አክሊል ደፍተው ሃያ አራት ሽማግሌዎች ተቀምጠው ነበር።'),
  ('ecd9aea3-89d3-53c7-a873-45ffe02243fd', 'a2f7a87a-8993-58e6-aaab-e68f35ddec9a', 'd5a9ab61-70c7-58c4-a229-0a892965d81d', 5, 5, 'ከዙፋኑም መብረቅና ድምፅ ነጐድጓድም ይወጣል፤ በዙፋኑም ፊት ሰባት የእሳት መብራቶች ይበሩ ነበር፤ እነርሱም ሰባቱ የእግዚአብሔር መናፍስት ናቸው።'),
  ('e5ccc8e3-adaa-5a08-a92e-4e22996d8b7e', 'a2f7a87a-8993-58e6-aaab-e68f35ddec9a', 'd5a9ab61-70c7-58c4-a229-0a892965d81d', 6, 6, 'በዙፋኑም ፊት ብርሌ የሚመስል የብርጭቆ ባሕር ነበረ። በዙፋኑም መካከል በዙፋኑም ዙሪያ፥ በፊትና በኋላ ዐይኖች የሞሉአቸው አራት እንስሶች ነበሩ።'),
  ('6d20e29d-4efa-5b40-ad47-9f8d0826931c', 'a2f7a87a-8993-58e6-aaab-e68f35ddec9a', 'd5a9ab61-70c7-58c4-a229-0a892965d81d', 7, 7, 'ፊተኛውም እንስሳ አንበሳን ይመስላል፤ ሁለተኛውም እንስሳ ጥጃን ይመስላል፤ ሦስተኛውም እንስሳ እንደ ሰው ፊት ነበረው፤ አራተኛውም እንስሳ የሚበረውን ንስር ይመስላል።'),
  ('964f39ab-bbc3-579f-a696-5b854755ed2f', 'a2f7a87a-8993-58e6-aaab-e68f35ddec9a', 'd5a9ab61-70c7-58c4-a229-0a892965d81d', 8, 8, 'አራቱም እንስሶች እያንዳንዳቸው ስድስት ክንፎች አሉአቸው፤ በዙሪያቸውና በውስጣቸውም ዐይኖች ሞልተውባቸዋል፤'),
  ('1fddeeb7-723b-5803-ae70-7628f4c978b0', '8cbccd00-25e4-50d5-aca7-b3c3f3d6d780', 'aec142b0-2a94-5899-a2fe-c6a7de4f0064', 1, 1, 'በዙፋኑ ላይም በተቀመጠው በቀኝ እጁ ላይ በውስጥና በኋላ የተጻፈበት በሰባትም ማኅተም የተዘጋ መጽሐፍን አየሁ።'),
  ('51c5adcb-d47d-57b8-a76d-9fbd8ca4a708', '8cbccd00-25e4-50d5-aca7-b3c3f3d6d780', 'aec142b0-2a94-5899-a2fe-c6a7de4f0064', 2, 2, 'ብርቱም መልአክ “መጽሐፉን ይዘረጋ ዘንድ ማኅተሞቹንም ይፈታ ዘንድ የሚገባው ማን ነው?” ብሎ በታላቅ ድምፅ ሲያውጅ አየሁ።'),
  ('6b27b6be-7907-5374-acd1-d7c549d3635d', '8cbccd00-25e4-50d5-aca7-b3c3f3d6d780', 'aec142b0-2a94-5899-a2fe-c6a7de4f0064', 3, 3, 'በሰማይም ቢሆን በምድርም ላይ ቢሆን ከምድርም በታች ቢሆን መጽሐፉን ሊዘረጋ ወይም ሊመለከተው ማንም አልተቻለውም።'),
  ('251b1bd3-8f73-5523-ad08-bf83148745d7', '8cbccd00-25e4-50d5-aca7-b3c3f3d6d780', 'aec142b0-2a94-5899-a2fe-c6a7de4f0064', 4, 4, 'መጽሐፉን ሊዘረጋ ወይም ሊመለከተው የሚገባው ማንም ስላልተገኘ እጅግ አለቀስሁ።'),
  ('6a7f3aa7-56a6-5b8e-a6b5-007c9545503a', '8cbccd00-25e4-50d5-aca7-b3c3f3d6d780', 'aec142b0-2a94-5899-a2fe-c6a7de4f0064', 5, 5, 'ከሽማግሌዎቹም አንዱ “አታልቅስ፤ እነሆ ከይሁዳ ነገድ የሆነው አንበሳ፥ እርሱም የዳዊት ሥር መጽሐፉን ይዘረጋ ዘንድ ሰባቱንም ማኅተም ይፈታ ዘንድ ድል ነሥቶአል፤” አለኝ።'),
  ('8bc20890-241a-50be-a971-8edd988c551f', '8cbccd00-25e4-50d5-aca7-b3c3f3d6d780', 'aec142b0-2a94-5899-a2fe-c6a7de4f0064', 6, 6, 'በዙፋኑና በአራቱ እንስሶች መካከልም በሽማግሌዎችም መካከል እንደ ታረደ በግ ቆሞ አየሁ፤ ሰባትም ቀንዶችና ሰባት ዐይኖች ነበሩት፤ እነርሱም ወደ ምድር ሁሉ የተላኩ የእግዚአብሔር መናፍስት ናቸው።'),
  ('5faaa0fd-5ff0-5c74-a666-7493df5432a4', '8cbccd00-25e4-50d5-aca7-b3c3f3d6d780', 'aec142b0-2a94-5899-a2fe-c6a7de4f0064', 7, 7, 'መጥቶም በዙፋን ላይ ከተቀመጠ ከዚያ ከቀኝ እጁ መጽሐፉን ወሰደው።'),
  ('db4e0f46-7e29-5a00-acb4-006a7cc2deae', '8cbccd00-25e4-50d5-aca7-b3c3f3d6d780', 'aec142b0-2a94-5899-a2fe-c6a7de4f0064', 8, 8, 'መጽሐፉንም በወሰደ ጊዜ አራቱ እንስሶችና ሃያ አራቱ ሽማግሌዎች በበጉ ፊት ወደቁ፤ እያንዳንዳቸውም በገናንና የቅዱሳን ጸሎት የሆነ ዕጣን የሞላበትን የወርቅ ዕቃ ያዙ።'),
  ('8cee02f4-04d1-535e-a67d-49009d5e1c69', '92c5a251-8327-55a2-a1b5-b9a2361f68e1', 'd0889706-eb31-564b-a00e-1dbf712e6534', 1, 1, 'በጉም ከሰባቱ ማኅተም አንዱን በፈታ ጊዜ አየሁ፤ ከአራቱም እንስሶች አንዱ ነጐድጓድ በሚመስል ድምፅ “መጥተህ እይ” ሲል ሰማሁ።'),
  ('7595e622-86d2-5129-a7e2-0cbfce865537', '92c5a251-8327-55a2-a1b5-b9a2361f68e1', 'd0889706-eb31-564b-a00e-1dbf712e6534', 2, 2, 'አየሁም፤ እነሆም አምባላይ ፈረስ ወጣ፤ በእርሱም ላይ የተቀመጠው ቀስት ነበረው፤ አክሊልም ተሰጠው፤ ድልም እየነሣ ወጣ፤ ድል ለመንሣት።'),
  ('390183f1-fdd7-57cc-ae1d-f7323d8dda64', '92c5a251-8327-55a2-a1b5-b9a2361f68e1', 'd0889706-eb31-564b-a00e-1dbf712e6534', 3, 3, 'ሁለተኛውንም ማኅተም በፈታ ጊዜ ሁለተኛው እንስሳ “መጥተህ እይ” ሲል ሰማሁ።')
